import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER' // Optional extension
}

export enum Currency {
  UAH = 'UAH',
  USD = 'USD',
  EUR = 'EUR'
}

export interface Account {
  id: string;
  name: string;
  currency: Currency;
  initialBalance: number;
  color: string;
}

export interface Category {
  id: string;
  name: string;
  type: TransactionType;
  icon: string;
  color: string;
}

export interface Transaction {
  id: string;
  date: string; // ISO string
  amount: number;
  currency: Currency;
  exchangeRate: number; // Rate relative to base currency (UAH). 1 for UAH.
  accountId: string;
  categoryId: string;
  note?: string;
  type: TransactionType;
}

export interface AppData {
  accounts: Account[];
  categories: Category[];
  transactions: Transaction[];
}

export const BASE_CURRENCY = Currency.UAH;

import { Account, AppData, Category, Currency, TransactionType } from './types';

