import { AppData } from '../types';
import { INITIAL_DATA } from '../constants';

const STORAGE_KEY = 'domfin_ua_data_v1';

export const saveToStorage = (data: AppData): void => {
  try {
    const json = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, json);
  } catch (e) {
    console.error('Failed to save data', e);
  }
};

export const loadFromStorage = (): AppData => {
  try {
    const json = localStorage.getItem(STORAGE_KEY);
    if (!json) return INITIAL_DATA;
    return JSON.parse(json);
  } catch (e) {
    console.error('Failed to load data', e);
    return INITIAL_DATA;
  }
};

export const exportDataToFile = (data: AppData) => {
  const jsonString = JSON.stringify(data, null, 2);
  const blob = new Blob([jsonString], { type: "application/json" });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = `budget_backup_${new Date().toISOString().split('T')[0]}.json`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const importDataFromFile = (file: File): Promise<AppData> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = event.target?.result as string;
        const data = JSON.parse(json);
        // Basic validation
        if (!data.transactions || !data.accounts) {
          throw new Error("Invalid format");
        }
        resolve(data);
      } catch (e) {
        reject(e);
      }
    };
    reader.readAsText(file);
  });
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyle = "px-4 py-2 rounded-lg font-medium transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100 flex items-center justify-center gap-2";

  const variants = {
    primary: "bg-primary text-white shadow-md shadow-emerald-200 hover:bg-emerald-600",
    secondary: "bg-white text-gray-700 border border-gray-300 hover:bg-gray-50",
    danger: "bg-danger text-white hover:bg-red-600",
    ghost: "bg-transparent text-gray-600 hover:bg-gray-100"
  };

  const widthClass = fullWidth ? "w-full" : "";

  return (
    <button 
      className={`${baseStyle} ${variants[variant]} ${widthClass} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
};

import React, { useMemo } from 'react';
import { Transaction, Account, Category, Currency, TransactionType } from '../types';
import { ArrowDownLeft, ArrowUpRight, Calendar, Search } from 'lucide-react';

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, 
  accounts, 
  categories,
  onDelete
}) => {
  const sortedTransactions = useMemo(() => {
    return [...transactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  if (transactions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-gray-400 p-8 text-center">
        <Search size={48} className="mb-4 opacity-20" />
        <p>Немає транзакцій. Додайте першу запис!</p>
      </div>
    );
  }

  return (
    <div className="pb-24 pt-4 px-4 space-y-4">
      {Object.entries(grouped).map(([date, items]) => (
        <div key={date} className="animate-fade-in">
          <div className="flex items-center gap-2 mb-2 sticky top-0 bg-background/95 backdrop-blur py-2 z-10">
            <Calendar size={14} className="text-gray-500" />
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
              {formatDate(date)}
            </h3>
          </div>
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
            {items.map(t => {
              const category = categories.find(c => c.id === t.categoryId);
              const account = accounts.find(a => a.id === t.accountId);
              const isExpense = t.type === TransactionType.EXPENSE;

              return (
                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 transition-colors relative group">
                  <div className="flex items-center gap-3">
                    <div 
                      className={`w-10 h-10 rounded-full flex items-center justify-center text-white text-lg shrink-0`}
                      style={{ backgroundColor: category?.color || '#ccc' }}
                    >
                      {/* Placeholder for icon mapping, using first letter for now */}
                      {category?.name[0]}
                    </div>
                    <div>
                      <div className="font-medium text-gray-900">{category?.name}</div>
                      <div className="text-xs text-gray-500 flex items-center gap-1">
                        <span className="max-w-[100px] truncate">{account?.name}</span>
                        {t.note && (
                            <>
                                <span>•</span>
                                <span className="italic truncate max-w-[120px]">{t.note}</span>
                            </>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className={`font-bold ${isExpense ? 'text-gray-900' : 'text-emerald-600'}`}>
                      {isExpense ? '-' : '+'}{t.amount.toLocaleString()} <span className="text-xs font-normal text-gray-500">{t.currency}</span>
                    </div>
                    {/* Only show delete button on long press or swipe in real native app. Here simple button on hover/focus for desktop, always visible details for mobile */}
                    <button 
                        onClick={(e) => { e.stopPropagation(); if(confirm('Видалити цей запис?')) onDelete(t.id); }}
                        className="absolute right-0 top-0 bottom-0 px-4 bg-red-500 text-white flex items-center opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                        ✕
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
};

import React from 'react';
import { Account, Transaction, TransactionType } from '../types';
import { Wallet, CreditCard, Banknote } from 'lucide-react';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ accounts, transactions }) => {
  const getBalance = (account: Account) => {
    const accountTransactions = transactions.filter(t => t.accountId === account.id);
    const totalIncome = accountTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);
    const totalExpense = accountTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    return account.initialBalance + totalIncome - totalExpense;
  };

  const totalBalanceInUAH = accounts.reduce((sum, acc) => {
      // Rough estimation for total balance header, assumes user knows their rates implicitly or we use last known rate.
      // For simplicity in this demo, we assume 1:1 if unknown, but practically 
      // we'd need a current rate service. We will skip the grand total conversion logic 
      // to avoid confusion without real rates, and just show list.
      return sum; 
  }, 0);

  return (
    <div className="pb-24 pt-4 px-4 space-y-4">
      <div className="grid grid-cols-1 gap-4">
        {accounts.map(account => {
          const balance = getBalance(account);
          return (
            <div key={account.id} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex flex-col justify-between relative overflow-hidden">
               <div 
                  className="absolute top-0 right-0 w-24 h-24 transform translate-x-8 -translate-y-8 rounded-full opacity-10"
                  style={{ backgroundColor: account.color }}
               />

               <div className="flex justify-between items-start mb-4 z-10">
                 <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-gray-50 text-gray-700">
                        {account.name.toLowerCase().includes('карт') ? <CreditCard size={20} /> : <Wallet size={20} />}
                    </div>
                    <div>
                        <h3 className="font-semibold text-gray-800">{account.name}</h3>
                        <p className="text-xs text-gray-500">Поточний баланс</p>
                    </div>
                 </div>
                 <div className="px-2 py-1 bg-gray-100 rounded text-xs font-bold text-gray-600">
                    {account.currency}
                 </div>
               </div>

               <div className="z-10">
                  <span className={`text-2xl font-bold tracking-tight ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                    {balance.toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </span>
                  <span className="text-sm font-medium text-gray-500 ml-1">{account.currency}</span>
               </div>
            </div>
          );
        })}
      </div>

      {/* Decorative Empty State if no accounts */}
      {accounts.length === 0 && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Transaction, Category, TransactionType, BASE_CURRENCY } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp } from 'lucide-react';

interface OverviewTabProps {
  transactions: Transaction[];
  categories: Category[];
}

export const OverviewTab: React.FC<OverviewTabProps> = ({ transactions, categories }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
    });
  }, [transactions, currentDate]);

  const stats = useMemo(() => {
    let income = 0;
    let expense = 0;
    const categoryTotals: { [key: string]: number } = {};

    filteredTransactions.forEach(t => {
      // Normalize to base currency (UAH) roughly using stored exchangeRate
      const amountInBase = t.amount * t.exchangeRate;

      if (t.type === TransactionType.INCOME) {
        income += amountInBase;
      } else if (t.type === TransactionType.EXPENSE) {
        expense += amountInBase;
        if (!categoryTotals[t.categoryId]) categoryTotals[t.categoryId] = 0;
        categoryTotals[t.categoryId] += amountInBase;
      }
    });

    const chartData = Object.entries(categoryTotals).map(([catId, amount]) => {
      const cat = categories.find(c => c.id === catId);
      return {
        name: cat?.name || 'Unknown',
        value: amount,
        color: cat?.color || '#ccc'
      };
    }).sort((a, b) => b.value - a.value);

    return { income, expense, chartData };
  }, [filteredTransactions, categories]);

  const balance = stats.income - stats.expense;

  return (
    <div className="pb-24 pt-4 px-4 space-y-6">
      {/* Date Control */}
      <div className="flex items-center justify-between bg-white p-2 rounded-xl shadow-sm">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-lg font-bold text-gray-800 capitalize">{periodLabel}</h2>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronRight size={20} />
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center">
           <span className="text-xs text-gray-500 uppercase font-semibold mb-1 flex items-center gap-1">
             <TrendingDown size={14} className="text-red-500" /> Витрати
           </span>
           <span className="text-xl font-bold text-gray-900">{stats.expense.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center">
           <span className="text-xs text-gray-500 uppercase font-semibold mb-1 flex items-center gap-1">
             <TrendingUp size={14} className="text-emerald-500" /> Доходи
           </span>
           <span className="text-xl font-bold text-emerald-600">+{stats.income.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴</span>
        </div>
      </div>

      {/* Balance Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex justify-between text-sm mb-2">
            <span className="text-gray-500">Залишок за період</span>
            <span className={`font-bold ${balance >= 0 ? 'text-primary' : 'text-danger'}`}>
                {balance > 0 ? '+' : ''}{balance.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
            </span>
        </div>
        <div className="h-2 w-full bg-gray-100 rounded-full overflow-hidden">
             {/* Simple visual bar showing expense ratio if income > 0 */}
             <div 
                className="h-full bg-primary" 
                style={{ width: stats.income > 0 ? `${Math.min((Math.max(0, balance) / stats.income) * 100, 100)}%` : '0%' }}
             />
        </div>
      </div>

      {/* Chart */}
      {stats.chartData.length > 0 ? (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 min-h-[300px]">
          <h3 className="font-semibold text-gray-700 mb-4">Структура витрат</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stats.chartData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {stats.chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip 
                    formatter={(value: number) => [`${value.toLocaleString()} ₴`, 'Сума']}
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 space-y-2">
              {stats.chartData.slice(0, 5).map((item, idx) => (
                  <div key={idx} className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2">
                          <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                          <span className="text-gray-700">{item.name}</span>
                      </div>
                      <span className="font-medium">{item.value.toLocaleString()} ₴</span>
                  </div>
              ))}
          </div>
        </div>
      ) : (
        <div className="text-center text-gray-400 py-10">
          <p>Немає даних про витрати за цей період</p>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Account, Category, Currency, Transaction, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X } from 'lucide-react';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Omit<Transaction, 'id'>) => void;
  accounts: Account[];
  categories: Category[];
}

export const AddTransactionModal: React.FC<AddTransactionModalProps> = ({
  isOpen, onClose, onSave, accounts, categories
}) => {
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountId, setAccountId] = useState(accounts[0]?.id || '');
  const [categoryId, setCategoryId] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [rate, setRate] = useState('1');
  const [note, setNote] = useState('');

  // Update default account if accounts change
  React.useEffect(() => {
     if (!accountId && accounts.length > 0) setAccountId(accounts[0].id);
  }, [accounts, accountId]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !accountId || !categoryId) return;

    onSave({
      date: new Date(date).toISOString(),
      amount: parseFloat(amount),
      currency: currency,
      exchangeRate: parseFloat(rate),
      accountId,
      categoryId,
      note,
      type
    });

    // Reset form mostly
    setAmount('');
    setNote('');
    onClose();
  };

  if (!isOpen) return null;

  const filteredCategories = categories.filter(c => c.type === type);
  const selectedAccount = accounts.find(a => a.id === accountId);

  // Auto-set currency based on account
  const handleAccountChange = (id: string) => {
    setAccountId(id);
    const acc = accounts.find(a => a.id === id);
    if (acc) {
        setCurrency(acc.currency);
        setRate(acc.currency === Currency.UAH ? '1' : ''); // Reset rate logic could be smarter
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">Нова транзакція</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        {/* Type Toggle */}
        <div className="flex p-1 bg-gray-100 rounded-lg mb-6">
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow text-red-500' : 'text-gray-500'}`}
                onClick={() => setType(TransactionType.EXPENSE)}
            >
                Витрата
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white shadow text-emerald-500' : 'text-gray-500'}`}
                onClick={() => setType(TransactionType.INCOME)}
            >
                Дохід
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">

            {/* Amount & Currency */}
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Сума</label>
                    <input 
                        type="number" 
                        step="0.01" 
                        required
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-lg font-bold"
                        placeholder="0.00"
                        autoFocus
                    />
                </div>
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Валюта</label>
                    <select 
                        value={currency}
                        onChange={(e) => setCurrency(e.target.value as Currency)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary font-medium"
                    >
                        {Object.values(Currency).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {/* Exchange Rate (Conditional) */}
            {currency !== Currency.UAH && (
                <div>
