import React, { useState, useEffect } from 'react';
import { Account, AccountType, Currency } from '../types';
import { Button } from './ui/Button';
import { X } from 'lucide-react';

interface AccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (account: Omit<Account, 'id'> | Account) => void;
  initialData?: Account;
}

const COLORS = ['#10b981', '#3b82f6', '#ef4444', '#f97316', '#8b5cf6', '#ec4899', '#000000', '#6b7280'];

export const AccountModal: React.FC<AccountModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [name, setName] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [initialBalance, setInitialBalance] = useState('0');
  const [type, setType] = useState<AccountType>(AccountType.CURRENT);
  const [color, setColor] = useState(COLORS[0]);
  const [currentRate, setCurrentRate] = useState('1');

  useEffect(() => {
    if (initialData) {
      setName(initialData.name);
      setCurrency(initialData.currency);
      setInitialBalance(initialData.initialBalance.toString());
      setType(initialData.type || AccountType.CURRENT);
      setColor(initialData.color);
      setCurrentRate(initialData.currentRate?.toString() || '1');
    } else {
      resetForm();
    }
  }, [initialData, isOpen]);

  const resetForm = () => {
    setName('');
    setCurrency(Currency.UAH);
    setInitialBalance('0');
    setType(AccountType.CURRENT);
    setColor(COLORS[0]);
    setCurrentRate('1');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const accountData = {
      name,
      currency,
      initialBalance: parseFloat(initialBalance),
      type,
      color,
      currentRate: parseFloat(currentRate)
    };

    if (initialData) {
      onSave({ ...accountData, id: initialData.id });
    } else {
      onSave(accountData);
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">{initialData ? 'Редагувати рахунок' : 'Новий рахунок'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Назва</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
              placeholder="Наприклад: Готівка"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1">Валюта</label>
              <select
                value={currency}
                onChange={(e) => {
                    const newCurr = e.target.value as Currency;
                    setCurrency(newCurr);
                    if (newCurr === Currency.UAH) setCurrentRate('1');
                }}
                className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
              >
                {Object.values(Currency).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1">Тип рахунку</label>
              <select
                value={type}
                onChange={(e) => setType(e.target.value as AccountType)}
                className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
              >
                <option value={AccountType.CURRENT}>Поточний</option>
                <option value={AccountType.SAVINGS}>Заощадження</option>
                <option value={AccountType.DEBT}>Заборгованість</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Початковий баланс</label>
                <input
                  type="number"
                  step="0.01"
                  value={initialBalance}
                  onChange={(e) => setInitialBalance(e.target.value)}
                  className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                />
             </div>
             <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Поточний курс до UAH</label>
                <input
                  type="number"
                  step="0.01"
                  value={currentRate}
                  disabled={currency === Currency.UAH}
                  onChange={(e) => setCurrentRate(e.target.value)}
                  className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary disabled:opacity-50"
                />
             </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Колір</label>
            <div className="flex flex-wrap gap-2">
              {COLORS.map(c => (
                <button
                  key={c}
                  type="button"
                  onClick={() => setColor(c)}
                  className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${color === c ? 'ring-2 ring-offset-2 ring-gray-400 scale-110' : ''}`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>

          <Button type="submit" fullWidth className="py-3 mt-4">
            Зберегти
          </Button>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType } from '../types';
import { Wallet, CreditCard, Banknote, Lock, LockOpen, Trash2, Pencil, Plus } from 'lucide-react';
import { Button } from './ui/Button';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, 
  transactions,
  onAddAccount,
  onEditAccount,
  onDeleteAccount
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const getBalance = (account: Account) => {
    const accountTransactions = transactions.filter(t => t.accountId === account.id);
    const totalIncome = accountTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);
    const totalExpense = accountTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    return account.initialBalance + totalIncome - totalExpense;
  };

  const groupAccounts = (type: AccountType) => {
    return accounts.filter(a => (a.type || AccountType.CURRENT) === type);
  };

  const renderAccountGroup = (title: string, type: AccountType) => {
    const group = groupAccounts(type);
    if (group.length === 0 && !isEditMode) return null;

    return (
      <div className="mb-6">
        <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1">{title}</h3>
        <div className="grid grid-cols-1 gap-4">
          {group.map(account => {
            const balance = getBalance(account);
            const balanceInUAH = account.currency !== Currency.UAH 
                ? balance * (account.currentRate || 1) 
                : null;

            return (
              <div key={account.id} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex flex-col justify-between relative overflow-hidden group">
                 {/* Background decoration */}
                 <div 
                    className="absolute top-0 right-0 w-24 h-24 transform translate-x-8 -translate-y-8 rounded-full opacity-10"
                    style={{ backgroundColor: account.color }}
                 />

                 <div className="flex justify-between items-start mb-4 z-10">
                   <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-gray-50 text-gray-700">
                          {account.name.toLowerCase().includes('карт') ? <CreditCard size={20} /> : <Wallet size={20} />}
                      </div>
                      <div>
                          <h3 className="font-semibold text-gray-800">{account.name}</h3>
                          <p className="text-xs text-gray-500">Поточний баланс</p>
                      </div>
                   </div>
                   <div className="px-2 py-1 bg-gray-100 rounded text-xs font-bold text-gray-600">
                      {account.currency}
                   </div>
                 </div>

                 <div className="z-10 flex items-baseline justify-between">
                    <div>
                        <span className={`text-2xl font-bold tracking-tight ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                            {balance.toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                        </span>
                        <span className="text-sm font-medium text-gray-500 ml-1">{account.currency}</span>
                    </div>
                    {balanceInUAH !== null && (
                        <div className="text-sm text-gray-400 font-medium">
                            ≈ {balanceInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
                        </div>
                    )}
                 </div>

                 {/* Edit Overlay */}
                 {isEditMode && (
                    <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-20 flex items-center justify-center gap-4 animate-fade-in">
                        <button 
                            onClick={() => onEditAccount(account)}
                            className="p-3 bg-blue-100 text-blue-600 rounded-full hover:bg-blue-200 shadow-sm"
                        >
                            <Pencil size={20} />
                        </button>
                        <button 
                            onClick={() => { if(confirm('Видалити цей рахунок та всі його транзакції?')) onDeleteAccount(account.id); }}
                            className="p-3 bg-red-100 text-red-600 rounded-full hover:bg-red-200 shadow-sm"
                        >
                            <Trash2 size={20} />
                        </button>
                    </div>
                 )}
              </div>
            );
          })}
          {isEditMode && (
              <button 
                onClick={onAddAccount}
                className="w-full py-4 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-400 hover:border-primary hover:text-primary transition-colors"
              >
                  <Plus size={24} className="mr-2" /> Додати рахунок
              </button>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-24 pt-4 px-4 relative min-h-full">
      {renderAccountGroup('Поточні', AccountType.CURRENT)}
      {renderAccountGroup('Заощадження', AccountType.SAVINGS)}
      {renderAccountGroup('Заборгованість', AccountType.DEBT)}

      {/* Empty State */}
      {accounts.length === 0 && !isEditMode && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}

      {/* Lock Button - Fixed Bottom Left */}
      <div className="fixed bottom-20 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { PieChart, List, Wallet, Plus, Settings, Download, Upload } from 'lucide-react';
import { AppData, Transaction, Account } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage, exportDataToFile, importDataFromFile } from './services/storageService';
import { OverviewTab } from './components/OverviewTab';
import { TransactionList } from './components/TransactionList';
import { AccountsTab } from './components/AccountsTab';
import { AddTransactionModal } from './components/AddTransactionModal';
import { AccountModal } from './components/AccountModal';

// Simple UUID generator fallback since we can't install packages freely
const generateId = () => Math.random().toString(36).substr(2, 9);

export default function App() {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'accounts'>('overview');
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [editingAccount, setEditingAccount] = useState<Account | undefined>(undefined);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // Load data on mount
  useEffect(() => {
    const loaded = loadFromStorage();
    // Migration for legacy data if needed (ensure accounts have types)
    if (loaded.accounts && !loaded.accounts[0]?.type) {
       // @ts-ignore
       loaded.accounts = loaded.accounts.map(a => ({...a, type: 'CURRENT', currentRate: 1}));
    }
    setData(loaded);
  }, []);

  // Auto-save on change
  useEffect(() => {
    saveToStorage(data);
  }, [data]);

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = {
      ...t,
      id: generateId()
    };
    setData(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTransaction]
    }));
  };

  const deleteTransaction = (id: string) => {
    setData(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
  };

  const saveAccount = (accountData: Omit<Account, 'id'> | Account) => {
    if ('id' in accountData) {
        // Edit existing
        setData(prev => ({
            ...prev,
            accounts: prev.accounts.map(a => a.id === accountData.id ? accountData as Account : a)
        }));
    } else {
        // Create new
        const newAccount: Account = {
            ...accountData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            accounts: [...prev.accounts, newAccount]
        }));
    }
  };

  const deleteAccount = (id: string) => {
    setData(prev => ({
        ...prev,
        accounts: prev.accounts.filter(a => a.id !== id),
        // Optionally delete transactions for this account, or keep them orphan? 
        // For safety, let's keep them but UI will show "Deleted Account" logic if we were robust. 
        // For this simple app, let's remove them to avoid crashes.
        transactions: prev.transactions.filter(t => t.accountId !== id)
    }));
  };

  const openAddAccount = () => {
    setEditingAccount(undefined);
    setIsAccountModalOpen(true);
  };

  const openEditAccount = (account: Account) => {
    setEditingAccount(account);
    setIsAccountModalOpen(true);
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const imported = await importDataFromFile(file);
        if(confirm('Це перезапише ваші поточні дані. Продовжити?')) {
            setData(imported);
            alert('Дані успішно імпортовано!');
        }
      } catch (err) {
        alert('Помилка імпорту файлу');
      }
    }
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 max-w-lg mx-auto shadow-2xl overflow-hidden relative border-x border-gray-200">

      {/* Header */}
      <header className="bg-white px-4 py-3 flex justify-between items-center shadow-sm z-20">
        <div className="flex items-center gap-2">
           <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center text-white font-bold">DF</div>
           <h1 className="font-bold text-gray-800 text-lg">DomFin UA</h1>
        </div>
        <div className="relative">
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="p-2 text-gray-600 hover:bg-gray-100 rounded-full">
                <Settings size={20} />
            </button>
            {isMenuOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-xl shadow-xl border border-gray-100 z-50 overflow-hidden animate-fade-in">
                    <button 
                        onClick={() => { exportDataToFile(data); setIsMenuOpen(false); }}
                        className="w-full text-left px-4 py-3 hover:bg-gray-50 text-sm flex items-center gap-2 text-gray-700"
                    >
                        <Download size={16} /> Експорт (JSON)
                    </button>
                    <label className="w-full text-left px-4 py-3 hover:bg-gray-50 text-sm flex items-center gap-2 text-gray-700 cursor-pointer border-t border-gray-50">
                        <Upload size={16} /> Імпорт (JSON)
                        <input type="file" accept=".json" className="hidden" onChange={handleImport} />
                    </label>
                </div>
            )}
            {/* Overlay to close menu */}
            {isMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsMenuOpen(false)} />}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto no-scrollbar relative">
        {activeTab === 'overview' && (
            <OverviewTab transactions={data.transactions} categories={data.categories} />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
            />
        )}
      </main>

      {/* FAB - Add Button (Only show on non-account tabs or if we want it global. 
          User asked for specific account controls in account tab, but standard transaction add should probably stay or hide?
          Usually FAB stays. Let's keep it global for adding transactions.) */}
      <div className="absolute bottom-20 right-4 z-30">
          <button 
            onClick={() => setIsTransactionModalOpen(true)}
            className="w-14 h-14 bg-primary rounded-full shadow-lg shadow-emerald-300 text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          >
              <Plus size={32} />
          </button>
      </div>

      {/* Bottom Navigation */}
      <nav className="bg-white border-t border-gray-200 pb-safe pt-2 px-6 flex justify-between items-center z-20 pb-4">
        <button 
            onClick={() => setActiveTab('overview')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors ${activeTab === 'overview' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <PieChart size={24} strokeWidth={activeTab === 'overview' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Огляд</span>
        </button>
        <button 
            onClick={() => setActiveTab('transactions')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors ${activeTab === 'transactions' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <List size={24} strokeWidth={activeTab === 'transactions' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Транзакції</span>
        </button>
        <button 
            onClick={() => setActiveTab('accounts')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors ${activeTab === 'accounts' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Wallet size={24} strokeWidth={activeTab === 'accounts' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Рахунки</span>
        </button>
      </nav>

      {/* Modals */}
      <AddTransactionModal 
        isOpen={isTransactionModalOpen} 
        onClose={() => setIsTransactionModalOpen(false)} 
        onSave={addTransaction}
        accounts={data.accounts}
        categories={data.categories}
      />

      <AccountModal 
        isOpen={isAccountModalOpen}
        onClose={() => setIsAccountModalOpen(false)}
        onSave={saveAccount}
        initialData={editingAccount}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType } from '../types';
