  );
}

import React, { useState, useEffect } from 'react';
import { Category, TransactionType } from '../types';
import { Button } from './ui/Button';
import { 
  X, ShoppingCart, Bus, Home, Film, Heart, Briefcase, Gift, 
  MoreHorizontal, Utensils, Car, Zap, Wifi, Smartphone, 
  Coffee, Book, Music, Dumbbell, Plane, PawPrint 
} from 'lucide-react';

interface CategoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (category: Omit<Category, 'id'> | Category) => void;
  initialData?: Category;
}

const COLORS = ['#ef4444', '#f97316', '#f59e0b', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#8b5cf6', '#ec4899', '#f43f5e', '#6b7280', '#000000'];

const ICONS: { [key: string]: React.ElementType } = {
  'shopping-cart': ShoppingCart,
  'bus': Bus,
  'home': Home,
  'film': Film,
  'heart': Heart,
  'briefcase': Briefcase,
  'gift': Gift,
  'utensils': Utensils,
  'car': Car,
  'zap': Zap,
  'wifi': Wifi,
  'smartphone': Smartphone,
  'coffee': Coffee,
  'book': Book,
  'music': Music,
  'dumbbell': Dumbbell,
  'plane': Plane,
  'paw-print': PawPrint,
  'more-horizontal': MoreHorizontal,
};

export const CategoryModal: React.FC<CategoryModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [monthlyBudget, setMonthlyBudget] = useState('0');
  const [color, setColor] = useState(COLORS[0]);
  const [icon, setIcon] = useState('shopping-cart');

  useEffect(() => {
    if (initialData) {
      setName(initialData.name);
      setType(initialData.type);
      setMonthlyBudget(initialData.monthlyBudget.toString());
      setColor(initialData.color);
      // Ensure the icon exists in our map, otherwise fallback
      setIcon(ICONS[initialData.icon] ? initialData.icon : 'shopping-cart');
    } else {
      resetForm();
    }
  }, [initialData, isOpen]);

  const resetForm = () => {
    setName('');
    setType(TransactionType.EXPENSE);
    setMonthlyBudget('0');
    setColor(COLORS[0]);
    setIcon('shopping-cart');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const categoryData = {
      name,
      type,
      icon, 
      color,
      monthlyBudget: parseFloat(monthlyBudget) || 0
    };

    if (initialData) {
      onSave({ ...categoryData, id: initialData.id });
    } else {
      onSave(categoryData);
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
