              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Account, Category, Currency, Transaction, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X, ArrowRightLeft } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Omit<Transaction, 'id'>) => void;
  accounts: Account[];
  categories: Category[];
}

export const AddTransactionModal: React.FC<AddTransactionModalProps> = ({
  isOpen, onClose, onSave, accounts, categories
}) => {
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountId, setAccountId] = useState(accounts[0]?.id || '');
  const [toAccountId, setToAccountId] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [rate, setRate] = useState('1');
  const [note, setNote] = useState('');

  // Update default account if accounts change
  React.useEffect(() => {
     if (!accountId && accounts.length > 0) setAccountId(accounts[0].id);
  }, [accounts, accountId]);

  // Reset category/toAccount when switching types
  React.useEffect(() => {
    setCategoryId('');
    if (type === TransactionType.TRANSFER && accounts.length > 1) {
        // Default to a different account than source if possible
        const target = accounts.find(a => a.id !== accountId);
        if (target) setToAccountId(target.id);
    }
  }, [type, accountId, accounts]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!amount || !accountId) return;
    if (type !== TransactionType.TRANSFER && !categoryId) return;
    if (type === TransactionType.TRANSFER && (!toAccountId || accountId === toAccountId)) {
        alert("Будь ласка, оберіть інший рахунок для зарахування");
        return;
    }

    onSave({
      date: new Date(date).toISOString(),
      amount: parseFloat(amount),
      currency: currency,
      exchangeRate: parseFloat(rate),
      accountId,
      toAccountId: type === TransactionType.TRANSFER ? toAccountId : undefined,
      categoryId: type === TransactionType.TRANSFER ? 'transfer' : categoryId, // Dummy ID for transfer
      note,
      type
    });

    // Reset form mostly
    setAmount('');
    setNote('');
    onClose();
  };

  if (!isOpen) return null;

  const filteredCategories = categories.filter(c => c.type === type);
  const selectedAccount = accounts.find(a => a.id === accountId);

  // Auto-set currency based on account
  const handleAccountChange = (id: string) => {
    setAccountId(id);
    const acc = accounts.find(a => a.id === id);
    if (acc) {
        setCurrency(acc.currency);
        setRate(acc.currency === Currency.UAH ? '1' : String(acc.currentRate));

        // If in transfer mode, ensure toAccount is not same
        if (type === TransactionType.TRANSFER && id === toAccountId) {
            setToAccountId('');
        }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">Нова транзакція</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        {/* Type Toggle */}
        <div className="flex p-1 bg-gray-100 rounded-lg mb-6">
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow text-red-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.EXPENSE)}
            >
                Витрата
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white shadow text-emerald-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.INCOME)}
            >
                Дохід
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.TRANSFER ? 'bg-white shadow text-blue-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.TRANSFER)}
            >
                Трансфер
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">

            {/* Amount & Currency */}
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Сума</label>
                    <input 
                        type="number" 
                        step="0.01" 
                        required
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-lg font-bold"
                        placeholder="0.00"
                        autoFocus
                    />
                </div>
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Валюта</label>
                    <select 
                        value={currency}
                        onChange={(e) => setCurrency(e.target.value as Currency)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary font-medium"
                    >
                        {Object.values(Currency).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {/* Exchange Rate (Conditional) */}
            {currency !== Currency.UAH && (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Курс до UAH</label>
                    <input 
                        type="number"
                        step="0.01"
                        value={rate}
                        onChange={(e) => setRate(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                        placeholder="Курс обміну"
                    />
                </div>
            )}

            {/* Account Selection */}
            {type === TransactionType.TRANSFER ? (
                <div className="flex items-center gap-2">
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">З рахунку</label>
                        <select 
                            value={accountId}
                            onChange={(e) => handleAccountChange(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            {accounts.map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                    <div className="pt-5 text-gray-400">
                        <ArrowRightLeft size={20} />
                    </div>
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">На рахунок</label>
                        <select 
                            value={toAccountId}
                            onChange={(e) => setToAccountId(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            <option value="">Оберіть...</option>
                            {accounts.filter(a => a.id !== accountId).map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                </div>
            ) : (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Рахунок</label>
                    <select 
                        value={accountId}
                        onChange={(e) => handleAccountChange(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                    >
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                        ))}
                    </select>
                </div>
            )}

            {/* Category (Hidden for Transfer) */}
            {type !== TransactionType.TRANSFER && (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Категорія</label>
                    <div className="grid grid-cols-3 gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {filteredCategories.map(c => (
                            <button
                                key={c.id}
                                type="button"
                                onClick={() => setCategoryId(c.id)}
                                className={`p-2 rounded-lg text-sm border transition-all flex flex-col items-center gap-1 ${categoryId === c.id ? 'border-primary bg-emerald-50 text-primary font-bold shadow-sm' : 'border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                            >
                                <div style={{ color: c.color }} className="mb-1">
                                    <CategoryIcon iconName={c.icon} size={24} />
                                </div>
                                <span className="truncate w-full text-center text-xs">{c.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Date */}
            <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Дата</label>
                <input 
                    type="date" 
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                />
            </div>

            {/* Note */}
            <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Примітка (опціонально)</label>
                <input 
                    type="text" 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                    placeholder="На що витрачено?"
                />
            </div>

            <Button type="submit" fullWidth className="py-4 mt-4 text-lg">
                Зберегти
            </Button>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Category, TransactionType } from '../types';
import { Lock, LockOpen, Plus, Trash2, Pencil, TrendingUp, TrendingDown } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface BudgetTabProps {
  categories: Category[];
  onAddCategory: () => void;
  onEditCategory: (category: Category) => void;
  onDeleteCategory: (id: string) => void;
}

export const BudgetTab: React.FC<BudgetTabProps> = ({ 
  categories, 
  onAddCategory, 
  onEditCategory, 
  onDeleteCategory 
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const renderCategoryGroup = (type: TransactionType, title: string, Icon: React.ElementType) => {
    const group = categories.filter(c => c.type === type);
    const totalBudget = group.reduce((sum, c) => sum + (c.monthlyBudget || 0), 0);

    return (
      <div className="mb-6 animate-fade-in">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                <Icon size={16} /> {title}
            </h3>
            <span className="text-sm font-bold text-gray-700">
                {totalBudget.toLocaleString('uk-UA')} ₴ / міс
            </span>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
          {group.map(category => (
            <div key={category.id} className="p-4 flex items-center justify-between group hover:bg-gray-50 transition-colors relative">
               <div className="flex items-center gap-3">
                  <div 
                    className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm"
                    style={{ backgroundColor: category.color }}
                  >
                    <CategoryIcon iconName={category.icon} size={20} />
                  </div>
                  <div>
                    <div className="font-medium text-gray-900">{category.name}</div>
                    <div className="text-xs text-gray-500">
                        {type === TransactionType.EXPENSE ? 'Ліміт:' : 'План:'} {category.monthlyBudget.toLocaleString()} ₴
                    </div>
                  </div>
               </div>

               {isEditMode && (
                   <div className="flex items-center gap-2">
                       <button 
                            onClick={() => onEditCategory(category)}
                            className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                        >
                            <Pencil size={16} />
                       </button>
                       <button 
                            onClick={() => {
                                if(window.confirm(`Видалити категорію "${category.name}"? Це не видалить існуючі транзакції, але вони втратять прив'язку до категорії.`)) {
                                    onDeleteCategory(category.id);
                                }
                            }}
                            className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                        >
                            <Trash2 size={16} />
                       </button>
                   </div>
               )}
            </div>
          ))}
          {group.length === 0 && (
              <div className="p-4 text-center text-gray-400 text-sm">
                  Список порожній
              </div>
          )}
          {isEditMode && (
              <button 
                onClick={onAddCategory}
                className="w-full p-3 flex items-center justify-center gap-2 text-primary font-medium hover:bg-emerald-50 transition-colors"
              >
                  <Plus size={18} /> Додати статтю
              </button>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-24 pt-4 px-4 min-h-full">
       {renderCategoryGroup(TransactionType.INCOME, 'Доходи', TrendingUp)}
       {renderCategoryGroup(TransactionType.EXPENSE, 'Витрати', TrendingDown)}

       {/* Lock Button - Fixed Bottom Left */}
      <div className="fixed bottom-20 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER' // Optional extension
}

export enum Currency {
  UAH = 'UAH',
  USD = 'USD',
  EUR = 'EUR'
}

export enum AccountType {
  CURRENT = 'CURRENT',
  DEBT = 'DEBT',
  SAVINGS = 'SAVINGS'
}

export interface Account {
  id: string;
  name: string;
  currency: Currency;
  initialBalance: number;
  color: string;
  type: AccountType;
  currentRate: number; // Current exchange rate to UAH for balance display
}

export interface Category {
  id: string;
  name: string;
  type: TransactionType;
  icon: string;
  color: string;
  monthlyBudget: number; // Planned amount per month
}

export interface Transaction {
  id: string;
  date: string; // ISO string
  amount: number;
  currency: Currency;
  exchangeRate: number; // Rate relative to base currency (UAH). 1 for UAH.
  accountId: string;
  toAccountId?: string; // Target account for transfers
  toAmount?: number; // Exact amount received in target account (for transfers)
  categoryId: string; // Optional for Transfer, strictly
  note?: string;
  type: TransactionType;
}

export interface AppData {
  accounts: Account[];
  categories: Category[];
  transactions: Transaction[];
}

export const BASE_CURRENCY = Currency.UAH;

import React, { useState, useEffect } from 'react';
import { Account, Category, Currency, Transaction, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X, ArrowRightLeft, AlertCircle } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Omit<Transaction, 'id'>) => void;
  accounts: Account[];
  categories: Category[];
}

export const AddTransactionModal: React.FC<AddTransactionModalProps> = ({
  isOpen, onClose, onSave, accounts, categories
}) => {
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [amount, setAmount] = useState('');
  const [toAmount, setToAmount] = useState(''); // New state for destination amount
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountId, setAccountId] = useState(accounts[0]?.id || '');
  const [toAccountId, setToAccountId] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [rate, setRate] = useState('1');
  const [note, setNote] = useState('');

  // Validation State
  const [validationError, setValidationError] = useState<string | null>(null);

  // Update default account if accounts change
  useEffect(() => {
     if (!accountId && accounts.length > 0) setAccountId(accounts[0].id);
  }, [accounts, accountId]);

  // Reset category/toAccount when switching types
  useEffect(() => {
    setCategoryId('');
    if (type === TransactionType.TRANSFER && accounts.length > 1) {
        // Default to a different account than source if possible
        const target = accounts.find(a => a.id !== accountId);
        if (target) setToAccountId(target.id);
    }
  }, [type, accountId, accounts]);

  const sourceAccount = accounts.find(a => a.id === accountId);
  const targetAccount = accounts.find(a => a.id === toAccountId);

  const isMultiCurrencyTransfer = type === TransactionType.TRANSFER && 
                                  sourceAccount && targetAccount && 
                                  sourceAccount.currency !== targetAccount.currency;

  // Real-time validation for Multi-Currency Transfers
  useEffect(() => {
    if (!isMultiCurrencyTransfer) {
        setValidationError(null);
        return;
    }

    const srcAmt = parseFloat(amount);
    const dstAmt = parseFloat(toAmount);
    const r = parseFloat(rate);

    if (!srcAmt || !dstAmt || !r) {
        // Don't show error while typing, just disable save potentially or wait
        setValidationError(null);
        return;
    }

    // Logic: 
    // If Source is UAH: SourceAmount should approx match TargetAmount * Rate
    // If Target is UAH: TargetAmount should approx match SourceAmount * Rate
    // If neither (Foreign -> Foreign): Simple check depends on rate definition, but usually user treats rate as relative to UAH or direct cross.
    // Let's assume standard Ukrainian behavior: Rate is always Price of Foreign Unit in UAH.

    let isValid = true;
    const threshold = 1.0; // Allow 1 unit difference for rounding

    if (sourceAccount?.currency === Currency.UAH) {
        // 4300 UAH -> 100 USD. Rate 43.
        // 4300 ~= 100 * 43
        if (Math.abs(srcAmt - (dstAmt * r)) > threshold) {
            isValid = false;
        }
    } else if (targetAccount?.currency === Currency.UAH) {
        // 100 USD -> 4100 UAH. Rate 41.
        // 4100 ~= 100 * 41
        if (Math.abs(dstAmt - (srcAmt * r)) > threshold) {
            isValid = false;
        }
    } else {
        // Foreign to Foreign (e.g. USD -> EUR). 
        // Logic depends on how user inputs rate. Let's rely on simple Source = Target * Rate check if user inputs rate that way.
        // We won't strictly block foreign-to-foreign logic mismatch as it's ambiguous, 
        // but we'll try: SourceAmount / TargetAmount = Rate
        const impliedRate = srcAmt / dstAmt;
        if (Math.abs(impliedRate - r) > 0.1) {
             // Maybe user meant Target/Source?
             const impliedRateInv = dstAmt / srcAmt;
             if (Math.abs(impliedRateInv - r) > 0.1) {
                 // isValid = false; // Too strict for cross-rates
             }
        }
    }

    if (!isValid) {
        setValidationError('Суми не відповідають вказаному курсу!');
    } else {
        setValidationError(null);
    }

  }, [amount, toAmount, rate, isMultiCurrencyTransfer, sourceAccount, targetAccount]);


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!amount || !accountId) return;
    if (type !== TransactionType.TRANSFER && !categoryId) return;
    if (type === TransactionType.TRANSFER) {
        if (!toAccountId || accountId === toAccountId) {
            alert("Будь ласка, оберіть інший рахунок для зарахування");
            return;
        }
        if (isMultiCurrencyTransfer) {
            if (!toAmount) {
                alert("Вкажіть суму зарахування");
                return;
            }
            if (validationError) {
                alert("Перевірте суми та курс. Розрахунок не сходиться.");
                return;
            }
        }
    }

    const finalRate = parseFloat(rate);

    // Determine the exchange rate to store for stats (relative to UAH)
    // If Source is UAH, rate is 1 (spent 4300 UAH).
    // If Source is USD, rate is likely the input rate (spent 100 USD * 41 = 4100 UAH value).
    let statsExchangeRate = 1;
    if (sourceAccount?.currency !== Currency.UAH) {
        statsExchangeRate = finalRate;
    }

    onSave({
      date: new Date(date).toISOString(),
      amount: parseFloat(amount),
      currency: currency,
      exchangeRate: statsExchangeRate,
      accountId,
      toAccountId: type === TransactionType.TRANSFER ? toAccountId : undefined,
      toAmount: (type === TransactionType.TRANSFER && toAmount) ? parseFloat(toAmount) : undefined,
      categoryId: type === TransactionType.TRANSFER ? 'transfer' : categoryId,
      note,
      type
    });

    // Reset form
    setAmount('');
    setToAmount('');
    setNote('');
    setValidationError(null);
    onClose();
  };

  if (!isOpen) return null;

  const filteredCategories = categories.filter(c => c.type === type);

  // Auto-set currency based on account
  const handleAccountChange = (id: string) => {
    setAccountId(id);
    const acc = accounts.find(a => a.id === id);
    if (acc) {
        setCurrency(acc.currency);

        // Default Rate Logic
        if (acc.currency === Currency.UAH) {
            setRate('1');
        } else {
            setRate(String(acc.currentRate));
        }

        // If in transfer mode, ensure toAccount is not same
        if (type === TransactionType.TRANSFER && id === toAccountId) {
            setToAccountId('');
        }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">Нова транзакція</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        {/* Type Toggle */}
        <div className="flex p-1 bg-gray-100 rounded-lg mb-6">
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow text-red-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.EXPENSE)}
            >
                Витрата
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white shadow text-emerald-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.INCOME)}
            >
                Дохід
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.TRANSFER ? 'bg-white shadow text-blue-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.TRANSFER)}
            >
                Трансфер
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">

            {/* Account Selection */}
            {type === TransactionType.TRANSFER ? (
                <div className="flex items-center gap-2">
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">З рахунку</label>
                        <select 
                            value={accountId}
                            onChange={(e) => handleAccountChange(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            {accounts.map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                    <div className="pt-5 text-gray-400">
                        <ArrowRightLeft size={20} />
                    </div>
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">На рахунок</label>
                        <select 
                            value={toAccountId}
                            onChange={(e) => setToAccountId(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            <option value="">Оберіть...</option>
                            {accounts.filter(a => a.id !== accountId).map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                </div>
            ) : (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Рахунок</label>
                    <select 
