        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
            />
        )}
        {activeTab === 'budget' && (
            <BudgetTab 
                categories={data.categories}
