    if ('id' in catData) {
        setData(prev => ({
            ...prev,
            categories: prev.categories.map(c => c.id === catData.id ? catData as Category : c)
        }));
    } else {
        const newCat: Category = {
            ...catData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            categories: [...prev.categories, newCat]
