           <h1 className="font-bold text-gray-800 text-lg">budget vs actual</h1>
        </div>
        <button onClick={() => setIsDataModalOpen(true)} className="p-2 text-gray-600 hover:bg-gray-100 rounded-full">
            <Settings size={20} />
        </button>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-hidden relative w-full">
        {activeTab === 'overview' && (
            <OverviewTab 
                transactions={data.transactions} 
                categories={data.categories}
                onCategoryClick={handleOverviewCategoryClick} 
            />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
                onEdit={openEditTransaction}
                initialFilters={transactionFilters}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
