import React, { useState } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote } from 'lucide-react';
import { Button } from './ui/Button';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, 
  transactions,
  onAddAccount,
  onEditAccount,
  onDeleteAccount,
  onSelectAccount
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const getBalance = (account: Account) => {
    // 1. Calculate transactions where this account is the primary source (Expense, Income to self, Transfer Out)
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);

    // 2. Calculate transactions where this account is the destination (Transfer In)
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);

    const totalIncome = sourceTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = sourceTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferOut = sourceTransactions
      .filter(t => t.type === TransactionType.TRANSFER)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferIn = destTransactions.reduce((sum, t) => {
        // If the transaction has a specific toAmount (manually entered multi-currency transfer), use it.
        if (t.toAmount !== undefined) {
            return sum + t.toAmount;
        }

        // Fallback: Convert Source Amount -> UAH -> Dest Amount using global rates
        // This is less accurate for past transactions if rates changed, but kept for backward compatibility
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = account.currentRate || 1; 
        const amountInDestCurrency = amountInUAH / destRate;
        return sum + amountInDestCurrency;
    }, 0);

    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const groupAccounts = (type: AccountType) => {
    return accounts.filter(a => (a.type || AccountType.CURRENT) === type);
  };

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        const balance = getBalance(account);
        // Convert to UAH approximation for total display
        const balanceInUAH = balance * (account.currentRate || 1);
        return sum + balanceInUAH;
    }, 0);
  };

  const renderAccountGroup = (title: string, type: AccountType) => {
    const group = groupAccounts(type);

    // Don't show empty groups unless in edit mode, but if in edit mode, show even if empty so we see structure
    if (group.length === 0 && !isEditMode) return null;

    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="mb-6">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">{title}</h3>
            <span className="text-sm font-bold text-gray-400">
                ≈ {totalInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
            </span>
        </div>

        <div className="grid grid-cols-1 gap-3">
          {group.map(account => {
            const balance = getBalance(account);
            const balanceInUAH = account.currency !== Currency.UAH 
                ? balance * (account.currentRate || 1) 
                : null;

            return (
              <div 
                key={account.id} 
                onClick={() => {
                    if (!isEditMode) onSelectAccount(account.id);
                }}
                className={`bg-white p-4 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden group ${!isEditMode ? 'cursor-pointer hover:shadow-md transition-shadow active:scale-[0.99] transition-transform' : ''}`}
              >
                 {/* Background decoration */}
                 <div 
                    className="absolute top-0 right-0 w-24 h-24 transform translate-x-8 -translate-y-8 rounded-full opacity-10"
                    style={{ backgroundColor: account.color }}
                 />

                 <div className="flex items-center justify-between relative z-10">
                   {/* Left Side: Icon & Name */}
                   <div className="flex items-center gap-3">
                      <div className="p-2.5 rounded-xl bg-gray-50 text-gray-700 shadow-sm">
                          <CategoryIcon iconName={account.icon || 'wallet'} size={22} />
                      </div>
                      <h3 className="font-bold text-gray-800 text-base">{account.name}</h3>
                   </div>

                   {/* Right Side: Balances */}
                   <div className="flex items-center gap-3 text-right">
                        {/* Secondary Balance (UAH) - Left of main balance */}
                        {balanceInUAH !== null && (
                            <div className="text-xs font-medium text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">
                                ≈ {balanceInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
                            </div>
                        )}

                        {/* Main Balance */}
                        <div className={`text-lg font-bold tracking-tight whitespace-nowrap ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                            {balance.toLocaleString('uk-UA', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}
                            <span className="text-sm font-medium text-gray-500 ml-1">{account.currency}</span>
                        </div>
                   </div>
                 </div>

                 {/* Edit Overlay */}
                 {isEditMode && (
                    <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-20 flex items-center justify-center gap-4 animate-fade-in transition-all">
                        <button 
                            onClick={(e) => { e.stopPropagation(); onEditAccount(account); }}
                            className="w-12 h-12 flex items-center justify-center bg-blue-100 text-blue-600 rounded-full hover:bg-blue-200 shadow-lg transform hover:scale-110 transition-all border border-blue-200"
                        >
                            <Pencil size={20} />
                        </button>
                        <button 
                            onClick={(e) => { 
                                e.stopPropagation(); 
                                if(window.confirm('Видалити цей рахунок та всі його транзакції?')) {
                                    onDeleteAccount(account.id);
                                }
                            }}
                            className="w-12 h-12 flex items-center justify-center bg-red-100 text-red-600 rounded-full hover:bg-red-200 shadow-lg transform hover:scale-110 transition-all border border-red-200"
                        >
                            <Trash2 size={20} />
                        </button>
                    </div>
                 )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 relative h-full overflow-y-auto no-scrollbar">
       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-2 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Рахунки</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

      {renderAccountGroup('Поточні', AccountType.CURRENT)}
      {renderAccountGroup('Заощадження', AccountType.SAVINGS)}
      {renderAccountGroup('Заборгованість', AccountType.DEBT)}

      {/* Single Add Button at the bottom */}
      {isEditMode && (
          <button 
            onClick={onAddAccount}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати рахунок
          </button>
      )}

      {/* Empty State (only if no accounts and not editing) */}
      {accounts.length === 0 && !isEditMode && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Category, TransactionType } from '../types';
import { Lock, LockOpen, Plus, Trash2, Pencil, TrendingUp, TrendingDown, ArrowUp, ArrowDown } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface BudgetTabProps {
  categories: Category[];
  onAddCategory: () => void;
  onEditCategory: (category: Category) => void;
  onDeleteCategory: (id: string) => void;
  onReorderCategories: (categories: Category[]) => void;
}

export const BudgetTab: React.FC<BudgetTabProps> = ({ 
  categories, 
  onAddCategory, 
  onEditCategory, 
  onDeleteCategory,
  onReorderCategories
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const moveCategory = (index: number, direction: 'up' | 'down', groupType: TransactionType) => {
    const income = categories.filter(c => c.type === TransactionType.INCOME);
    const expense = categories.filter(c => c.type === TransactionType.EXPENSE);

    // We only modify the group corresponding to the type
    const targetGroup = groupType === TransactionType.INCOME ? income : expense;

    if (direction === 'up') {
        if (index === 0) return;
        [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
    } else {
        if (index === targetGroup.length - 1) return;
         [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
    }

    // Combine back to form the full list (maintaining Income then Expense order, or vice versa)
    onReorderCategories([...income, ...expense]);
  };

  const renderCategoryGroup = (type: TransactionType, title: string, Icon: React.ElementType) => {
    const group = categories.filter(c => c.type === type);
    const totalBudget = group.reduce((sum, c) => sum + (c.monthlyBudget || 0), 0);

    return (
      <div className="mb-6 animate-fade-in">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                <Icon size={16} /> {title}
            </h3>
            <span className="text-sm font-bold text-gray-700">
                {totalBudget.toLocaleString('uk-UA')} UAH / міс
            </span>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
          {group.map((category, index) => (
            <div key={category.id} className="p-4 flex items-center justify-between group hover:bg-gray-50 transition-colors relative">
               {/* Left Side: Icon & Name */}
               <div className="flex items-center gap-3 overflow-hidden">
                  <div 
                    className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm"
                    style={{ backgroundColor: category.color }}
                  >
                    <CategoryIcon iconName={category.icon} size={20} />
                  </div>
                  <div className="font-bold text-gray-800 text-base truncate pr-2">
                    {category.name}
                  </div>
               </div>

               {/* Right Side: Amount & Controls */}
               <div className="flex items-center gap-3 shrink-0">
                   <div className="text-lg font-bold text-gray-900 whitespace-nowrap">
                        {category.monthlyBudget.toLocaleString('uk-UA')} <span className="text-sm font-medium text-gray-400 ml-1">UAH</span>
                   </div>

                   {isEditMode && (
                       <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200">
                           {/* Reorder Controls - Horizontal & Round */}
                           <div className="flex items-center gap-1 bg-gray-50 p-1 rounded-full border border-gray-100">
                               <button 
                                    onClick={() => moveCategory(index, 'up', type)}
                                    disabled={index === 0}
                                    className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowUp size={14} strokeWidth={2.5} />
                               </button>
                               <button 
                                    onClick={() => moveCategory(index, 'down', type)}
                                    disabled={index === group.length - 1}
                                    className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowDown size={14} strokeWidth={2.5} />
                               </button>
                           </div>

                           <button 
                                onClick={() => onEditCategory(category)}
                                className="w-9 h-9 flex items-center justify-center bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                            >
                                <Pencil size={16} />
                            </button>
                            <button 
                                onClick={() => {
                                    if(window.confirm(`Видалити категорію "${category.name}"? Це не видалить існуючі транзакції, але вони втратять прив'язку до категорії.`)) {
                                        onDeleteCategory(category.id);
                                    }
                                }}
                                className="w-9 h-9 flex items-center justify-center bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                            >
                                <Trash2 size={16} />
                            </button>
                       </div>
                   )}
               </div>
            </div>
          ))}
          {group.length === 0 && (
              <div className="p-4 text-center text-gray-400 text-sm">
                  Список порожній
              </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 h-full overflow-y-auto no-scrollbar">
       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-4 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Бюджет</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

       {renderCategoryGroup(TransactionType.INCOME, 'Доходи', TrendingUp)}
       {renderCategoryGroup(TransactionType.EXPENSE, 'Витрати', TrendingDown)}

       {/* Single Add Button at the bottom */}
       {isEditMode && (
          <button 
            onClick={onAddCategory}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати статтю
          </button>
      )}
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date; // Usually first day of the month
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, 
  accounts, 
  categories,
  onDelete,
  onEdit,
  initialFilters
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [showFilters, setShowFilters] = useState(true);

  // Filter States
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  // Apply initial filters when they change (navigation from other tabs)
  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      setShowFilters(true);
    }
  }, [initialFilters]);

  const resetFilters = () => {
    setFilterMonth(new Date());
    setFilterAccountId('');
    setFilterCategoryId('');
  };

  const prevMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);

      // 1. Filter by Date (Month)
      // Only apply month filter if we assume "budget view". 
      // Users might want to see "All time" for an account, but standard view is usually monthly.
      // Let's strictly follow the selected filterMonth.
      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && 
                        tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;

      // 2. Filter by Account
      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) {
        return false;
      }

      // 3. Filter by Category
      if (filterCategoryId && t.categoryId !== filterCategoryId) {
        return false;
      }

      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  return (
    <div className="h-full flex flex-col">
        {/* Filters Header */}
        <div className="bg-white border-b border-gray-200 px-4 py-3 shadow-sm z-20">
            {/* Month Selector */}
            <div className="flex items-center justify-between mb-3">
                 <button onClick={prevMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronLeft size={20} />
                 </button>
                 <span className="font-bold text-gray-800 capitalize">{monthLabel}</span>
                 <button onClick={nextMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronRight size={20} />
                 </button>
            </div>

            {/* Dropdowns */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <select 
                        value={filterAccountId}
                        onChange={(e) => setFilterAccountId(e.target.value)}
                        className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterAccountId ? 'bg-blue-50 border-blue-200 text-blue-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі рахунки</option>
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name}</option>
                        ))}
                    </select>
                </div>

                <div className="relative flex-1">
                    <select 
                        value={filterCategoryId}
                        onChange={(e) => setFilterCategoryId(e.target.value)}
                         className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterCategoryId ? 'bg-emerald-50 border-emerald-200 text-emerald-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі категорії</option>
                        {categories.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {(filterAccountId || filterCategoryId) && (
                    <button 
                        onClick={resetFilters}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        title="Скинути фільтри"
                    >
                        <X size={16} />
                    </button>
                )}
            </div>
        </div>

        {/* List Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar pb-32 px-4 pt-2">
            {sortedTransactions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400 text-center">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p>Транзакцій не знайдено за цими фільтрами.</p>
                    <button onClick={resetFilters} className="mt-4 text-primary text-sm font-medium hover:underline">
                        Скинути фільтри
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {Object.entries(grouped).map(([date, items]: [string, Transaction[]]) => (
                        <div key={date} className="animate-fade-in">
                        <div className="flex items-center gap-2 mb-2 sticky top-0 bg-background/95 backdrop-blur py-2 z-10">
                            <Calendar size={14} className="text-gray-500" />
                            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            {formatDate(date)}
                            </h3>
                        </div>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
                            {items.map(t => {
                            const category = categories.find(c => c.id === t.categoryId);
                            const account = accounts.find(a => a.id === t.accountId);
                            const toAccount = t.toAccountId ? accounts.find(a => a.id === t.toAccountId) : null;

                            const isExpense = t.type === TransactionType.EXPENSE;
                            const isTransfer = t.type === TransactionType.TRANSFER;

                            return (
                                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    {/* Icon Circle */}
                                    {isTransfer ? (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 bg-blue-500 shadow-sm">
                                        <CategoryIcon iconName="transfer" size={20} />
                                        </div>
                                    ) : (
                                        <div 
                                        className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm`}
                                        style={{ backgroundColor: category?.color || '#ccc' }}
                                        >
                                            <CategoryIcon iconName={category?.icon || 'help-circle'} size={20} />
                                        </div>
                                    )}

                                    {/* Text Info */}
                                    <div className="min-w-0 flex-1">
                                    <div className="font-semibold text-gray-900 truncate pr-2 text-sm">
                                        {isTransfer ? 'Переказ коштів' : (category?.name || 'Без категорії')}
                                    </div>
                                    <div className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                        {/* Account Info */}
                                        {isTransfer ? (
                                            <span className="truncate flex items-center gap-1">
                                                {account?.name} → {toAccount?.name}
                                            </span>
                                        ) : (
                                            <span className="truncate font-medium">{account?.name}</span>
                                        )}

                                        {/* Note */}
                                        {t.note && (
                                            <>
                                                <span className="shrink-0 text-gray-300">|</span>
                                                <span className="italic truncate text-gray-400">{t.note}</span>
                                            </>
                                        )}
                                    </div>
                                    </div>
                                </div>

                                {/* Amount & Actions */}
                                <div className="flex items-center gap-3 pl-2 shrink-0">
                                    <div className="text-right">
                                        {isTransfer && t.toAmount ? (
                                            <div className="flex flex-col items-end">
                                                <span className="text-red-500 font-bold text-sm">-{t.amount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {t.currency}</span>
                                                <span className="text-emerald-500 font-bold text-sm">+{t.toAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {toAccount?.currency}</span>
                                            </div>
                                        ) : (
                                            <div className={`font-bold text-base ${isTransfer ? 'text-blue-600' : isExpense ? 'text-gray-900' : 'text-emerald-600'}`}>
                                                {isTransfer ? '' : (isExpense ? '-' : '+')}
                                                {t.amount.toLocaleString(undefined, { minimumFractionDigits: 0 })} 
                                                <span className="text-xs font-normal text-gray-400 ml-1">{t.currency}</span>
                                            </div>
                                        )}
                                    </div>

                                    {isEditMode && (
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    onEdit(t);
                                                }}
                                                className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                                            >
                                                <Pencil size={16} />
                                            </button>
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    if(window.confirm('Видалити цей запис?')) {
                                                        onDelete(t.id);
                                                    }
                                                }}
                                                className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                                </div>
                            );
                            })}
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

      {/* Lock Button - Fixed Bottom Left */}
      <div className="fixed bottom-20 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Transaction, Category, TransactionType } from '../types';
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp, AlertCircle, ChevronRight as ChevronRightIcon } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface OverviewTabProps {
  transactions: Transaction[];
  categories: Category[];
  onCategoryClick: (categoryId: string, date: Date) => void;
}

export const OverviewTab: React.FC<OverviewTabProps> = ({ transactions, categories, onCategoryClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
    });
  }, [transactions, currentDate]);

  const stats = useMemo(() => {
    let income = 0;
    let expense = 0;
    const categoryTotals: { [key: string]: number } = {};

    filteredTransactions.forEach(t => {
      // Normalize to base currency (UAH) roughly using stored exchangeRate
      const amountInBase = t.amount * t.exchangeRate;

      if (t.type === TransactionType.INCOME) {
        income += amountInBase;
      } else if (t.type === TransactionType.EXPENSE) {
        expense += amountInBase;
        if (!categoryTotals[t.categoryId]) categoryTotals[t.categoryId] = 0;
        categoryTotals[t.categoryId] += amountInBase;
      }
    });

    // Merge with category definitions to include budget info even if 0 spent
    const expenseCategories = categories.filter(c => c.type === TransactionType.EXPENSE);
    const totalBudget = expenseCategories.reduce((sum, c) => sum + (c.monthlyBudget || 0), 0);

    const chartData = expenseCategories.map(cat => {
        const spent = categoryTotals[cat.id] || 0;
        return {
            id: cat.id,
            name: cat.name,
            value: spent,
            budget: cat.monthlyBudget || 0,
            color: cat.color,
            icon: cat.icon
        };
    }).sort((a, b) => b.value - a.value);

    return { income, expense, chartData, totalBudget };
  }, [filteredTransactions, categories]);

  const balance = stats.income - stats.expense;
  const budgetProgress = stats.totalBudget > 0 ? (stats.expense / stats.totalBudget) * 100 : 0;

  const getProgressColor = (percent: number) => {
      if (percent < 75) return 'bg-emerald-500';
      if (percent < 100) return 'bg-yellow-500';
      return 'bg-red-500';
  };

  return (
    <div className="pb-32 pt-4 px-4 space-y-6 h-full overflow-y-auto no-scrollbar">
      {/* Date Control */}
      <div className="flex items-center justify-between bg-white p-2 rounded-xl shadow-sm">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-lg font-bold text-gray-800 capitalize">{periodLabel}</h2>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronRight size={20} />
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center">
           <span className="text-xs text-gray-500 uppercase font-semibold mb-1 flex items-center gap-1">
             <TrendingDown size={14} className="text-red-500" /> Витрати
           </span>
           <span className="text-xl font-bold text-gray-900">{stats.expense.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center">
           <span className="text-xs text-gray-500 uppercase font-semibold mb-1 flex items-center gap-1">
             <TrendingUp size={14} className="text-emerald-500" /> Доходи
           </span>
           <span className="text-xl font-bold text-emerald-600">+{stats.income.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴</span>
        </div>
      </div>

      {/* Budget vs Actual Widget */}
      <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
         <div className="flex justify-between items-end mb-2">
             <h3 className="font-bold text-gray-800">Виконання бюджету</h3>
             <span className="text-xs text-gray-500">
                 {stats.expense.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} / {stats.totalBudget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
             </span>
         </div>
         <div className="h-4 w-full bg-gray-100 rounded-full overflow-hidden">
             <div 
                className={`h-full transition-all duration-500 ${getProgressColor(budgetProgress)}`}
                style={{ width: `${Math.min(budgetProgress, 100)}%` }}
             />
         </div>
         <div className="mt-2 text-right">
             <span className={`text-sm font-bold ${budgetProgress > 100 ? 'text-red-500' : 'text-gray-600'}`}>
                 {budgetProgress.toFixed(1)}%
             </span>
         </div>
      </div>

      {/* Detailed Spending List with Budget Bars */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100">
            <h3 className="font-semibold text-gray-700">Деталі по категоріям</h3>
          </div>
          <div className="divide-y divide-gray-50">
              {stats.chartData.map((item) => {
                  const percent = item.budget > 0 ? (item.value / item.budget) * 100 : 0;
                  // Show items if they have budget OR spending
                  if (item.budget === 0 && item.value === 0) return null;

                  return (
                      <div 
                        key={item.id} 
                        className="p-4 hover:bg-gray-50 cursor-pointer transition-colors active:bg-gray-100"
                        onClick={() => onCategoryClick(item.id, currentDate)}
                      >
                          <div className="flex justify-between text-sm mb-1.5">
                              <div className="flex items-center gap-2">
                                  <div className="w-5 h-5 rounded-full flex items-center justify-center text-white" style={{ backgroundColor: item.color }}>
                                     <CategoryIcon iconName={item.icon} size={12} />
                                  </div>
                                  <span className="text-gray-700 font-medium">{item.name}</span>
                              </div>
                              <div className="flex items-center gap-2">
                                <span className="text-gray-900 font-semibold">
                                    {item.value.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                                    <span className="text-gray-400 text-xs font-normal ml-1">
                                        / {item.budget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
                                    </span>
                                </span>
                                <ChevronRightIcon size={14} className="text-gray-300" />
                              </div>
                          </div>
                          <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                              <div 
                                  className={`h-full rounded-full ${getProgressColor(percent)}`}
                                  style={{ width: `${Math.min(percent, 100)}%` }}
                              />
                          </div>
                      </div>
                  );
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, Wallet, Plus, Settings, Calculator } from 'lucide-react';
import { AppData, Transaction, Account, Category } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage } from './services/storageService';
