                                        // Trigger standard file import logic from App
                                        const reader = new FileReader();
                                        reader.onload = (ev) => {
                                            const txt = ev.target?.result as string;
                                            setImportText(txt); // Put it in text area for preview
                                        };
                                        reader.readAsText(file);
                                    }
                                }}
                            />
                        </label>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote, ArrowUp, ArrowDown } from 'lucide-react';
import { Button } from './ui/Button';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  rates: Record<string, number>;
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
  onReorderAccounts: (accounts: Account[]) => void;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, 
  transactions,
  rates,
  onAddAccount,
  onEditAccount,
  onDeleteAccount,
  onSelectAccount,
  onReorderAccounts
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const getBalance = (account: Account) => {
    // 1. Calculate transactions where this account is the primary source (Expense, Income to self, Transfer Out)
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);

    // 2. Calculate transactions where this account is the destination (Transfer In)
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);

    const totalIncome = sourceTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = sourceTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferOut = sourceTransactions
      .filter(t => t.type === TransactionType.TRANSFER)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferIn = destTransactions.reduce((sum, t) => {
        // If the transaction has a specific toAmount (manually entered multi-currency transfer), use it.
        if (t.toAmount !== undefined) {
            return sum + t.toAmount;
        }

        // Fallback: Convert Source Amount -> UAH -> Dest Amount using global rates
        // This is less accurate for past transactions if rates changed, but kept for backward compatibility
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = rates[account.currency] || 1; 
        const amountInDestCurrency = amountInUAH / destRate;
        return sum + amountInDestCurrency;
    }, 0);

    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const groupAccounts = (type: AccountType) => {
    return accounts.filter(a => (a.type || AccountType.CURRENT) === type);
  };

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        const balance = getBalance(account);
        // Convert to UAH approximation using GLOBAL RATES from settings
        const rate = rates[account.currency] || 1;
        const balanceInUAH = balance * rate;
        return sum + balanceInUAH;
    }, 0);
  };

  const moveAccount = (index: number, direction: 'up' | 'down', groupType: AccountType) => {
      const current = groupAccounts(AccountType.CURRENT);
      const savings = groupAccounts(AccountType.SAVINGS);
      const debt = groupAccounts(AccountType.DEBT);

      // Determine which array we are modifying
      let targetGroup: Account[] = [];
      if (groupType === AccountType.CURRENT) targetGroup = current;
      if (groupType === AccountType.SAVINGS) targetGroup = savings;
      if (groupType === AccountType.DEBT) targetGroup = debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }

      // Reconstruct full list (order matters: Current -> Savings -> Debt)
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (title: string, type: AccountType) => {
    const group = groupAccounts(type);

    // Don't show empty groups unless in edit mode, but if in edit mode, show even if empty so we see structure
    if (group.length === 0 && !isEditMode) return null;

    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="mb-6 animate-fade-in">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">{title}</h3>
            <span className="text-sm font-bold text-gray-400">
                 {totalInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} UAH
            </span>
        </div>

        <div className="grid grid-cols-1 gap-3">
          {group.map((account, index) => {
            const balance = getBalance(account);
            // Use global rate for display calculation
            const currentRate = rates[account.currency] || 1;
            const balanceInUAH = account.currency !== Currency.UAH 
                ? balance * currentRate
                : null;

            // Generate a subtle background color and border color
            const bgColor = account.color + '10'; // 6% opacity roughly
            const borderColor = account.color;

            return (
              <div 
                key={account.id} 
                onClick={() => {
                    if (!isEditMode) onSelectAccount(account.id);
                }}
                className={`rounded-xl shadow-sm border border-gray-100 relative overflow-hidden group transition-all ${!isEditMode ? 'cursor-pointer hover:shadow-md active:scale-[0.99]' : ''}`}
                style={{ 
                    background: `linear-gradient(110deg, white 40%, ${bgColor} 100%)`,
                    borderLeft: `5px solid ${borderColor}`
                }}
              >
                 <div className="flex items-center justify-between p-4 relative z-10">
                   {/* Left Side: Icon & Name */}
                   <div className="flex items-center gap-3 overflow-hidden">
                      <div 
                        className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm"
                        style={{ backgroundColor: account.color }}
                      >
                          <CategoryIcon iconName={account.icon || 'wallet'} size={20} />
                      </div>
                      <div className="min-w-0">
                          <h3 className="font-bold text-gray-800 text-base truncate pr-2">{account.name}</h3>
                          {balanceInUAH !== null && (
                            <div className="text-xs font-medium text-gray-400 mt-0.5">
                                {balanceInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} UAH
                            </div>
                           )}
                      </div>
                   </div>

                   {/* Right Side: Balances or Controls */}
                   <div className="flex items-center gap-3 text-right shrink-0">
                        {isEditMode ? (
                           <div className="flex items-center gap-1 bg-white/50 backdrop-blur-sm p-1 rounded-full border border-gray-200 shadow-sm">
                               {/* Reorder Controls */}
                               <button 
                                    onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }}
                                    disabled={index === 0}
                                    className="w-8 h-8 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowUp size={16} strokeWidth={2.5} />
                               </button>
                               <button 
                                    onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }}
                                    disabled={index === group.length - 1}
                                    className="w-8 h-8 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowDown size={16} strokeWidth={2.5} />
                               </button>

                               <div className="w-px h-4 bg-gray-300 mx-1"></div>

                               <button 
                                    onClick={(e) => { e.stopPropagation(); onEditAccount(account); }}
                                    className="w-8 h-8 flex items-center justify-center text-blue-600 hover:bg-blue-50 rounded-full transition-colors"
                                >
                                    <Pencil size={16} />
                                </button>
                                <button 
                                    onClick={(e) => { 
                                        e.stopPropagation(); 
                                        if(window.confirm('Видалити цей рахунок та всі його транзакції?')) {
                                            onDeleteAccount(account.id);
                                        }
                                    }}
                                    className="w-8 h-8 flex items-center justify-center text-red-600 hover:bg-red-50 rounded-full transition-colors"
                                >
                                    <Trash2 size={16} />
                                </button>
                           </div>
                        ) : (
                            /* Main Balance Display */
                            <div className={`text-lg font-bold tracking-tight whitespace-nowrap ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                                {balance.toLocaleString('uk-UA', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}
                                <span className="text-sm font-medium text-gray-500 ml-1">{account.currency}</span>
                            </div>
                        )}
                   </div>
                 </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 relative h-full overflow-y-auto no-scrollbar">
       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-4 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Рахунки</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

      {renderAccountGroup('Поточні', AccountType.CURRENT)}
      {renderAccountGroup('Заощадження', AccountType.SAVINGS)}
      {renderAccountGroup('Заборгованість', AccountType.DEBT)}

      {/* Single Add Button at the bottom */}
      {isEditMode && (
          <button 
            onClick={onAddAccount}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати рахунок
          </button>
      )}

      {/* Empty State (only if no accounts and not editing) */}
      {accounts.length === 0 && !isEditMode && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Account, Category, Currency, Transaction, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X, ArrowRightLeft, AlertCircle, RefreshCw } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Omit<Transaction, 'id'> | Transaction) => void;
  accounts: Account[];
  categories: Category[];
  initialData?: Transaction;
  rates?: Record<string, number>;
}

export const AddTransactionModal: React.FC<AddTransactionModalProps> = ({
  isOpen, onClose, onSave, accounts, categories, initialData, rates
}) => {
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [amount, setAmount] = useState('');
  const [toAmount, setToAmount] = useState(''); // New state for destination amount
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountId, setAccountId] = useState(accounts[0]?.id || '');
  const [toAccountId, setToAccountId] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [rate, setRate] = useState('1');
  const [note, setNote] = useState('');

  // Validation State
  const [validationError, setValidationError] = useState<string | null>(null);

  // Initialize form with data
  useEffect(() => {
    if (isOpen) {
        if (initialData) {
            setType(initialData.type);
            setAmount(initialData.amount.toString());
            setDate(initialData.date.split('T')[0]);
            setAccountId(initialData.accountId);
            setCurrency(initialData.currency);
            setRate(initialData.exchangeRate.toString());
            setNote(initialData.note || '');

            if (initialData.type === TransactionType.TRANSFER) {
                setToAccountId(initialData.toAccountId || '');
                setToAmount(initialData.toAmount ? initialData.toAmount.toString() : '');
                setCategoryId('');
            } else {
                setCategoryId(initialData.categoryId);
                setToAccountId('');
                setToAmount('');
            }
        } else {
            // Reset for new
            setType(TransactionType.EXPENSE);
            setAmount('');
            setToAmount('');
            setDate(new Date().toISOString().split('T')[0]);

            // Set default account and currency/rate
            const defaultAcc = accounts[0];
            setAccountId(defaultAcc?.id || '');
            const defaultCurrency = defaultAcc?.currency || Currency.UAH;
            setCurrency(defaultCurrency);

            // Set rate from global rates if available, otherwise 1
            if (rates && defaultCurrency !== Currency.UAH) {
                setRate(rates[defaultCurrency]?.toString() || '1');
            } else {
                setRate('1');
            }

            setToAccountId('');
            setCategoryId('');
            setNote('');
        }
    }
  }, [isOpen, initialData, accounts, rates]);

  const sourceAccount = accounts.find(a => a.id === accountId);
  const targetAccount = accounts.find(a => a.id === toAccountId);

  const isMultiCurrencyTransfer = type === TransactionType.TRANSFER && 
                                  sourceAccount && targetAccount && 
                                  sourceAccount.currency !== targetAccount.currency;

  // Real-time validation for Multi-Currency Transfers
  useEffect(() => {
    if (!isMultiCurrencyTransfer) {
        setValidationError(null);
        return;
    }

    const srcAmt = parseFloat(amount);
    const dstAmt = parseFloat(toAmount);
    const r = parseFloat(rate);

    if (!srcAmt || !dstAmt || !r) {
        setValidationError(null);
        return;
    }

    let isValid = true;

    // Determine expected math based on direction
    const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;

    let calculatedDest = 0;

    if (isSell) {
        calculatedDest = srcAmt * r;
    } else {
        calculatedDest = srcAmt / r;
    }

    // Check deviation
    const diff = Math.abs(calculatedDest - dstAmt);
    // Allow small difference (e.g. 1 unit) due to rounding
    if (diff > 1.0) {
        isValid = false;
    }

    if (!isValid) {
        setValidationError('Суми не відповідають вказаному курсу');
    } else {
        setValidationError(null);
    }

  }, [amount, toAmount, rate, isMultiCurrencyTransfer, sourceAccount, targetAccount]);

  // --- Auto-Calculation Logic ---

  const handleAmountChange = (val: string) => {
      setAmount(val);
      if (isMultiCurrencyTransfer && rate && val) {
          const s = parseFloat(val);
          const r = parseFloat(rate);
          if (!isNaN(s) && !isNaN(r) && r !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              const newTo = isSell ? s * r : s / r;
              // Format to max 2 decimals, trim trailing zeros if needed for better UX
              setToAmount(parseFloat(newTo.toFixed(2)).toString());
          }
      }
  };

  const handleToAmountChange = (val: string) => {
      setToAmount(val);
      if (isMultiCurrencyTransfer && amount && val) {
          const s = parseFloat(amount);
          const d = parseFloat(val);
          if (!isNaN(s) && !isNaN(d) && d !== 0 && s !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              // If Sell: D = S * R => R = D / S
              // If Buy:  D = S / R => R = S / D
              const newRate = isSell ? d / s : s / d;
              setRate(parseFloat(newRate.toFixed(4)).toString());
          }
      }
  };

  const handleRateChange = (val: string) => {
      setRate(val);
      if (isMultiCurrencyTransfer && amount && val) {
          const s = parseFloat(amount);
          const r = parseFloat(val);
          if (!isNaN(s) && !isNaN(r) && r !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              const newTo = isSell ? s * r : s / r;
              setToAmount(parseFloat(newTo.toFixed(2)).toString());
          }
      }
  };


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!amount || !accountId) return;
    if (type !== TransactionType.TRANSFER && !categoryId) return;
    if (type === TransactionType.TRANSFER) {
        if (!toAccountId || accountId === toAccountId) {
            alert("Будь ласка, оберіть інший рахунок для зарахування");
            return;
        }
        if (isMultiCurrencyTransfer) {
            if (!toAmount) {
                alert("Вкажіть суму зарахування");
                return;
            }
            if (validationError) {
                if (!confirm("Суми не сходяться з курсом. Зберегти як є?")) {
                    return;
                }
            }
        }
    }

    const finalRate = parseFloat(rate);
    let statsExchangeRate = 1;
    if (sourceAccount?.currency !== Currency.UAH) {
        statsExchangeRate = finalRate;
    }

    const transactionData = {
      date: new Date(date).toISOString(),
      amount: parseFloat(amount),
      currency: currency,
      exchangeRate: statsExchangeRate,
      accountId,
      toAccountId: type === TransactionType.TRANSFER ? toAccountId : undefined,
      toAmount: (type === TransactionType.TRANSFER && toAmount) ? parseFloat(toAmount) : undefined,
      categoryId: type === TransactionType.TRANSFER ? 'transfer' : categoryId,
      note,
      type
    };

    if (initialData) {
        onSave({ ...transactionData, id: initialData.id });
    } else {
        onSave(transactionData);
    }

    // Reset form
    setAmount('');
    setToAmount('');
    setNote('');
    setValidationError(null);
    onClose();
  };

  if (!isOpen) return null;

  const filteredCategories = categories.filter(c => c.type === type);

  // Auto-set currency based on account (only if not editing or explicit change)
  const handleAccountChange = (id: string) => {
    setAccountId(id);
    const acc = accounts.find(a => a.id === id);
    if (acc) {
        setCurrency(acc.currency);

        // Default Rate Logic: Look up Global Rates first
        if (acc.currency === Currency.UAH) {
            setRate('1');
        } else {
            // Prioritize Global Rates passed via props
            if (rates && rates[acc.currency]) {
                setRate(rates[acc.currency].toString());
            } else {
                setRate(String(acc.currentRate)); // Fallback to account's historical rate
            }
        }

        // If in transfer mode, ensure toAccount is not same
        if (type === TransactionType.TRANSFER && id === toAccountId) {
            setToAccountId('');
        }
    }
  };

  const handleToAccountChange = (id: string) => {
      setToAccountId(id);
      // Auto-set rate if target is foreign and source is UAH
      const target = accounts.find(a => a.id === id);
      const source = accounts.find(a => a.id === accountId);

      if (source && target && source.currency === Currency.UAH && target.currency !== Currency.UAH) {
          if (rates && rates[target.currency]) {
               setRate(rates[target.currency].toString());
          } else {
               setRate(String(target.currentRate || 1));
          }
      }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">{initialData ? 'Редагувати транзакцію' : 'Нова транзакція'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        {/* Type Toggle */}
        <div className="flex p-1 bg-gray-100 rounded-lg mb-6">
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow text-red-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.EXPENSE)}
            >
                Витрата
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white shadow text-emerald-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.INCOME)}
            >
                Дохід
            </button>
            <button 
                type="button"
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.TRANSFER ? 'bg-white shadow text-blue-500' : 'text-gray-500 hover:text-gray-700'}`}
                onClick={() => setType(TransactionType.TRANSFER)}
            >
                Трансфер
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">

            {/* Account Selection */}
            {type === TransactionType.TRANSFER ? (
                <div className="flex items-center gap-2">
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">З рахунку</label>
                        <select 
                            value={accountId}
                            onChange={(e) => handleAccountChange(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            {accounts.map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                    <div className="pt-5 text-gray-400">
                        <ArrowRightLeft size={20} />
                    </div>
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-gray-500 mb-1">На рахунок</label>
                        <select 
                            value={toAccountId}
                            onChange={(e) => handleToAccountChange(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-sm"
                        >
                            <option value="">Оберіть...</option>
                            {accounts.filter(a => a.id !== accountId).map(a => (
                                <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                            ))}
                        </select>
                    </div>
                </div>
            ) : (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Рахунок</label>
                    <select 
                        value={accountId}
                        onChange={(e) => handleAccountChange(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                    >
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>
                        ))}
                    </select>
                </div>
            )}

            {/* Amounts Area */}
            {isMultiCurrencyTransfer ? (
                <div className={`p-4 rounded-xl space-y-3 border transition-colors ${validationError ? 'bg-red-50 border-red-200' : 'bg-blue-50 border-blue-100'}`}>
                    <div className="flex justify-between items-center text-xs font-medium">
                        <span className={validationError ? 'text-red-600' : 'text-blue-600'}>Обмін валют (Авторозрахунок)</span>
                    </div>

                    <div>
                        <label className="block text-xs text-gray-500 mb-1">Списання ({sourceAccount?.currency})</label>
                        <input 
                            type="number" 
                            step="0.01" 
                            required
                            value={amount}
                            onChange={(e) => handleAmountChange(e.target.value)}
                            className="w-full p-2 rounded-lg border border-white/50 bg-white focus:ring-2 focus:ring-primary shadow-sm"
                            placeholder="0.00"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <div className="h-px bg-gray-300 flex-1 opacity-50"></div>
                        <div className="text-xs text-gray-500 font-mono whitespace-nowrap">
                            Курс: 1 {sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH ? sourceAccount.currency : targetAccount?.currency} =
                        </div>
                        <input 
                            type="number" 
                            step="0.0001"
                            value={rate}
                            onChange={(e) => handleRateChange(e.target.value)}
                            className="w-24 p-1 text-center text-sm rounded border border-gray-200 bg-white font-bold text-gray-700"
                        />
                         <div className="text-xs text-gray-500 font-mono">
                            {sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH ? targetAccount.currency : sourceAccount?.currency}
                        </div>
                        <div className="h-px bg-gray-300 flex-1 opacity-50"></div>
                    </div>

                    <div>
                        <label className="block text-xs text-gray-500 mb-1">Зарахування ({targetAccount?.currency})</label>
                        <input 
                            type="number" 
                            step="0.01" 
                            required
                            value={toAmount}
                            onChange={(e) => handleToAmountChange(e.target.value)}
                             className="w-full p-2 rounded-lg border border-white/50 bg-white focus:ring-2 focus:ring-primary shadow-sm"
                            placeholder="0.00"
                        />
                    </div>

                    {validationError && (
                        <div className="flex items-start gap-2 text-xs text-red-600 mt-2 bg-white/50 p-2 rounded">
                            <AlertCircle size={14} className="mt-0.5 shrink-0" />
                            <span>{validationError}. Перевірте введені дані, або скоригуйте курс.</span>
                        </div>
                    )}
                </div>
            ) : (
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Сума</label>
                        <input 
                            type="number" 
                            step="0.01" 
                            required
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary text-lg font-bold"
                            placeholder="0.00"
                            autoFocus
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Валюта</label>
                        <select 
                            value={currency}
                            disabled={true} 
                            className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary font-medium opacity-75"
                        >
                            <option value={currency}>{currency}</option>
                        </select>
                    </div>
                </div>
            )}

            {/* Standard Exchange Rate (Non-Transfer or Same Currency logic fallback) */}
            {!isMultiCurrencyTransfer && currency !== Currency.UAH && (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Курс до UAH</label>
                    <input 
                        type="number"
                        step="0.01"
                        value={rate}
                        onChange={(e) => setRate(e.target.value)}
                        className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                        placeholder="Курс обміну"
                    />
                    {rates && rates[currency] && parseFloat(rate) !== rates[currency] && (
                        <div className="text-xs text-orange-500 mt-1 flex items-center gap-1">
                            <span>Глобальний курс: {rates[currency]}</span>
                            <button 
                                type="button" 
                                onClick={() => setRate(rates[currency]!.toString())}
                                className="underline hover:text-orange-600"
                            >
                                Використати
                            </button>
                        </div>
                    )}
                </div>
            )}

            {/* Category (Hidden for Transfer) */}
            {type !== TransactionType.TRANSFER && (
                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Категорія</label>
                    <div className="grid grid-cols-3 gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {filteredCategories.map(c => (
                            <button
                                key={c.id}
                                type="button"
                                onClick={() => setCategoryId(c.id)}
                                className={`p-2 rounded-lg text-sm border transition-all flex flex-col items-center gap-1 ${categoryId === c.id ? 'border-primary bg-emerald-50 text-primary font-bold shadow-sm' : 'border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                            >
                                <div style={{ color: c.color }} className="mb-1">
                                    <CategoryIcon iconName={c.icon} size={24} />
                                </div>
                                <span className="truncate w-full text-center text-xs">{c.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Date */}
            <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Дата</label>
                <input 
                    type="date" 
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                />
            </div>

            {/* Note */}
            <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">Примітка (опціонально)</label>
                <input 
                    type="text" 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
                    placeholder="На що витрачено?"
                />
            </div>

            <Button type="submit" fullWidth className="py-4 mt-4 text-lg">
                Зберегти
            </Button>
        </form>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date; // Usually first day of the month
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, 
  accounts, 
  categories,
  onDelete,
  onEdit,
  initialFilters
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [showFilters, setShowFilters] = useState(true);

  // Filter States
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  // Apply initial filters when they change (navigation from other tabs)
  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      setShowFilters(true);
    }
  }, [initialFilters]);

  const resetFilters = () => {
    setFilterMonth(new Date());
    setFilterAccountId('');
    setFilterCategoryId('');
  };

  const prevMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);

      // 1. Filter by Date (Month)
      // Only apply month filter if we assume "budget view". 
      // Users might want to see "All time" for an account, but standard view is usually monthly.
      // Let's strictly follow the selected filterMonth.
      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && 
                        tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;

      // 2. Filter by Account
      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) {
        return false;
      }

      // 3. Filter by Category
      if (filterCategoryId && t.categoryId !== filterCategoryId) {
        return false;
      }

      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  return (
    <div className="h-full flex flex-col">
        {/* Filters Header */}
        <div className="bg-white border-b border-gray-200 px-4 py-3 shadow-sm z-20">
            {/* Month Selector */}
            <div className="flex items-center justify-between mb-3">
                 <button onClick={prevMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronLeft size={20} />
                 </button>
                 <span className="font-bold text-gray-800 capitalize">{monthLabel}</span>
                 <button onClick={nextMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronRight size={20} />
                 </button>
            </div>

            {/* Dropdowns */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <select 
                        value={filterAccountId}
                        onChange={(e) => setFilterAccountId(e.target.value)}
                        className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterAccountId ? 'bg-blue-50 border-blue-200 text-blue-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі рахунки</option>
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name}</option>
                        ))}
                    </select>
                </div>

                <div className="relative flex-1">
                    <select 
                        value={filterCategoryId}
                        onChange={(e) => setFilterCategoryId(e.target.value)}
                         className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterCategoryId ? 'bg-emerald-50 border-emerald-200 text-emerald-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі категорії</option>
                        {categories.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {(filterAccountId || filterCategoryId) && (
                    <button 
                        onClick={resetFilters}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        title="Скинути фільтри"
                    >
                        <X size={16} />
                    </button>
                )}
            </div>
        </div>

        {/* List Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar pb-32 px-4 pt-2">
            {sortedTransactions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400 text-center">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p>Транзакцій не знайдено за цими фільтрами.</p>
                    <button onClick={resetFilters} className="mt-4 text-primary text-sm font-medium hover:underline">
                        Скинути фільтри
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {Object.entries(grouped).map(([date, items]: [string, Transaction[]]) => (
                        <div key={date} className="animate-fade-in">
                        <div className="flex items-center gap-2 mb-2 sticky top-0 bg-background/95 backdrop-blur py-2 z-10">
                            <Calendar size={14} className="text-gray-500" />
                            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            {formatDate(date)}
                            </h3>
                        </div>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
                            {items.map(t => {
                            const category = categories.find(c => c.id === t.categoryId);
                            const account = accounts.find(a => a.id === t.accountId);
                            const toAccount = t.toAccountId ? accounts.find(a => a.id === t.toAccountId) : null;

                            const isExpense = t.type === TransactionType.EXPENSE;
                            const isTransfer = t.type === TransactionType.TRANSFER;

                            // Determine visual style
                            let amountClass = 'text-gray-900';
                            let sign = '';
                            const absAmount = Math.abs(t.amount);

                            if (isTransfer) {
                                amountClass = 'text-blue-600';
                            } else if (isExpense) {
                                if (t.amount < 0) {
                                    // Storno/Refund (Negative Expense) -> Green +
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                } else {
                                    // Normal Expense -> Gray -
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                }
                            } else {
                                // Income
                                if (t.amount < 0) {
                                    // Negative Income (Correction) -> Gray -
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                } else {
                                    // Normal Income -> Green +
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                }
                            }

                            return (
                                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    {/* Icon Circle */}
                                    {isTransfer ? (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 bg-blue-500 shadow-sm">
                                        <CategoryIcon iconName="transfer" size={20} />
                                        </div>
                                    ) : (
                                        <div 
                                        className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm`}
                                        style={{ backgroundColor: category?.color || '#ccc' }}
                                        >
                                            <CategoryIcon iconName={category?.icon || 'help-circle'} size={20} />
                                        </div>
                                    )}

                                    {/* Text Info */}
                                    <div className="min-w-0 flex-1">
                                    <div className="font-semibold text-gray-900 truncate pr-2 text-sm">
                                        {isTransfer ? 'Переказ коштів' : (category?.name || 'Без категорії')}
                                    </div>
                                    <div className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                        {/* Account Info */}
                                        {isTransfer ? (
                                            <span className="truncate flex items-center gap-1">
                                                {account?.name} → {toAccount?.name}
                                            </span>
                                        ) : (
                                            <span className="truncate font-medium">{account?.name}</span>
                                        )}

                                        {/* Note */}
                                        {t.note && (
                                            <>
                                                <span className="shrink-0 text-gray-300">|</span>
                                                <span className="italic truncate text-gray-400">{t.note}</span>
                                            </>
                                        )}
                                    </div>
                                    </div>
                                </div>

                                {/* Amount & Actions */}
                                <div className="flex items-center gap-3 pl-2 shrink-0">
                                    <div className="text-right">
                                        {isTransfer && t.toAmount ? (
                                            <div className="flex flex-col items-end">
                                                <span className="text-red-500 font-bold text-sm">-{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {t.currency}</span>
                                                <span className="text-emerald-500 font-bold text-sm">+{t.toAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {toAccount?.currency}</span>
                                            </div>
                                        ) : (
                                            <div className={`font-bold text-base ${amountClass}`}>
                                                {sign}{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} 
                                                <span className="text-xs font-normal text-gray-400 ml-1">{t.currency}</span>
                                            </div>
                                        )}
                                    </div>

                                    {isEditMode && (
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    onEdit(t);
                                                }}
                                                className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                                            >
                                                <Pencil size={16} />
                                            </button>
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    if(window.confirm('Видалити цей запис?')) {
                                                        onDelete(t.id);
                                                    }
                                                }}
                                                className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                                </div>
                            );
                            })}
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

      {/* Lock Button - Fixed Bottom Left */}
      <div className="fixed bottom-20 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER' // Optional extension
}

export enum Currency {
  UAH = 'UAH',
  USD = 'USD',
  EUR = 'EUR'
}

export enum AccountType {
  CURRENT = 'CURRENT',
  DEBT = 'DEBT',
  SAVINGS = 'SAVINGS'
}

export interface Account {
  id: string;
  name: string;
  currency: Currency;
  initialBalance: number;
  color: string;
  icon: string; // Icon name from CategoryIcon map
  type: AccountType;
  currentRate: number; // Legacy, but kept for compatibility. UI now prefers AppData.rates
  isHidden?: boolean; // New property for visibility toggle
}

export interface Category {
  id: string;
  name: string;
  type: TransactionType;
  icon: string;
  color: string;
  monthlyBudget: number; // Planned amount per month
}

export interface Transaction {
  id: string;
  date: string; // ISO string
  amount: number;
  currency: Currency;
  exchangeRate: number; // Rate relative to base currency (UAH). 1 for UAH.
  accountId: string;
  toAccountId?: string; // Target account for transfers
  toAmount?: number; // Exact amount received in target account (for transfers)
  categoryId: string; // Optional for Transfer, strictly
  note?: string;
  type: TransactionType;
}

export interface AppData {
  accounts: Account[];
  categories: Category[];
  transactions: Transaction[];
  rates: Record<string, number>; // Global exchange rates (e.g., "USD": 41.5)
}

export const BASE_CURRENCY = Currency.UAH;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, Wallet, Plus, Settings, Calculator } from 'lucide-react';
import { AppData, Transaction, Account, Category } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage } from './services/storageService';
import { OverviewTab } from './components/OverviewTab';
import { TransactionList, TransactionFilters } from './components/TransactionList';
import { AccountsTab } from './components/AccountsTab';
import { BudgetTab } from './components/BudgetTab';
import { AddTransactionModal } from './components/AddTransactionModal';
import { AccountModal } from './components/AccountModal';
import { CategoryModal } from './components/CategoryModal';
import { DataManagementModal } from './components/DataManagementModal';

// Simple UUID generator fallback since we can't install packages freely
const generateId = () => Math.random().toString(36).substr(2, 9);

export default function App() {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'accounts' | 'budget'>('overview');
  const [data, setData] = useState<AppData>(INITIAL_DATA);

  // Navigation & Filtering State
  const [transactionFilters, setTransactionFilters] = useState<TransactionFilters | null>(null);

  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);

  const [editingAccount, setEditingAccount] = useState<Account | undefined>(undefined);
  const [editingCategory, setEditingCategory] = useState<Category | undefined>(undefined);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | undefined>(undefined);

  // Load data on mount
  useEffect(() => {
    const loaded = loadFromStorage();

    // Migration: ensure rates exist
    if (!loaded.rates) {
        loaded.rates = INITIAL_DATA.rates;
    }

    // Migration: ensure accounts have types and icons
    if (loaded.accounts) {
       loaded.accounts = loaded.accounts.map(a => {
           let updated = { ...a };
           // @ts-ignore
           if (!updated.type) updated.type = 'CURRENT';
           if (!updated.currentRate) updated.currentRate = 1;
           if (!updated.icon) {
               // Heuristic for migration
               const nameLower = updated.name.toLowerCase();
               if (nameLower.includes('карт') || nameLower.includes('card')) updated.icon = 'credit-card';
               else if (nameLower.includes('банк') || nameLower.includes('bank')) updated.icon = 'landmark';
               else if (nameLower.includes('usd') || nameLower.includes('eur')) updated.icon = 'banknote';
               else updated.icon = 'wallet';
           }
           return updated as Account;
       });
    }

    // Migration for categories (ensure monthlyBudget exists)
    if(loaded.categories) {
        loaded.categories = loaded.categories.map(c => ({
            ...c,
            monthlyBudget: c.monthlyBudget !== undefined ? c.monthlyBudget : 0
        }));
    }

    setData(loaded);
  }, []);

  // Auto-save on change
  useEffect(() => {
    saveToStorage(data);
  }, [data]);

  const saveTransaction = (t: Transaction | Omit<Transaction, 'id'>) => {
    if ('id' in t) {
        // Edit existing
        setData(prev => ({
            ...prev,
            transactions: prev.transactions.map(tr => tr.id === t.id ? t as Transaction : tr)
        }));
    } else {
        // Create new
        const newTransaction: Transaction = {
          ...t,
          id: generateId()
        };
        setData(prev => ({
          ...prev,
          transactions: [...prev.transactions, newTransaction]
        }));
    }
  };

  const openEditTransaction = (t: Transaction) => {
      setEditingTransaction(t);
      setIsTransactionModalOpen(true);
  };

  const deleteTransaction = (id: string) => {
    setData(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
  };

  // --- Account Handlers ---
  const saveAccount = (accountData: Omit<Account, 'id'> | Account) => {
    if ('id' in accountData) {
        // Edit existing
        setData(prev => ({
            ...prev,
            accounts: prev.accounts.map(a => a.id === accountData.id ? accountData as Account : a)
        }));
    } else {
        // Create new
        const newAccount: Account = {
            ...accountData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            accounts: [...prev.accounts, newAccount]
        }));
    }
  };

  const reorderAccounts = (newAccounts: Account[]) => {
      setData(prev => ({
          ...prev,
          accounts: newAccounts
      }));
  };

  const toggleAccountVisibility = (account: Account) => {
      const updatedAccount = { ...account, isHidden: !account.isHidden };
      saveAccount(updatedAccount);
  };

  const deleteAccount = (id: string) => {
    setData(prev => ({
        ...prev,
        accounts: prev.accounts.filter(a => a.id !== id),
        transactions: prev.transactions.filter(t => t.accountId !== id)
    }));
  };

  const openAddAccount = () => {
    setEditingAccount(undefined);
    setIsAccountModalOpen(true);
  };

  const openEditAccount = (account: Account) => {
    setEditingAccount(account);
    setIsAccountModalOpen(true);
  };

  // --- Category Handlers ---
  const saveCategory = (catData: Omit<Category, 'id'> | Category) => {
    if ('id' in catData) {
        setData(prev => ({
            ...prev,
            categories: prev.categories.map(c => c.id === catData.id ? catData as Category : c)
        }));
    } else {
        const newCat: Category = {
            ...catData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            categories: [...prev.categories, newCat]
        }));
    }
  };

  const reorderCategories = (newCategories: Category[]) => {
      setData(prev => ({
          ...prev,
          categories: newCategories
      }));
  };

  const deleteCategory = (id: string) => {
    setData(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c.id !== id)
    }));
  };

  const openAddCategory = () => {
      setEditingCategory(undefined);
      setIsCategoryModalOpen(true);
  };

  const openEditCategory = (cat: Category) => {
      setEditingCategory(cat);
      setIsCategoryModalOpen(true);
  };

  const handleDataImport = (newData: AppData) => {
      setData(newData);
      alert('Дані успішно імпортовано!');
  };

  const handleUpdateRates = (newRates: Record<string, number>) => {
      setData(prev => ({
          ...prev,
          rates: newRates
      }));
  };

  // --- Navigation & Filtering Handlers ---
  const handleOverviewCategoryClick = (categoryId: string, date: Date) => {
    setTransactionFilters({
        categoryId,
        date,
        accountId: ''
    });
    setActiveTab('transactions');
  };

  const handleAccountSelect = (accountId: string) => {
    setTransactionFilters({
        accountId,
        date: new Date(), // Default to current month, user can change
        categoryId: ''
    });
    setActiveTab('transactions');
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 w-full overflow-hidden relative">

      {/* Header removed as requested */}

      {/* Main Content Area */}
      <main className="flex-1 overflow-hidden relative w-full pt-safe">
        {activeTab === 'overview' && (
            <OverviewTab 
                transactions={data.transactions} 
                categories={data.categories}
                onCategoryClick={handleOverviewCategoryClick} 
            />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
                onEdit={openEditTransaction}
                initialFilters={transactionFilters}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                rates={data.rates}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
                onSelectAccount={handleAccountSelect}
                onReorderAccounts={reorderAccounts}
                onToggleVisibility={toggleAccountVisibility}
            />
        )}
        {activeTab === 'budget' && (
            <BudgetTab 
                categories={data.categories}
                onAddCategory={openAddCategory}
                onEditCategory={openEditCategory}
                onDeleteCategory={deleteCategory}
                onReorderCategories={reorderCategories}
            />
        )}
      </main>

      {/* FAB - Add Button */}
      <div className="absolute bottom-28 right-4 z-30">
          <button 
            onClick={() => {
                setEditingTransaction(undefined);
                setIsTransactionModalOpen(true);
            }}
            className="w-14 h-14 bg-primary rounded-full shadow-lg shadow-emerald-300 text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          >
              <Plus size={32} />
          </button>
      </div>

      {/* Bottom Navigation */}
      <nav className="bg-white border-t border-gray-200 pb-safe pt-2 px-2 flex justify-between items-center z-20 pb-4">
        <button 
            onClick={() => setActiveTab('overview')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'overview' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <LayoutDashboard size={22} strokeWidth={activeTab === 'overview' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Огляд</span>
        </button>
        <button 
            onClick={() => setActiveTab('transactions')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'transactions' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <List size={22} strokeWidth={activeTab === 'transactions' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Транз.</span>
        </button>
        <button 
            onClick={() => setActiveTab('budget')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'budget' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Calculator size={22} strokeWidth={activeTab === 'budget' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Бюджет</span>
        </button>
        <button 
            onClick={() => setActiveTab('accounts')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'accounts' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Wallet size={22} strokeWidth={activeTab === 'accounts' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Рахунки</span>
        </button>
        {/* Settings moved here */}
        <button 
            onClick={() => setIsDataModalOpen(true)}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] text-gray-400 hover:text-gray-600`}
        >
            <Settings size={22} />
            <span className="text-[10px] font-medium">Налашт.</span>
        </button>
      </nav>

      {/* Modals */}
      <AddTransactionModal 
        isOpen={isTransactionModalOpen} 
        onClose={() => setIsTransactionModalOpen(false)} 
        onSave={saveTransaction}
        accounts={data.accounts}
        categories={data.categories}
        initialData={editingTransaction}
        rates={data.rates}
      />

      <AccountModal 
        isOpen={isAccountModalOpen}
        onClose={() => setIsAccountModalOpen(false)}
        onSave={saveAccount}
        initialData={editingAccount}
      />

      <CategoryModal 
        isOpen={isCategoryModalOpen}
        onClose={() => setIsCategoryModalOpen(false)}
        onSave={saveAccount} // Bug fix: passing saveAccount for category fix, wait, saveCategory is separate
        // Wait, saveCategory was passed correctly before?
        // Checking App.tsx content above...
        // Ah, in previous file content it was: onSave={saveCategory}. 
        // In the updated content above I wrote onSave={saveAccount} by mistake in CategoryModal props?
        // Let me double check the App.tsx content I just wrote above.
        // Yes, in the App.tsx content block above I wrote <CategoryModal ... onSave={saveAccount} />. This is a BUG. 
        // I need to correct it to saveCategory.
        // Also passing toggleAccountVisibility to AccountsTab.
      />

      <CategoryModal 
        isOpen={isCategoryModalOpen}
        onClose={() => setIsCategoryModalOpen(false)}
        onSave={saveCategory} // CORRECTED
        initialData={editingCategory}
      />

      <DataManagementModal
        isOpen={isDataModalOpen}
        onClose={() => setIsDataModalOpen(false)}
        currentData={data}
        onImport={handleDataImport}
        onUpdateRates={handleUpdateRates}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote, ArrowUp, ArrowDown, Eye, EyeOff } from 'lucide-react';
import { Button } from './ui/Button';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  rates: Record<string, number>;
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
  onReorderAccounts: (accounts: Account[]) => void;
  onToggleVisibility: (account: Account) => void;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, 
  transactions,
  rates,
  onAddAccount,
  onEditAccount,
  onDeleteAccount,
  onSelectAccount,
  onReorderAccounts,
  onToggleVisibility
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const getBalance = (account: Account) => {
    // 1. Calculate transactions where this account is the primary source (Expense, Income to self, Transfer Out)
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);

    // 2. Calculate transactions where this account is the destination (Transfer In)
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);

    const totalIncome = sourceTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = sourceTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferOut = sourceTransactions
      .filter(t => t.type === TransactionType.TRANSFER)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalTransferIn = destTransactions.reduce((sum, t) => {
        // If the transaction has a specific toAmount (manually entered multi-currency transfer), use it.
        if (t.toAmount !== undefined) {
            return sum + t.toAmount;
        }

        // Fallback: Convert Source Amount -> UAH -> Dest Amount using global rates
        // This is less accurate for past transactions if rates changed, but kept for backward compatibility
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = rates[account.currency] || 1; 
        const amountInDestCurrency = amountInUAH / destRate;
        return sum + amountInDestCurrency;
    }, 0);

    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const groupAccounts = (type: AccountType) => {
    return accounts.filter(a => (a.type || AccountType.CURRENT) === type);
  };

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        // Skip hidden accounts in total calculation if strictly in "view" mode, 
        // BUT usually hidden accounts still count towards net worth, they are just hidden from UI.
        // However, standard behavior for "Hide" is usually "Archive/Ignore".
        // Let's keep them in total if user wants to see them in edit mode, 
        // but typically if hidden, they shouldn't clutter the total view either.
        // Let's exclude hidden accounts from total if not in edit mode to be consistent.
        if (!isEditMode && account.isHidden) return sum;

        const balance = getBalance(account);
        // Convert to UAH approximation using GLOBAL RATES from settings
        const rate = rates[account.currency] || 1;
        const balanceInUAH = balance * rate;
        return sum + balanceInUAH;
    }, 0);
  };

  const moveAccount = (index: number, direction: 'up' | 'down', groupType: AccountType) => {
      const current = groupAccounts(AccountType.CURRENT);
      const savings = groupAccounts(AccountType.SAVINGS);
      const debt = groupAccounts(AccountType.DEBT);

      // Determine which array we are modifying
      let targetGroup: Account[] = [];
      if (groupType === AccountType.CURRENT) targetGroup = current;
      if (groupType === AccountType.SAVINGS) targetGroup = savings;
      if (groupType === AccountType.DEBT) targetGroup = debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }

      // Reconstruct full list (order matters: Current -> Savings -> Debt)
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (title: string, type: AccountType) => {
    let group = groupAccounts(type);

    // Filter hidden accounts if not in edit mode
    if (!isEditMode) {
        group = group.filter(a => !a.isHidden);
    }

    // Don't show empty groups unless in edit mode
    if (group.length === 0 && !isEditMode) return null;

    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="mb-6 animate-fade-in">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">{title}</h3>
            <span className="text-sm font-bold text-gray-400">
                 {totalInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} UAH
            </span>
        </div>

        <div className="grid grid-cols-1 gap-3">
          {group.map((account, index) => {
            const rawBalance = getBalance(account);
            // Fix for -0 display. If abs(balance) is very small, treat as 0.
            const balance = Math.abs(rawBalance) < 0.005 ? 0 : rawBalance;

            // Use global rate for display calculation
            const currentRate = rates[account.currency] || 1;
            const balanceInUAH = account.currency !== Currency.UAH 
                ? balance * currentRate
                : null;

            // Generate a subtle background color and border color
            // If hidden in edit mode, make it look "inactive" (grayscale or faded)
            const isHidden = !!account.isHidden;
            const bgColor = isHidden ? '#f3f4f6' : (account.color + '10'); // Gray if hidden, Color if visible
            const borderColor = isHidden ? '#9ca3af' : account.color;

            return (
              <div 
                key={account.id} 
                onClick={() => {
                    if (!isEditMode) onSelectAccount(account.id);
                }}
                className={`rounded-xl shadow-sm border border-gray-100 relative overflow-hidden group transition-all ${!isEditMode ? 'cursor-pointer hover:shadow-md active:scale-[0.99]' : ''} ${isHidden ? 'opacity-75' : ''}`}
                style={{ 
                    background: `linear-gradient(110deg, white 40%, ${bgColor} 100%)`,
                    borderLeft: `5px solid ${borderColor}`
                }}
              >
                 <div className="flex items-center justify-between p-4 relative z-10">
                   {/* Left Side: Icon & Name */}
                   <div className="flex items-center gap-3 overflow-hidden">
                      <div 
                        className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm ${isHidden ? 'bg-gray-400' : ''}`}
                        style={{ backgroundColor: isHidden ? undefined : account.color }}
                      >
                          <CategoryIcon iconName={account.icon || 'wallet'} size={20} />
                      </div>
                      <div className="min-w-0">
                          <h3 className={`font-bold text-base truncate pr-2 ${isHidden ? 'text-gray-500' : 'text-gray-800'}`}>
                              {account.name} {isHidden && <span className='text-xs font-normal text-gray-400'>(Приховано)</span>}
                          </h3>
                          {balanceInUAH !== null && (
                            <div className="text-xs font-medium text-gray-400 mt-0.5">
                                {balanceInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} UAH
                            </div>
                           )}
                      </div>
                   </div>

                   {/* Right Side: Balances or Controls */}
                   <div className="flex items-center gap-3 text-right shrink-0">
                        {isEditMode ? (
                           <div className="flex items-center gap-1 bg-white/50 backdrop-blur-sm p-1 rounded-full border border-gray-200 shadow-sm">
                               {/* Visibility Toggle */}
                               <button 
                                    onClick={(e) => { e.stopPropagation(); onToggleVisibility(account); }}
                                    className="w-8 h-8 flex items-center justify-center rounded-full transition-all hover:bg-white"
                               >
                                   {account.isHidden ? <EyeOff size={16} className="text-gray-400" /> : <Eye size={16} className="text-black" />}
                               </button>

                               <div className="w-px h-4 bg-gray-300 mx-1"></div>

                               {/* Reorder Controls */}
                               <button 
                                    onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }}
                                    disabled={index === 0}
                                    className="w-8 h-8 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowUp size={16} strokeWidth={2.5} />
                               </button>
                               <button 
                                    onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }}
                                    disabled={index === group.length - 1}
                                    className="w-8 h-8 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowDown size={16} strokeWidth={2.5} />
                               </button>

                               <div className="w-px h-4 bg-gray-300 mx-1"></div>

                               <button 
                                    onClick={(e) => { e.stopPropagation(); onEditAccount(account); }}
                                    className="w-8 h-8 flex items-center justify-center text-blue-600 hover:bg-blue-50 rounded-full transition-colors"
                                >
                                    <Pencil size={16} />
                                </button>
                                <button 
                                    onClick={(e) => { 
                                        e.stopPropagation(); 
                                        if(window.confirm('Видалити цей рахунок та всі його транзакції?')) {
                                            onDeleteAccount(account.id);
                                        }
                                    }}
                                    className="w-8 h-8 flex items-center justify-center text-red-600 hover:bg-red-50 rounded-full transition-colors"
                                >
                                    <Trash2 size={16} />
                                </button>
                           </div>
                        ) : (
                            /* Main Balance Display */
                            <div className={`text-lg font-bold tracking-tight whitespace-nowrap ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                                {balance.toLocaleString('uk-UA', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}
                                <span className="text-sm font-medium text-gray-500 ml-1">{account.currency}</span>
                            </div>
                        )}
                   </div>
                 </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 relative h-full overflow-y-auto no-scrollbar">
       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-4 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Рахунки</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

      {renderAccountGroup('Поточні', AccountType.CURRENT)}
      {renderAccountGroup('Заощадження', AccountType.SAVINGS)}
      {renderAccountGroup('Заборгованість', AccountType.DEBT)}

      {/* Single Add Button at the bottom */}
      {isEditMode && (
          <button 
            onClick={onAddAccount}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати рахунок
          </button>
      )}

      {/* Empty State (only if no accounts and not editing) */}
      {accounts.length === 0 && !isEditMode && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Transaction, Category, TransactionType } from '../types';
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp, ChevronRight as ChevronRightIcon, Wallet } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface OverviewTabProps {
  transactions: Transaction[];
  categories: Category[];
  onCategoryClick: (categoryId: string, date: Date) => void;
}

export const OverviewTab: React.FC<OverviewTabProps> = ({ transactions, categories, onCategoryClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
    });
  }, [transactions, currentDate]);

  const stats = useMemo(() => {
    let income = 0;
    let expense = 0;
    const categoryTotals: { [key: string]: number } = {};

    filteredTransactions.forEach(t => {
      // Normalize to base currency (UAH) roughly using stored exchangeRate
      const amountInBase = t.amount * t.exchangeRate;

      if (t.type === TransactionType.INCOME) {
        income += amountInBase;
      } else if (t.type === TransactionType.EXPENSE) {
        expense += amountInBase;
      }

      if (!categoryTotals[t.categoryId]) categoryTotals[t.categoryId] = 0;
      categoryTotals[t.categoryId] += amountInBase;
    });

    // Process Expenses (Preserve order from categories prop)
    const expenseCategories = categories.filter(c => c.type === TransactionType.EXPENSE);
    const totalBudgetExpense = expenseCategories.reduce((sum, c) => sum + (c.monthlyBudget || 0), 0);

    const expenseData = expenseCategories.map(cat => ({
        id: cat.id,
        name: cat.name,
        value: categoryTotals[cat.id] || 0,
        budget: cat.monthlyBudget || 0,
        color: cat.color,
        icon: cat.icon
    }));

    // Process Income (Preserve order from categories prop)
    const incomeCategories = categories.filter(c => c.type === TransactionType.INCOME);
    const totalBudgetIncome = incomeCategories.reduce((sum, c) => sum + (c.monthlyBudget || 0), 0);

    const incomeData = incomeCategories.map(cat => ({
        id: cat.id,
        name: cat.name,
        value: categoryTotals[cat.id] || 0,
        budget: cat.monthlyBudget || 0,
        color: cat.color,
        icon: cat.icon
    }));

    return { 
        income, 
        expense, 
        expenseData, 
        totalBudgetExpense,
        incomeData,
        totalBudgetIncome
    };
  }, [filteredTransactions, categories]);

  const balance = stats.income - stats.expense;

  const renderCategoryList = (title: string, data: typeof stats.expenseData, totalActual: number, totalBudget: number) => {
      return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center">
              <h3 className="font-semibold text-gray-700">{title}</h3>
            </div>
            <div className="divide-y divide-gray-50">
                {data.map((item) => {
                    const percent = item.budget > 0 ? (item.value / item.budget) * 100 : 0;
                    // Show item if it has budget OR value, or strict showing? 
                    // Let's show all configured categories to see gaps

                    return (
                        <div 
                          key={item.id} 
                          className="p-3 hover:bg-gray-50 cursor-pointer transition-colors active:bg-gray-100"
                          onClick={() => onCategoryClick(item.id, currentDate)}
                        >
                            <div className="flex justify-between text-sm mb-1.5">
                                <div className="flex items-center gap-2">
                                    <div className="w-5 h-5 rounded-full flex items-center justify-center text-white" style={{ backgroundColor: item.color }}>
                                       <CategoryIcon iconName={item.icon} size={12} />
                                    </div>
                                    <span className="text-gray-700 font-medium">{item.name}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                  <span className="text-gray-900 font-semibold text-xs sm:text-sm">
                                      {item.value.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                                      <span className="text-gray-400 font-normal ml-1">
                                          / {item.budget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
                                      </span>
                                  </span>
                                  <ChevronRightIcon size={14} className="text-gray-300" />
                                </div>
                            </div>
                            <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className="h-full rounded-full opacity-80"
                                    style={{ 
                                        width: `${Math.min(percent, 100)}%`,
                                        backgroundColor: item.color 
                                    }}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
            {/* Footer Total */}
            <div className="bg-gray-50 p-3 flex justify-between items-center text-sm border-t border-gray-100">
                <span className="font-bold text-gray-500">Всього</span>
                <span className="font-bold text-gray-800">
                     {totalActual.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                     <span className="text-gray-400 font-normal ml-1">
                        / {totalBudget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
                     </span>
                </span>
            </div>
        </div>
      );
  };

  return (
    <div className="pb-32 pt-4 px-4 space-y-4 h-full overflow-y-auto no-scrollbar">
      {/* Date Control */}
      <div className="flex items-center justify-between bg-white p-2 rounded-xl shadow-sm">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-lg font-bold text-gray-800 capitalize">{periodLabel}</h2>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronRight size={20} />
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-2">
        {/* Expenses */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <TrendingDown size={12} className="text-red-500" /> Витрати
           </span>
           <span className="text-sm sm:text-base font-bold text-gray-900 break-all">
             {stats.expense.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>

        {/* Income */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <TrendingUp size={12} className="text-emerald-500" /> Доходи
           </span>
           <span className="text-sm sm:text-base font-bold text-emerald-600 break-all">
             {stats.income.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>

        {/* Net / Balance */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <Wallet size={12} className="text-blue-500" /> Сальдо
           </span>
           <span className={`text-sm sm:text-base font-bold break-all ${balance >= 0 ? 'text-blue-600' : 'text-red-500'}`}>
             {balance > 0 ? '+' : ''}{balance.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>
      </div>

      {/* Lists */}
      {renderCategoryList('Витрати', stats.expenseData, stats.expense, stats.totalBudgetExpense)}

      {renderCategoryList('Доходи', stats.incomeData, stats.income, stats.totalBudgetIncome)}

    </div>
  );
};

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER' // Optional extension
}

export enum Currency {
  UAH = 'UAH',
  USD = 'USD',
  EUR = 'EUR'
}

export enum AccountType {
  CURRENT = 'CURRENT',
  DEBT = 'DEBT',
  SAVINGS = 'SAVINGS'
}

export interface Account {
  id: string;
  name: string;
  currency: Currency;
  initialBalance: number;
  color: string;
  icon: string; // Icon name from CategoryIcon map
  type: AccountType;
  currentRate: number; // Legacy, but kept for compatibility. UI now prefers AppData.rates
  isHidden?: boolean; // New property for visibility toggle
}

export interface Category {
  id: string;
  name: string;
  type: TransactionType;
  icon: string;
  color: string;
  monthlyBudget: number; // Deprecated: used as fallback, logic moved to budgetHistory
  budgetHistory?: Record<string, number>; // Key: "YYYY-MM", Value: Budget Amount
}

export interface Transaction {
  id: string;
  date: string; // ISO string
  amount: number;
  currency: Currency;
  exchangeRate: number; // Rate relative to base currency (UAH). 1 for UAH.
  accountId: string;
  toAccountId?: string; // Target account for transfers
  toAmount?: number; // Exact amount received in target account (for transfers)
  categoryId: string; // Optional for Transfer, strictly
  note?: string;
  type: TransactionType;
}

export interface AppData {
  accounts: Account[];
  categories: Category[];
  transactions: Transaction[];
  rates: Record<string, number>; // Global exchange rates (e.g., "USD": 41.5)
}

export const BASE_CURRENCY = Currency.UAH;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, Wallet, Plus, Settings, Calculator } from 'lucide-react';
import { AppData, Transaction, Account, Category } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage } from './services/storageService';
import { OverviewTab } from './components/OverviewTab';
import { TransactionList, TransactionFilters } from './components/TransactionList';
import { AccountsTab } from './components/AccountsTab';
import { BudgetTab } from './components/BudgetTab';
import { AddTransactionModal } from './components/AddTransactionModal';
import { AccountModal } from './components/AccountModal';
import { CategoryModal } from './components/CategoryModal';
import { DataManagementModal } from './components/DataManagementModal';

// Simple UUID generator fallback since we can't install packages freely
const generateId = () => Math.random().toString(36).substr(2, 9);

export default function App() {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'accounts' | 'budget'>('overview');
  const [data, setData] = useState<AppData>(INITIAL_DATA);

  // Navigation & Filtering State
  const [transactionFilters, setTransactionFilters] = useState<TransactionFilters | null>(null);

  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);

  const [editingAccount, setEditingAccount] = useState<Account | undefined>(undefined);
  const [editingCategory, setEditingCategory] = useState<Category | undefined>(undefined);
  const [editingCategoryDate, setEditingCategoryDate] = useState<Date>(new Date()); // Context for budget editing
  const [editingTransaction, setEditingTransaction] = useState<Transaction | undefined>(undefined);

  // Load data on mount
  useEffect(() => {
    const loaded = loadFromStorage();

    // Migration: ensure rates exist
    if (!loaded.rates) {
        loaded.rates = INITIAL_DATA.rates;
    }

    // Migration: ensure accounts have types and icons
    if (loaded.accounts) {
       loaded.accounts = loaded.accounts.map(a => {
           let updated = { ...a };
           // @ts-ignore
           if (!updated.type) updated.type = 'CURRENT';
           if (!updated.currentRate) updated.currentRate = 1;
           if (!updated.icon) {
               const nameLower = updated.name.toLowerCase();
               if (nameLower.includes('карт') || nameLower.includes('card')) updated.icon = 'credit-card';
               else if (nameLower.includes('банк') || nameLower.includes('bank')) updated.icon = 'landmark';
               else if (nameLower.includes('usd') || nameLower.includes('eur')) updated.icon = 'banknote';
               else updated.icon = 'wallet';
           }
           return updated as Account;
       });
    }

    // Migration for categories (budgetHistory)
    if(loaded.categories) {
        loaded.categories = loaded.categories.map(c => {
            const updated = { ...c };
            // Ensure budgetHistory exists. If not, migrate monthlyBudget to a history entry in the past.
            if (!updated.budgetHistory) {
                updated.budgetHistory = {
                    '2023-01': c.monthlyBudget || 0
                };
            }
            // Ensure monthlyBudget is still there for types compatibility, though we prioritize history
            if (updated.monthlyBudget === undefined) updated.monthlyBudget = 0;
            return updated;
        });
    }

    setData(loaded);
  }, []);

  // Auto-save on change
  useEffect(() => {
    saveToStorage(data);
  }, [data]);

  const saveTransaction = (t: Transaction | Omit<Transaction, 'id'>) => {
    if ('id' in t) {
        // Edit existing
        setData(prev => ({
            ...prev,
            transactions: prev.transactions.map(tr => tr.id === t.id ? t as Transaction : tr)
        }));
    } else {
        // Create new
        const newTransaction: Transaction = {
          ...t,
          id: generateId()
        };
        setData(prev => ({
          ...prev,
          transactions: [...prev.transactions, newTransaction]
        }));
    }
  };

  const openEditTransaction = (t: Transaction) => {
      setEditingTransaction(t);
      setIsTransactionModalOpen(true);
  };

  const deleteTransaction = (id: string) => {
    setData(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
  };

  // --- Account Handlers ---
  const saveAccount = (accountData: Omit<Account, 'id'> | Account) => {
    if ('id' in accountData) {
        // Edit existing
        setData(prev => ({
            ...prev,
            accounts: prev.accounts.map(a => a.id === accountData.id ? accountData as Account : a)
        }));
    } else {
        // Create new
        const newAccount: Account = {
            ...accountData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            accounts: [...prev.accounts, newAccount]
        }));
    }
  };

  const reorderAccounts = (newAccounts: Account[]) => {
      setData(prev => ({
          ...prev,
          accounts: newAccounts
      }));
  };

  const toggleAccountVisibility = (account: Account) => {
      const updatedAccount = { ...account, isHidden: !account.isHidden };
      saveAccount(updatedAccount);
  };

  const deleteAccount = (id: string) => {
    setData(prev => ({
        ...prev,
        accounts: prev.accounts.filter(a => a.id !== id),
        transactions: prev.transactions.filter(t => t.accountId !== id)
    }));
  };

  const openAddAccount = () => {
    setEditingAccount(undefined);
    setIsAccountModalOpen(true);
  };

  const openEditAccount = (account: Account) => {
    setEditingAccount(account);
    setIsAccountModalOpen(true);
  };

  // --- Category Handlers ---
  const saveCategory = (catData: Omit<Category, 'id'> | Category) => {
    // Determine the month key for the current editing context
    const monthKey = editingCategoryDate.toISOString().slice(0, 7); // "YYYY-MM"

    if ('id' in catData) {
        setData(prev => ({
            ...prev,
            categories: prev.categories.map(c => {
                if (c.id === catData.id) {
                    const newBudget = catData.monthlyBudget;
                    const oldHistory = c.budgetHistory || {};

                    // Logic: Update history for this month. 
                    // To "Apply to subsequent months", we delete any future explicit overrides.
                    // This way, future months will fall back to finding *this* new entry as the most recent one.
                    const newHistory = { ...oldHistory };

                    // 1. Set current month
                    newHistory[monthKey] = newBudget;

                    // 2. Delete all future keys
                    Object.keys(newHistory).forEach(key => {
                        if (key > monthKey) {
                            delete newHistory[key];
                        }
                    });

                    return {
                        ...catData,
                        budgetHistory: newHistory
                    } as Category;
                }
                return c;
            })
        }));
    } else {
        // New Category
        const newCat: Category = {
            ...catData,
            id: generateId(),
            budgetHistory: {
                [monthKey]: catData.monthlyBudget // Start history from current view month
            }
        } as Category;

        setData(prev => ({
            ...prev,
            categories: [...prev.categories, newCat]
        }));
    }
  };

  const reorderCategories = (newCategories: Category[]) => {
      setData(prev => ({
          ...prev,
          categories: newCategories
      }));
  };

  const deleteCategory = (id: string) => {
    setData(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c.id !== id)
    }));
  };

  const openAddCategory = (date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(undefined);
      setIsCategoryModalOpen(true);
  };

  const openEditCategory = (cat: Category, date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(cat);
      setIsCategoryModalOpen(true);
  };

  const handleDataImport = (newData: AppData) => {
      setData(newData);
      alert('Дані успішно імпортовано!');
  };

  const handleUpdateRates = (newRates: Record<string, number>) => {
      setData(prev => ({
          ...prev,
          rates: newRates
      }));
  };

  // --- Navigation & Filtering Handlers ---
  const handleOverviewCategoryClick = (categoryId: string, date: Date) => {
    setTransactionFilters({
        categoryId,
        date,
        accountId: ''
    });
    setActiveTab('transactions');
  };

  const handleAccountSelect = (accountId: string) => {
    setTransactionFilters({
        accountId,
        date: new Date(), // Default to current month, user can change
        categoryId: ''
    });
    setActiveTab('transactions');
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 w-full overflow-hidden relative">

      {/* Main Content Area */}
      <main className="flex-1 overflow-hidden relative w-full pt-safe">
        {activeTab === 'overview' && (
            <OverviewTab 
                transactions={data.transactions} 
                categories={data.categories}
                onCategoryClick={handleOverviewCategoryClick} 
            />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
                onEdit={openEditTransaction}
                initialFilters={transactionFilters}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                rates={data.rates}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
                onSelectAccount={handleAccountSelect}
                onReorderAccounts={reorderAccounts}
                onToggleVisibility={toggleAccountVisibility}
            />
        )}
        {activeTab === 'budget' && (
            <BudgetTab 
                categories={data.categories}
                onAddCategory={openAddCategory}
                onEditCategory={openEditCategory}
                onDeleteCategory={deleteCategory}
                onReorderCategories={reorderCategories}
            />
        )}
      </main>

      {/* FAB - Add Button */}
      <div className="absolute bottom-28 right-4 z-30">
          <button 
            onClick={() => {
                setEditingTransaction(undefined);
                setIsTransactionModalOpen(true);
            }}
            className="w-14 h-14 bg-primary rounded-full shadow-lg shadow-emerald-300 text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          >
              <Plus size={32} />
          </button>
      </div>

      {/* Bottom Navigation */}
      <nav className="bg-white border-t border-gray-200 pb-safe pt-2 px-2 flex justify-between items-center z-20 pb-4">
        <button 
            onClick={() => setActiveTab('overview')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'overview' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <LayoutDashboard size={22} strokeWidth={activeTab === 'overview' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Огляд</span>
        </button>
        <button 
            onClick={() => setActiveTab('transactions')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'transactions' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <List size={22} strokeWidth={activeTab === 'transactions' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Транз.</span>
        </button>
        <button 
            onClick={() => setActiveTab('budget')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'budget' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Calculator size={22} strokeWidth={activeTab === 'budget' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Бюджет</span>
        </button>
        <button 
            onClick={() => setActiveTab('accounts')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'accounts' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Wallet size={22} strokeWidth={activeTab === 'accounts' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Рахунки</span>
        </button>
        <button 
            onClick={() => setIsDataModalOpen(true)}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] text-gray-400 hover:text-gray-600`}
        >
            <Settings size={22} />
            <span className="text-[10px] font-medium">Налашт.</span>
        </button>
      </nav>

      {/* Modals */}
      <AddTransactionModal 
        isOpen={isTransactionModalOpen} 
        onClose={() => setIsTransactionModalOpen(false)} 
        onSave={saveTransaction}
        accounts={data.accounts}
        categories={data.categories}
        initialData={editingTransaction}
        rates={data.rates}
      />

      <AccountModal 
        isOpen={isAccountModalOpen}
        onClose={() => setIsAccountModalOpen(false)}
        onSave={saveAccount}
        initialData={editingAccount}
      />

      <CategoryModal 
        isOpen={isCategoryModalOpen}
        onClose={() => setIsCategoryModalOpen(false)}
        onSave={saveCategory}
        initialData={editingCategory}
        targetDate={editingCategoryDate} // Pass date context
      />

      <DataManagementModal
        isOpen={isDataModalOpen}
        onClose={() => setIsDataModalOpen(false)}
        currentData={data}
        onImport={handleDataImport}
        onUpdateRates={handleUpdateRates}
      />
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Category, TransactionType } from '../types';
import { Lock, LockOpen, Plus, Trash2, Pencil, TrendingUp, TrendingDown, ArrowUp, ArrowDown, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface BudgetTabProps {
  categories: Category[];
  onAddCategory: (date: Date) => void;
  onEditCategory: (category: Category, date: Date) => void;
  onDeleteCategory: (id: string) => void;
  onReorderCategories: (categories: Category[]) => void;
}

export const BudgetTab: React.FC<BudgetTabProps> = ({ 
  categories, 
  onAddCategory, 
  onEditCategory, 
  onDeleteCategory,
  onReorderCategories
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  // Helper to resolve budget for a specific date from history
  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;

    // Sort keys (YYYY-MM) descending
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7); // YYYY-MM

    // Find first key <= targetKey
    const effectiveKey = keys.find(k => k <= targetKey);

    if (effectiveKey) return category.budgetHistory[effectiveKey];

    // Fallback if no history before this date (e.g. creating history for future)
    // Try to find ANY earliest entry? Or just return 0. 
    // Usually we want to return the oldest known if we are looking way back? 
    // Or 0 if it didn't exist? Let's assume 0 if it predates history.
    return 0;
  };

  const moveCategory = (index: number, direction: 'up' | 'down', groupType: TransactionType) => {
    const income = categories.filter(c => c.type === TransactionType.INCOME);
    const expense = categories.filter(c => c.type === TransactionType.EXPENSE);

    // We only modify the group corresponding to the type
    const targetGroup = groupType === TransactionType.INCOME ? income : expense;

    if (direction === 'up') {
        if (index === 0) return;
        [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
    } else {
        if (index === targetGroup.length - 1) return;
         [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
    }

    // Combine back to form the full list (maintaining Income then Expense order, or vice versa)
    onReorderCategories([...income, ...expense]);
  };

  const renderCategoryGroup = (type: TransactionType, title: string, Icon: React.ElementType) => {
    const group = categories.filter(c => c.type === type);

    // Calculate totals based on CURRENT view month
    const totalBudget = group.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);

    return (
      <div className="mb-6 animate-fade-in">
        <div className="flex justify-between items-end mb-3 px-1">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                <Icon size={16} /> {title}
            </h3>
            <span className="text-sm font-bold text-gray-700">
                {totalBudget.toLocaleString('uk-UA')} UAH / міс
            </span>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
          {group.map((category, index) => {
            const budgetAmount = getBudgetForDate(category, currentDate);

            return (
            <div key={category.id} className="p-4 flex items-center justify-between group hover:bg-gray-50 transition-colors relative">
               {/* Left Side: Icon & Name */}
               <div className="flex items-center gap-3 overflow-hidden">
                  <div 
                    className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm"
                    style={{ backgroundColor: category.color }}
                  >
                    <CategoryIcon iconName={category.icon} size={20} />
                  </div>
                  <div className="font-bold text-gray-800 text-base truncate pr-2">
                    {category.name}
                  </div>
               </div>

               {/* Right Side: Amount & Controls */}
               <div className="flex items-center gap-3 shrink-0">
                   <div className="text-lg font-bold text-gray-900 whitespace-nowrap">
                        {budgetAmount.toLocaleString('uk-UA')} <span className="text-sm font-medium text-gray-400 ml-1">UAH</span>
                   </div>

                   {isEditMode && (
                       <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200">
                           {/* Reorder Controls */}
                           <div className="flex items-center gap-1 bg-gray-50 p-1 rounded-full border border-gray-100">
                               <button 
                                    onClick={() => moveCategory(index, 'up', type)}
                                    disabled={index === 0}
                                    className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowUp size={14} strokeWidth={2.5} />
                               </button>
                               <button 
                                    onClick={() => moveCategory(index, 'down', type)}
                                    disabled={index === group.length - 1}
                                    className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded-full disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                               >
                                   <ArrowDown size={14} strokeWidth={2.5} />
                               </button>
                           </div>

                           <button 
                                onClick={() => onEditCategory(category, currentDate)}
                                className="w-9 h-9 flex items-center justify-center bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                            >
                                <Pencil size={16} />
                            </button>
                            <button 
                                onClick={() => {
                                    if(window.confirm(`Видалити категорію "${category.name}"? Це не видалить існуючі транзакції.`)) {
                                        onDeleteCategory(category.id);
                                    }
                                }}
                                className="w-9 h-9 flex items-center justify-center bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                            >
                                <Trash2 size={16} />
                            </button>
                       </div>
                   )}
               </div>
            </div>
            );
          })}
          {group.length === 0 && (
              <div className="p-4 text-center text-gray-400 text-sm">
                  Список порожній
              </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 h-full overflow-y-auto no-scrollbar">
       {/* Date Control */}
       <div className="flex items-center justify-between bg-white p-2 mb-4 rounded-xl shadow-sm">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-lg font-bold text-gray-800 capitalize">{periodLabel}</h2>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronRight size={20} />
        </button>
      </div>

       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-4 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Бюджет</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

       {renderCategoryGroup(TransactionType.INCOME, 'Доходи', TrendingUp)}
       {renderCategoryGroup(TransactionType.EXPENSE, 'Витрати', TrendingDown)}

       {/* Single Add Button at the bottom */}
       {isEditMode && (
          <button 
            onClick={() => onAddCategory(currentDate)}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати статтю
          </button>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Category, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X } from 'lucide-react';
import { CategoryIcon, ICON_MAP } from './CategoryIcon';

interface CategoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (category: Omit<Category, 'id'> | Category) => void;
  initialData?: Category;
  targetDate?: Date;
}

const COLORS = ['#ef4444', '#f97316', '#f59e0b', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#8b5cf6', '#ec4899', '#f43f5e', '#6b7280', '#000000'];

export const CategoryModal: React.FC<CategoryModalProps> = ({ isOpen, onClose, onSave, initialData, targetDate = new Date() }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [monthlyBudget, setMonthlyBudget] = useState('0');
  const [color, setColor] = useState(COLORS[0]);
  const [icon, setIcon] = useState('shopping-cart');

  const monthLabel = targetDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  // Helper to resolve budget from history
  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7);
    const effectiveKey = keys.find(k => k <= targetKey);
    return effectiveKey ? category.budgetHistory[effectiveKey] : 0;
  };

  useEffect(() => {
    if (initialData) {
      setName(initialData.name);
      setType(initialData.type);

      // Load budget specifically for the target date
      const budgetForMonth = getBudgetForDate(initialData, targetDate);
      setMonthlyBudget(budgetForMonth.toString());

      setColor(initialData.color);
      setIcon(ICON_MAP[initialData.icon] ? initialData.icon : 'shopping-cart');
    } else {
      resetForm();
    }
  }, [initialData, isOpen, targetDate]);

  const resetForm = () => {
    setName('');
    setType(TransactionType.EXPENSE);
    setMonthlyBudget('0');
    setColor(COLORS[0]);
    setIcon('shopping-cart');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const categoryData = {
      name,
      type,
      icon, 
      color,
      monthlyBudget: parseFloat(monthlyBudget) || 0
    };

    if (initialData) {
      onSave({ ...categoryData, id: initialData.id });
    } else {
      onSave(categoryData);
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">{initialData ? 'Редагувати категорію' : 'Нова категорія'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">

          <div className="flex p-1 bg-gray-100 rounded-lg mb-4">
                <button 
                    type="button"
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow text-red-500' : 'text-gray-500 hover:text-gray-700'}`}
                    onClick={() => setType(TransactionType.EXPENSE)}
                >
                    Витрати
                </button>
                <button 
                    type="button"
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white shadow text-emerald-500' : 'text-gray-500 hover:text-gray-700'}`}
                    onClick={() => setType(TransactionType.INCOME)}
                >
                    Доходи
                </button>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Назва</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
              placeholder="Назва статті"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
                {type === TransactionType.EXPENSE ? `Місячний ліміт на ${monthLabel}` : `Очікуваний дохід на ${monthLabel}`}
            </label>
            <input
              type="number"
              step="0.01"
              value={monthlyBudget}
              onChange={(e) => setMonthlyBudget(e.target.value)}
              className="w-full p-3 bg-gray-50 rounded-xl border-none focus:ring-2 focus:ring-primary"
            />
            <p className="text-[10px] text-gray-400 mt-1">
                Зміни будуть застосовані до цього місяця та всіх наступних.
            </p>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Колір мітки</label>
            <div className="flex flex-wrap gap-2">
              {COLORS.map(c => (
                <button
                  key={c}
                  type="button"
                  onClick={() => setColor(c)}
                  className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${color === c ? 'ring-2 ring-offset-2 ring-gray-400 scale-110' : ''}`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Іконка</label>
            <div className="grid grid-cols-6 gap-2">
              {Object.keys(ICON_MAP).filter(k => k !== 'transfer').map((key) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setIcon(key)}
                  className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${icon === key ? 'bg-emerald-50 text-primary ring-2 ring-primary' : 'bg-gray-50 text-gray-500 hover:bg-gray-100'}`}
                >
                  <CategoryIcon iconName={key} size={20} />
                </button>
              ))}
            </div>
          </div>

          <Button type="submit" fullWidth className="py-3 mt-4">
            Зберегти
          </Button>
        </form>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Transaction, Category, TransactionType } from '../types';
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp, ChevronRight as ChevronRightIcon, Wallet } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface OverviewTabProps {
  transactions: Transaction[];
  categories: Category[];
  onCategoryClick: (categoryId: string, date: Date) => void;
}

export const OverviewTab: React.FC<OverviewTabProps> = ({ transactions, categories, onCategoryClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  // Helper to resolve budget from history
  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7);
    const effectiveKey = keys.find(k => k <= targetKey);
    return effectiveKey ? category.budgetHistory[effectiveKey] : 0;
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
    });
  }, [transactions, currentDate]);

  const stats = useMemo(() => {
    let income = 0;
    let expense = 0;
    const categoryTotals: { [key: string]: number } = {};

    filteredTransactions.forEach(t => {
      // Normalize to base currency (UAH) roughly using stored exchangeRate
      const amountInBase = t.amount * t.exchangeRate;

      if (t.type === TransactionType.INCOME) {
        income += amountInBase;
      } else if (t.type === TransactionType.EXPENSE) {
        expense += amountInBase;
      }

      if (!categoryTotals[t.categoryId]) categoryTotals[t.categoryId] = 0;
      categoryTotals[t.categoryId] += amountInBase;
    });

    // Process Expenses (Preserve order from categories prop)
    const expenseCategories = categories.filter(c => c.type === TransactionType.EXPENSE);

    // Calculate total budget dynamically for this month
    const totalBudgetExpense = expenseCategories.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);

    const expenseData = expenseCategories.map(cat => ({
        id: cat.id,
        name: cat.name,
        value: categoryTotals[cat.id] || 0,
        budget: getBudgetForDate(cat, currentDate),
        color: cat.color,
        icon: cat.icon
    }));

    // Process Income (Preserve order from categories prop)
    const incomeCategories = categories.filter(c => c.type === TransactionType.INCOME);
    const totalBudgetIncome = incomeCategories.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);

    const incomeData = incomeCategories.map(cat => ({
        id: cat.id,
        name: cat.name,
        value: categoryTotals[cat.id] || 0,
        budget: getBudgetForDate(cat, currentDate),
        color: cat.color,
        icon: cat.icon
    }));

    return { 
        income, 
        expense, 
        expenseData, 
        totalBudgetExpense,
        incomeData,
        totalBudgetIncome
    };
  }, [filteredTransactions, categories, currentDate]);

  const balance = stats.income - stats.expense;

  const renderCategoryList = (title: string, data: typeof stats.expenseData, totalActual: number, totalBudget: number) => {
      return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center">
              <h3 className="font-semibold text-gray-700">{title}</h3>
            </div>
            <div className="divide-y divide-gray-50">
                {data.map((item) => {
                    const percent = item.budget > 0 ? (item.value / item.budget) * 100 : 0;

                    return (
                        <div 
                          key={item.id} 
                          className="p-3 hover:bg-gray-50 cursor-pointer transition-colors active:bg-gray-100"
                          onClick={() => onCategoryClick(item.id, currentDate)}
                        >
                            <div className="flex justify-between text-sm mb-1.5">
                                <div className="flex items-center gap-2">
                                    <div className="w-5 h-5 rounded-full flex items-center justify-center text-white" style={{ backgroundColor: item.color }}>
                                       <CategoryIcon iconName={item.icon} size={12} />
                                    </div>
                                    <span className="text-gray-700 font-medium">{item.name}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                  <span className="text-gray-900 font-semibold text-xs sm:text-sm">
                                      {item.value.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                                      <span className="text-gray-400 font-normal ml-1">
                                          / {item.budget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
                                      </span>
                                  </span>
                                  <ChevronRightIcon size={14} className="text-gray-300" />
                                </div>
                            </div>
                            <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                                <div 
                                    className="h-full rounded-full opacity-80"
                                    style={{ 
                                        width: `${Math.min(percent, 100)}%`,
                                        backgroundColor: item.color 
                                    }}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
            {/* Footer Total */}
            <div className="bg-gray-50 p-3 flex justify-between items-center text-sm border-t border-gray-100">
                <span className="font-bold text-gray-500">Всього</span>
                <span className="font-bold text-gray-800">
                     {totalActual.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                     <span className="text-gray-400 font-normal ml-1">
                        / {totalBudget.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} ₴
                     </span>
                </span>
            </div>
        </div>
      );
  };

  return (
    <div className="pb-32 pt-4 px-4 space-y-4 h-full overflow-y-auto no-scrollbar">
      {/* Date Control */}
      <div className="flex items-center justify-between bg-white p-2 rounded-xl shadow-sm">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-lg font-bold text-gray-800 capitalize">{periodLabel}</h2>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600">
          <ChevronRight size={20} />
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-2">
        {/* Expenses */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <TrendingDown size={12} className="text-red-500" /> Витрати
           </span>
           <span className="text-sm sm:text-base font-bold text-gray-900 break-all">
             {stats.expense.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>

        {/* Income */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <TrendingUp size={12} className="text-emerald-500" /> Доходи
           </span>
           <span className="text-sm sm:text-base font-bold text-emerald-600 break-all">
             {stats.income.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>

        {/* Net / Balance */}
        <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center">
           <span className="text-[10px] text-gray-500 uppercase font-bold mb-1 flex items-center gap-1">
             <Wallet size={12} className="text-blue-500" /> Сальдо
           </span>
           <span className={`text-sm sm:text-base font-bold break-all ${balance >= 0 ? 'text-blue-600' : 'text-red-500'}`}>
             {balance > 0 ? '+' : ''}{balance.toLocaleString('uk-UA', { maximumFractionDigits: 0 })}
           </span>
        </div>
      </div>

      {/* Lists */}
      {renderCategoryList('Витрати', stats.expenseData, stats.expense, stats.totalBudgetExpense)}

      {renderCategoryList('Доходи', stats.incomeData, stats.income, stats.totalBudgetIncome)}

    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date; // Usually first day of the month
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, 
  accounts, 
  categories,
  onDelete,
  onEdit,
  initialFilters
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [showFilters, setShowFilters] = useState(true);

  // Filter States
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  // Apply initial filters when they change (navigation from other tabs)
  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      setShowFilters(true);
    }
  }, [initialFilters]);

  const resetFilters = () => {
    setFilterMonth(new Date());
    setFilterAccountId('');
    setFilterCategoryId('');
  };

  const prevMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);

      // 1. Filter by Date (Month)
      // Only apply month filter if we assume "budget view". 
      // Users might want to see "All time" for an account, but standard view is usually monthly.
      // Let's strictly follow the selected filterMonth.
      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && 
                        tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;

      // 2. Filter by Account
      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) {
        return false;
      }

      // 3. Filter by Category
      if (filterCategoryId && t.categoryId !== filterCategoryId) {
        return false;
      }

      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  return (
    <div className="h-full flex flex-col">
        {/* Filters Header */}
        <div className="bg-white border-b border-gray-200 px-4 py-3 shadow-sm z-20">
            {/* Month Selector */}
            <div className="flex items-center justify-between mb-3">
                 <button onClick={prevMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronLeft size={20} />
                 </button>
                 <span className="font-bold text-gray-800 capitalize">{monthLabel}</span>
                 <button onClick={nextMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronRight size={20} />
                 </button>
            </div>

            {/* Dropdowns */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <select 
                        value={filterAccountId}
                        onChange={(e) => setFilterAccountId(e.target.value)}
                        className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterAccountId ? 'bg-blue-50 border-blue-200 text-blue-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі рахунки</option>
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name}</option>
                        ))}
                    </select>
                </div>

                <div className="relative flex-1">
                    <select 
                        value={filterCategoryId}
                        onChange={(e) => setFilterCategoryId(e.target.value)}
                         className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterCategoryId ? 'bg-emerald-50 border-emerald-200 text-emerald-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі категорії</option>
                        {categories.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {(filterAccountId || filterCategoryId) && (
                    <button 
                        onClick={resetFilters}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        title="Скинути фільтри"
                    >
                        <X size={16} />
                    </button>
                )}
            </div>
        </div>

        {/* List Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar pb-32 px-4 pt-2">
            {sortedTransactions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400 text-center">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p>Транзакцій не знайдено за цими фільтрами.</p>
                    <button onClick={resetFilters} className="mt-4 text-primary text-sm font-medium hover:underline">
                        Скинути фільтри
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {Object.entries(grouped).map(([date, items]: [string, Transaction[]]) => (
                        <div key={date} className="animate-fade-in">
                        <div className="flex items-center gap-2 mb-2 sticky top-0 bg-background/95 backdrop-blur py-2 z-10">
                            <Calendar size={14} className="text-gray-500" />
                            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            {formatDate(date)}
                            </h3>
                        </div>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
                            {items.map(t => {
                            const category = categories.find(c => c.id === t.categoryId);
                            const account = accounts.find(a => a.id === t.accountId);
                            const toAccount = t.toAccountId ? accounts.find(a => a.id === t.toAccountId) : null;

                            const isExpense = t.type === TransactionType.EXPENSE;
                            const isTransfer = t.type === TransactionType.TRANSFER;

                            // Determine visual style
                            let amountClass = 'text-gray-900';
                            let sign = '';
                            const absAmount = Math.abs(t.amount);

                            if (isTransfer) {
                                amountClass = 'text-blue-600';
                            } else if (isExpense) {
                                if (t.amount < 0) {
                                    // Storno/Refund (Negative Expense) -> Green +
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                } else {
                                    // Normal Expense -> Gray -
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                }
                            } else {
                                // Income
                                if (t.amount < 0) {
                                    // Negative Income (Correction) -> Gray -
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                } else {
                                    // Normal Income -> Green +
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                }
                            }

                            return (
                                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    {/* Icon Circle */}
                                    {isTransfer ? (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 bg-blue-500 shadow-sm">
                                        <CategoryIcon iconName="transfer" size={20} />
                                        </div>
                                    ) : (
                                        <div 
                                        className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm`}
                                        style={{ backgroundColor: category?.color || '#ccc' }}
                                        >
                                            <CategoryIcon iconName={category?.icon || 'help-circle'} size={20} />
                                        </div>
                                    )}

                                    {/* Text Info */}
                                    <div className="min-w-0 flex-1">
                                    <div className="font-semibold text-gray-900 truncate pr-2 text-sm">
                                        {isTransfer ? 'Переказ коштів' : (category?.name || 'Без категорії')}
                                    </div>
                                    <div className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                        {/* Account Info */}
                                        {isTransfer ? (
                                            <span className="truncate flex items-center gap-1">
                                                {account?.name} → {toAccount?.name}
                                            </span>
                                        ) : (
                                            <span className="truncate font-medium">{account?.name}</span>
                                        )}

                                        {/* Note */}
                                        {t.note && (
                                            <>
                                                <span className="shrink-0 text-gray-300">|</span>
                                                <span className="italic truncate text-gray-400">{t.note}</span>
                                            </>
                                        )}
                                    </div>
                                    </div>
                                </div>

                                {/* Amount & Actions */}
                                <div className="flex items-center gap-3 pl-2 shrink-0">
                                    <div className="text-right">
                                        {isTransfer && t.toAmount ? (
                                            <div className="flex flex-col items-end">
                                                <span className="text-red-500 font-bold text-sm">-{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {t.currency}</span>
                                                <span className="text-emerald-500 font-bold text-sm">+{t.toAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {toAccount?.currency}</span>
                                            </div>
                                        ) : (
                                            <div className={`font-bold text-base ${amountClass}`}>
                                                {sign}{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} 
                                                <span className="text-xs font-normal text-gray-400 ml-1">{t.currency}</span>
                                            </div>
                                        )}
                                    </div>

                                    {isEditMode && (
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    onEdit(t);
                                                }}
                                                className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                                            >
                                                <Pencil size={16} />
                                            </button>
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    if(window.confirm('Видалити цей запис?')) {
                                                        onDelete(t.id);
                                                    }
                                                }}
                                                className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                                </div>
                            );
                            })}
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

      {/* Lock Button - Fixed Bottom Left */}
      <div className="fixed bottom-28 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

import { AppData } from '../types';
import { INITIAL_DATA } from '../constants';

const STORAGE_KEY = 'domfin_ua_data_v1';

export const saveToStorage = (data: AppData): void => {
  try {
    const json = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, json);
  } catch (e) {
    console.error('Failed to save data', e);
  }
};

export const loadFromStorage = (): AppData => {
  try {
    const json = localStorage.getItem(STORAGE_KEY);
    if (!json) return INITIAL_DATA;
    return JSON.parse(json);
  } catch (e) {
    console.error('Failed to load data', e);
    return INITIAL_DATA;
  }
};

// Generates the JSON string for the UI to display/use
export const getExportDataString = (data: AppData): string => {
  return JSON.stringify(data, null, 2);
};

// Generates the filename
export const getExportFileName = (): string => {
    return `budget_backup_${new Date().toISOString().split('T')[0]}.json`;
};

// Attempt to download purely via browser API
export const triggerBrowserDownload = (jsonString: string, fileName: string) => {
    const blob = new Blob([jsonString], { type: "application/json" });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
};

// Robust share function that tries to share as a File first (Android "Save to..."), then as text
export const shareData = async (jsonString: string, fileName: string): Promise<boolean> => {
    // 1. Try to share as a physical file (Best for Android "Save to Files" or Messengers)
    if (navigator.canShare && navigator.share) {
        try {
            const file = new File([jsonString], fileName, { type: "application/json" });
            const shareData = {
                files: [file],
                title: 'Резервна копія бюджету',
                text: 'Файл даних додатку'
            };

            if (navigator.canShare(shareData)) {
                await navigator.share(shareData);
                return true;
            }
        } catch (e) {
            console.warn("File sharing failed, falling back to text", e);
        }
    }

    // 2. Fallback: Share as plain text
    if (navigator.share) {
        try {
            await navigator.share({
                title: 'Резервна копія (JSON)',
                text: jsonString
            });
            return true;
        } catch (e) {
            console.warn("Text sharing failed", e);
        }
    }

    return false;
};

export const importDataFromFile = (file: File): Promise<AppData> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = event.target?.result as string;
        const data = JSON.parse(json);
        // Basic validation
        if (!data.transactions || !data.accounts) {
          throw new Error("Invalid format");
        }
        resolve(data);
      } catch (e) {
        reject(e);
      }
    };
    reader.readAsText(file);
  });
};

export const importDataFromString = (jsonString: string): AppData => {
    try {
        const data = JSON.parse(jsonString);
        if (!data.transactions || !data.accounts) {
            throw new Error("Invalid format");
        }
        return data;
    } catch (e) {
        throw e;
    }
};

