      if (groupType === AccountType.SAVINGS) targetGroup = savings;
      if (groupType === AccountType.DEBT) targetGroup = debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }

      // Reconstruct full list (order matters: Current -> Savings -> Debt)
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (
      title: string, 
      type: AccountType,
      Icon: React.ElementType,
      headerColorClass: string
  ) => {
    let group = groupAccounts(type);

    // Filter hidden accounts if not in edit mode
    if (!isEditMode) {
        group = group.filter(a => !a.isHidden);
    }

    // Don't show empty groups unless in edit mode
    if (group.length === 0 && !isEditMode) return null;

    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden mb-6 animate-fade-in">
        {/* Header: Title Left, Totals Right (Matching Overview/Budget Style) */}
        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
           <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}>
                    <Icon size={18} className={headerColorClass.replace('bg-', 'text-')} />
                </div>
                <div>
                    <h3 className="font-bold text-gray-800 text-base">{title}</h3>
                </div>
           </div>
           <div className="text-right whitespace-nowrap">
                <span className="text-lg font-bold text-gray-900 leading-none">
                    {totalInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} 
                    <span className="text-xs font-medium text-gray-400 ml-1">UAH</span>
                </span>
           </div>
        </div>

        <div className="divide-y divide-gray-50">
          {group.map((account, index) => {
            const rawBalance = getBalance(account);
            const balance = Math.abs(rawBalance) < 0.005 ? 0 : rawBalance;
            const isHidden = !!account.isHidden;

            // Calculate UAH equivalent for foreign currencies
            const rate = rates[account.currency] || 1;
            const balanceInUAH = balance * rate;

            return (
              <div 
                key={account.id} 
                onClick={() => {
                    if (!isEditMode) onSelectAccount(account.id);
                }}
                className={`p-3 flex items-center justify-between group hover:bg-gray-50 transition-colors relative ${!isEditMode ? 'cursor-pointer active:bg-gray-100' : ''} ${isHidden ? 'opacity-60 bg-gray-50' : ''}`}
              >
                 {/* Left Side: Icon & Name */}
                 <div className="flex items-center gap-3 overflow-hidden flex-1">
                    <div 
                      className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm ${isHidden ? 'bg-gray-400' : ''}`}
                      style={{ backgroundColor: isHidden ? undefined : account.color }}
                    >
                        <CategoryIcon iconName={account.icon || 'wallet'} size={20} />
                    </div>
                    <div className="min-w-0">
                        <div className={`font-bold text-sm truncate pr-2 ${isHidden ? 'text-gray-500' : 'text-gray-800'}`}>
                            {account.name} 
                            {isHidden && <span className='text-[10px] font-normal text-gray-400 ml-2 border border-gray-200 px-1 rounded'>Приховано</span>}
                        </div>
                         {/* Show currency badge */}
                         <div className="text-xs text-gray-400 font-medium">
                            {account.currency}
                         </div>
                    </div>
                 </div>

                 {/* Right Side: Balances or Controls */}
                 <div className="flex items-center gap-3 shrink-0">
                      {isEditMode ? (
                         <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200">
                             {/* Reorder Controls */}
                             <div className="flex items-center gap-1 bg-gray-50 p-1 rounded-lg border border-gray-100">
                                 <button 
                                      onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }}
                                      disabled={index === 0}
                                      className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded bg-transparent disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                                 >
                                     <ArrowUp size={14} strokeWidth={2.5} />
                                 </button>
                                 <button 
                                      onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }}
                                      disabled={index === group.length - 1}
                                      className="w-7 h-7 flex items-center justify-center text-gray-500 hover:text-primary hover:bg-white hover:shadow-sm rounded bg-transparent disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                                 >
                                     <ArrowDown size={14} strokeWidth={2.5} />
                                 </button>
                             </div>

                             <button 
                                  onClick={(e) => { e.stopPropagation(); onToggleVisibility(account); }}
                                  className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${account.isHidden ? 'bg-gray-100 text-gray-500' : 'bg-white text-gray-400 hover:text-black border border-gray-100'}`}
                             >
                                 {account.isHidden ? <EyeOff size={14} /> : <Eye size={14} />}
                             </button>

                             <button 
                                  onClick={(e) => { e.stopPropagation(); onEditAccount(account); }}
                                  className="w-8 h-8 flex items-center justify-center bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                              >
                                  <Pencil size={14} />
                              </button>
                              <button 
                                  onClick={(e) => { 
                                      e.stopPropagation(); 
                                      if(window.confirm('Видалити цей рахунок та всі його транзакції?')) {
                                          onDeleteAccount(account.id);
                                      }
                                  }}
                                  className="w-8 h-8 flex items-center justify-center bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                              >
                                  <Trash2 size={14} />
                              </button>
                         </div>
                      ) : (
                          /* Main Balance Display */
                          <div className="flex flex-col items-end">
                              <div className={`font-bold text-sm whitespace-nowrap ${balance < 0 ? 'text-red-500' : 'text-gray-900'}`}>
                                  {balance.toLocaleString('uk-UA', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}
                                  <span className="text-xs font-normal text-gray-400 ml-1">{account.currency}</span>
                              </div>
                              {account.currency !== Currency.UAH && (
                                   <div className="text-[10px] text-gray-400 font-medium">
                                       {balanceInUAH.toLocaleString('uk-UA', { maximumFractionDigits: 0 })} UAH
                                   </div>
                              )}
                          </div>
                      )}
                 </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="pb-32 pt-4 px-4 relative h-full overflow-y-auto no-scrollbar bg-gray-50">
       {/* Header with Title and Edit Toggle */}
       <div className="flex items-center justify-between mb-4 px-1">
          <h2 className="text-2xl font-bold text-gray-800">Рахунки</h2>
          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
          >
              {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
          </button>
      </div>

      {renderAccountGroup('Поточні', AccountType.CURRENT, Wallet, 'bg-blue-500')}
      {renderAccountGroup('Заощадження', AccountType.SAVINGS, PiggyBank, 'bg-emerald-500')}
      {renderAccountGroup('Заборгованість', AccountType.DEBT, CreditCard, 'bg-red-500')}

      {/* Single Add Button at the bottom */}
      {isEditMode && (
          <button 
            onClick={onAddAccount}
            className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 rounded-2xl flex items-center justify-center text-gray-500 hover:border-primary hover:text-primary transition-colors bg-white/50 text-lg font-medium"
          >
              <Plus size={24} className="mr-2" /> Додати рахунок
          </button>
      )}

      {/* Empty State (only if no accounts and not editing) */}
      {accounts.length === 0 && !isEditMode && (
          <div className="text-center text-gray-400 mt-10">
              <Banknote size={48} className="mx-auto mb-2 opacity-20" />
              <p>Рахунків немає</p>
          </div>
      )}
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date; // Usually first day of the month
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
  onResetFilters?: () => void;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, 
  accounts, 
  categories,
  onDelete,
  onEdit,
  initialFilters,
  onResetFilters
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [showFilters, setShowFilters] = useState(true);

  // Filter States
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  // Apply initial filters when they change (navigation from other tabs)
  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      setShowFilters(true);

      // Notify parent that the filter intent has been consumed
      if (onResetFilters) {
          onResetFilters();
      }
    }
  }, [initialFilters, onResetFilters]);

  const resetFilters = () => {
    setFilterMonth(new Date());
    setFilterAccountId('');
    setFilterCategoryId('');
    if (onResetFilters) {
        onResetFilters();
    }
  };

  const prevMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);

      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && 
                        tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;

      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) {
        return false;
      }

      if (filterCategoryId && t.categoryId !== filterCategoryId) {
        return false;
      }

      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  return (
    <div className="h-full flex flex-col">
        {/* Filters Header */}
        <div className="bg-white border-b border-gray-200 px-4 py-3 shadow-sm z-20">
            {/* Month Selector */}
            <div className="flex items-center justify-between mb-3">
                 <button onClick={prevMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronLeft size={20} />
                 </button>
                 <span className="font-bold text-gray-800 capitalize">{monthLabel}</span>
                 <button onClick={nextMonth} className="p-1 rounded-full hover:bg-gray-100 text-gray-500">
                    <ChevronRight size={20} />
                 </button>
            </div>

            {/* Dropdowns */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <select 
                        value={filterAccountId}
                        onChange={(e) => setFilterAccountId(e.target.value)}
                        className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterAccountId ? 'bg-blue-50 border-blue-200 text-blue-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі рахунки</option>
                        {accounts.map(a => (
                            <option key={a.id} value={a.id}>{a.name}</option>
                        ))}
                    </select>
                </div>

                <div className="relative flex-1">
                    <select 
                        value={filterCategoryId}
                        onChange={(e) => setFilterCategoryId(e.target.value)}
                         className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterCategoryId ? 'bg-emerald-50 border-emerald-200 text-emerald-700 font-medium' : 'bg-gray-50 border-gray-200 text-gray-600'}`}
                    >
                        <option value="">Всі категорії</option>
                        {categories.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {(filterAccountId || filterCategoryId) && (
                    <button 
                        onClick={resetFilters}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        title="Скинути фільтри"
                    >
                        <X size={16} />
                    </button>
                )}
            </div>
        </div>

        {/* List Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar pb-32 px-4 pt-2">
            {sortedTransactions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400 text-center">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p>Транзакцій не знайдено за цими фільтрами.</p>
                    <button onClick={resetFilters} className="mt-4 text-primary text-sm font-medium hover:underline">
                        Скинути фільтри
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {Object.entries(grouped).map(([date, items]: [string, Transaction[]]) => (
                        <div key={date} className="animate-fade-in">
                        <div className="flex items-center gap-2 mb-2 sticky top-0 bg-background/95 backdrop-blur py-2 z-10">
                            <Calendar size={14} className="text-gray-500" />
                            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            {formatDate(date)}
                            </h3>
                        </div>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
                            {items.map(t => {
                            const category = categories.find(c => c.id === t.categoryId);
                            const account = accounts.find(a => a.id === t.accountId);
                            const toAccount = t.toAccountId ? accounts.find(a => a.id === t.toAccountId) : null;

                            const isExpense = t.type === TransactionType.EXPENSE;
                            const isTransfer = t.type === TransactionType.TRANSFER;

                            let amountClass = 'text-gray-900';
                            let sign = '';
                            const absAmount = Math.abs(t.amount);

                            if (isTransfer) {
                                amountClass = 'text-blue-600';
                            } else if (isExpense) {
                                if (t.amount < 0) {
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                } else {
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                }
                            } else {
                                if (t.amount < 0) {
                                    amountClass = 'text-gray-900';
                                    sign = '-';
                                } else {
                                    amountClass = 'text-emerald-600';
                                    sign = '+';
                                }
                            }

                            return (
                                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    {isTransfer ? (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 bg-blue-500 shadow-sm">
                                        <CategoryIcon iconName="transfer" size={20} />
                                        </div>
                                    ) : (
                                        <div 
                                        className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm`}
                                        style={{ backgroundColor: category?.color || '#ccc' }}
                                        >
                                            <CategoryIcon iconName={category?.icon || 'help-circle'} size={20} />
                                        </div>
                                    )}

                                    <div className="min-w-0 flex-1">
                                    <div className="font-semibold text-gray-900 truncate pr-2 text-sm">
                                        {isTransfer ? 'Переказ коштів' : (category?.name || 'Без категорії')}
                                    </div>
                                    <div className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                                        {isTransfer ? (
                                            <span className="truncate flex items-center gap-1">
                                                {account?.name} → {toAccount?.name}
                                            </span>
                                        ) : (
                                            <span className="truncate font-medium">{account?.name}</span>
                                        )}

                                        {t.note && (
                                            <>
                                                <span className="shrink-0 text-gray-300">|</span>
                                                <span className="italic truncate text-gray-400">{t.note}</span>
                                            </>
                                        )}
                                    </div>
                                    </div>
                                </div>

                                <div className="flex items-center gap-3 pl-2 shrink-0">
                                    <div className="text-right">
                                        {isTransfer && t.toAmount ? (
                                            <div className="flex flex-col items-end">
                                                <span className="text-red-500 font-bold text-sm">-{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {t.currency}</span>
                                                <span className="text-emerald-500 font-bold text-sm">+{t.toAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} {toAccount?.currency}</span>
                                            </div>
                                        ) : (
                                            <div className={`font-bold text-base ${amountClass}`}>
                                                {sign}{absAmount.toLocaleString(undefined, { minimumFractionDigits: 0 })} 
                                                <span className="text-xs font-normal text-gray-400 ml-1">{t.currency}</span>
                                            </div>
                                        )}
                                    </div>

                                    {isEditMode && (
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    onEdit(t);
                                                }}
                                                className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-100 transition-colors"
                                            >
                                                <Pencil size={16} />
                                            </button>
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    if(window.confirm('Видалити цей запис?')) {
                                                        onDelete(t.id);
                                                    }
                                                }}
                                                className="p-2 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                                </div>
                            );
                            })}
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

      <div className="fixed bottom-28 left-4 z-30">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600 border border-gray-200'}`}
        >
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, Wallet, Plus, Settings, Calculator } from 'lucide-react';
import { AppData, Transaction, Account, Category } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage } from './services/storageService';
import { OverviewTab } from './components/OverviewTab';
import { TransactionList, TransactionFilters } from './components/TransactionList';
import { AccountsTab } from './components/AccountsTab';
import { BudgetTab } from './components/BudgetTab';
import { AddTransactionModal } from './components/AddTransactionModal';
import { AccountModal } from './components/AccountModal';
import { CategoryModal } from './components/CategoryModal';
import { DataManagementModal } from './components/DataManagementModal';

// Simple UUID generator fallback since we can't install packages freely
const generateId = () => Math.random().toString(36).substr(2, 9);

export default function App() {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'accounts' | 'budget'>('overview');
  const [data, setData] = useState<AppData>(INITIAL_DATA);

  // Navigation & Filtering State
  const [transactionFilters, setTransactionFilters] = useState<TransactionFilters | null>(null);

  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);

  const [editingAccount, setEditingAccount] = useState<Account | undefined>(undefined);
  const [editingCategory, setEditingCategory] = useState<Category | undefined>(undefined);
  const [editingCategoryDate, setEditingCategoryDate] = useState<Date>(new Date()); // Context for budget editing
  const [editingTransaction, setEditingTransaction] = useState<Transaction | undefined>(undefined);

  // Load data on mount
  useEffect(() => {
    const loaded = loadFromStorage();

    // Migration: ensure rates exist
    if (!loaded.rates) {
        loaded.rates = INITIAL_DATA.rates;
    }

    // Migration: ensure accounts have types and icons
    if (loaded.accounts) {
       loaded.accounts = loaded.accounts.map(a => {
           let updated = { ...a };
           // @ts-ignore
           if (!updated.type) updated.type = 'CURRENT';
           if (!updated.currentRate) updated.currentRate = 1;
           if (!updated.icon) {
               const nameLower = updated.name.toLowerCase();
               if (nameLower.includes('карт') || nameLower.includes('card')) updated.icon = 'credit-card';
               else if (nameLower.includes('банк') || nameLower.includes('bank')) updated.icon = 'landmark';
               else if (nameLower.includes('usd') || nameLower.includes('eur')) updated.icon = 'banknote';
               else updated.icon = 'wallet';
           }
           return updated as Account;
       });
    }

    // Migration for categories (budgetHistory)
    if(loaded.categories) {
        loaded.categories = loaded.categories.map(c => {
            const updated = { ...c };
            // Ensure budgetHistory exists. If not, migrate monthlyBudget to a history entry in the past.
            if (!updated.budgetHistory) {
                updated.budgetHistory = {
                    '2023-01': c.monthlyBudget || 0
                };
            }
            // Ensure monthlyBudget is still there for types compatibility, though we prioritize history
            if (updated.monthlyBudget === undefined) updated.monthlyBudget = 0;
            return updated;
        });
    }

    setData(loaded);
  }, []);

  // Auto-save on change
  useEffect(() => {
    saveToStorage(data);
  }, [data]);

  const saveTransaction = (t: Transaction | Omit<Transaction, 'id'>) => {
    if ('id' in t) {
        // Edit existing
        setData(prev => ({
            ...prev,
            transactions: prev.transactions.map(tr => tr.id === t.id ? t as Transaction : tr)
        }));
    } else {
        // Create new
        const newTransaction: Transaction = {
          ...t,
          id: generateId()
        };
        setData(prev => ({
          ...prev,
          transactions: [...prev.transactions, newTransaction]
        }));
    }
  };

  const openEditTransaction = (t: Transaction) => {
      setEditingTransaction(t);
      setIsTransactionModalOpen(true);
  };

  const deleteTransaction = (id: string) => {
    setData(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
  };

  // --- Account Handlers ---
  const saveAccount = (accountData: Omit<Account, 'id'> | Account) => {
    if ('id' in accountData) {
        // Edit existing
        setData(prev => ({
            ...prev,
            accounts: prev.accounts.map(a => a.id === accountData.id ? accountData as Account : a)
        }));
    } else {
        // Create new
        const newAccount: Account = {
            ...accountData,
            id: generateId()
        };
        setData(prev => ({
            ...prev,
            accounts: [...prev.accounts, newAccount]
        }));
    }
  };

  const reorderAccounts = (newAccounts: Account[]) => {
      setData(prev => ({
          ...prev,
          accounts: newAccounts
      }));
  };

  const toggleAccountVisibility = (account: Account) => {
      const updatedAccount = { ...account, isHidden: !account.isHidden };
      saveAccount(updatedAccount);
  };

  const deleteAccount = (id: string) => {
    setData(prev => ({
        ...prev,
        accounts: prev.accounts.filter(a => a.id !== id),
        transactions: prev.transactions.filter(t => t.accountId !== id)
    }));
  };

  const openAddAccount = () => {
    setEditingAccount(undefined);
    setIsAccountModalOpen(true);
  };

  const openEditAccount = (account: Account) => {
    setEditingAccount(account);
    setIsAccountModalOpen(true);
  };

  // --- Category Handlers ---
  const saveCategory = (catData: Omit<Category, 'id'> | Category) => {
    // Determine the month key for the current editing context
    const monthKey = editingCategoryDate.toISOString().slice(0, 7); // "YYYY-MM"

    if ('id' in catData) {
        setData(prev => ({
            ...prev,
            categories: prev.categories.map(c => {
                if (c.id === catData.id) {
                    const newBudget = catData.monthlyBudget;
                    const oldHistory = c.budgetHistory || {};

                    // Logic: Update history for this month. 
                    const newHistory = { ...oldHistory };

                    // 1. Set current month
                    newHistory[monthKey] = newBudget;

                    // 2. Delete all future keys
                    Object.keys(newHistory).forEach(key => {
                        if (key > monthKey) {
                            delete newHistory[key];
                        }
                    });

                    return {
                        ...catData,
                        budgetHistory: newHistory
                    } as Category;
                }
                return c;
            })
        }));
    } else {
        // New Category
        const newCat: Category = {
            ...catData,
            id: generateId(),
            budgetHistory: {
                [monthKey]: catData.monthlyBudget // Start history from current view month
            }
        } as Category;

        setData(prev => ({
            ...prev,
            categories: [...prev.categories, newCat]
        }));
    }
  };

  const reorderCategories = (newCategories: Category[]) => {
      setData(prev => ({
          ...prev,
          categories: newCategories
      }));
  };

  const deleteCategory = (id: string) => {
    setData(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c.id !== id)
    }));
  };

  const openAddCategory = (date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(undefined);
      setIsCategoryModalOpen(true);
  };

  const openEditCategory = (cat: Category, date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(cat);
      setIsCategoryModalOpen(true);
  };

  const handleDataImport = (newData: AppData) => {
      setData(newData);
      alert('Дані успішно імпортовано!');
  };

  const handleUpdateRates = (newRates: Record<string, number>) => {
      setData(prev => ({
          ...prev,
          rates: newRates
      }));
  };

  // --- Navigation & Filtering Handlers ---
  const handleOverviewCategoryClick = (categoryId: string, date: Date) => {
    setTransactionFilters({
        categoryId,
        date,
        accountId: ''
    });
    setActiveTab('transactions');
  };

  const handleAccountSelect = (accountId: string) => {
    setTransactionFilters({
        accountId,
        date: new Date(), // Default to current month, user can change
        categoryId: ''
    });
    setActiveTab('transactions');
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 w-full overflow-hidden relative">

      {/* Main Content Area */}
      <main className="flex-1 overflow-hidden relative w-full pt-safe">
        {activeTab === 'overview' && (
            <OverviewTab 
                transactions={data.transactions} 
                categories={data.categories}
                onCategoryClick={handleOverviewCategoryClick} 
            />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
                onEdit={openEditTransaction}
                initialFilters={transactionFilters}
                onResetFilters={() => setTransactionFilters(null)}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                rates={data.rates}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
                onSelectAccount={handleAccountSelect}
                onReorderAccounts={reorderAccounts}
                onToggleVisibility={toggleAccountVisibility}
            />
        )}
        {activeTab === 'budget' && (
            <BudgetTab 
                categories={data.categories}
                onAddCategory={openAddCategory}
                onEditCategory={openEditCategory}
                onDeleteCategory={deleteCategory}
                onReorderCategories={reorderCategories}
            />
        )}
      </main>

      {/* FAB - Add Button */}
      <div className="absolute bottom-28 right-4 z-30">
          <button 
            onClick={() => {
                setEditingTransaction(undefined);
                setIsTransactionModalOpen(true);
            }}
            className="w-14 h-14 bg-primary rounded-full shadow-lg shadow-emerald-300 text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          >
              <Plus size={32} />
          </button>
      </div>

      {/* Bottom Navigation */}
      <nav className="bg-white border-t border-gray-200 pb-safe pt-2 px-2 flex justify-between items-center z-20 pb-4">
        <button 
            onClick={() => setActiveTab('overview')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'overview' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <LayoutDashboard size={22} strokeWidth={activeTab === 'overview' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Огляд</span>
        </button>
        <button 
            onClick={() => setActiveTab('transactions')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'transactions' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <List size={22} strokeWidth={activeTab === 'transactions' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Транз.</span>
        </button>
        <button 
            onClick={() => setActiveTab('budget')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'budget' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Calculator size={22} strokeWidth={activeTab === 'budget' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Бюджет</span>
        </button>
        <button 
            onClick={() => setActiveTab('accounts')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] ${activeTab === 'accounts' ? 'text-primary' : 'text-gray-400 hover:text-gray-600'}`}
        >
            <Wallet size={22} strokeWidth={activeTab === 'accounts' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Рахунки</span>
        </button>
        <button 
            onClick={() => setIsDataModalOpen(true)}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors min-w-[60px] text-gray-400 hover:text-gray-600`}
        >
            <Settings size={22} />
            <span className="text-[10px] font-medium">Налашт.</span>
        </button>
      </nav>

      {/* Modals */}
      <AddTransactionModal 
        isOpen={isTransactionModalOpen} 
        onClose={() => setIsTransactionModalOpen(false)} 
        onSave={saveTransaction}
        accounts={data.accounts}
        categories={data.categories}
        initialData={editingTransaction}
        rates={data.rates}
      />

      <AccountModal 
        isOpen={isAccountModalOpen}
        onClose={() => setIsAccountModalOpen(false)}
        onSave={saveAccount}
        initialData={editingAccount}
      />

      <CategoryModal 
        isOpen={isCategoryModalOpen}
        onClose={() => setIsCategoryModalOpen(false)}
        onSave={saveCategory}
        initialData={editingCategory}
        targetDate={editingCategoryDate} // Pass date context
      />

      <DataManagementModal
        isOpen={isDataModalOpen}
        onClose={() => setIsDataModalOpen(false)}
        currentData={data}
        onImport={handleDataImport}
        onUpdateRates={handleUpdateRates}
      />
    </div>
  );
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER'
}

export enum Currency {
  UAH = 'UAH',
  USD = 'USD',
  EUR = 'EUR'
}

export enum AccountType {
  CURRENT = 'CURRENT',
  DEBT = 'DEBT',
  SAVINGS = 'SAVINGS'
}

export interface UserSettings {
  numberFormat: 'integer' | 'decimal';
  theme: 'light' | 'dark';
}

export interface Account {
  id: string;
  name: string;
  currency: Currency;
  initialBalance: number;
  color: string;
  icon: string;
  type: AccountType;
  currentRate: number;
  isHidden?: boolean;
}

export interface Category {
  id: string;
  name: string;
  type: TransactionType;
  icon: string;
  color: string;
  monthlyBudget: number;
  budgetHistory?: Record<string, number>;
}

export interface Transaction {
  id: string;
  date: string;
  amount: number;
  currency: Currency;
  exchangeRate: number;
  accountId: string;
  toAccountId?: string;
  toAmount?: number;
  categoryId: string;
  note?: string;
  type: TransactionType;
}

export interface AppData {
  accounts: Account[];
  categories: Category[];
  transactions: Transaction[];
  rates: Record<string, number>;
  settings: UserSettings;
}

