                                {currentData.settings.numberFormat === 'integer' && <Check size={20} />}
                            </button>
                            <button onClick={() => updateSetting('numberFormat', 'decimal')} className={`w-full flex items-center justify-between p-4 rounded-2xl border transition-all ${currentData.settings.numberFormat === 'decimal' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-primary text-primary' : 'bg-gray-50 dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-gray-500'}`}>
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-lg bg-gray-200 dark:bg-gray-800 flex items-center justify-center font-bold text-gray-600 dark:text-gray-400">.00</div>
                                    <span className="font-bold">Два знаки після коми</span>
                                </div>
                                {currentData.settings.numberFormat === 'decimal' && <Check size={20} />}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'export' && (
                <div className="space-y-4">
                    <p className="text-sm text-gray-500">Збережіть файл для резервного копіювання.</p>
                    <div className="grid grid-cols-2 gap-3">
                        <Button variant="secondary" onClick={handleDownload}><Download size={16} /> Файл</Button>
                        <Button variant="secondary" onClick={handleShare}><Share2 size={16} /> Поділитись</Button>
                    </div>
                    <div className="relative">
                        <textarea readOnly value={exportString} className="w-full h-48 p-3 text-xs font-mono bg-gray-50 dark:bg-gray-900 dark:text-gray-300 border border-gray-200 dark:border-gray-700 rounded-xl" />
                        <button onClick={handleCopy} className={`absolute top-2 right-2 p-2 rounded-lg text-xs font-bold border ${copyStatus ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 border-green-200' : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300'}`}>{copyStatus ? <Check size={14} /> : <Copy size={14} />}</button>
                    </div>
                </div>
            )}

            {activeTab === 'import' && (
                <div className="space-y-4">
                    <div className="bg-yellow-50 dark:bg-yellow-900/20 p-3 rounded-lg border border-yellow-100 dark:border-yellow-800 text-sm text-yellow-800 dark:text-yellow-200 flex gap-2"><AlertCircle size={16} className="shrink-0 mt-0.5" /><span>Заміна всіх даних!</span></div>
                    <textarea value={importText} onChange={(e) => setImportText(e.target.value)} placeholder='Вставте JSON...' className="w-full h-32 p-3 text-xs font-mono bg-white dark:bg-gray-900 dark:text-white border border-gray-300 dark:border-gray-700 rounded-xl" />
                    {importError && <p className="text-xs text-red-500">{importError}</p>}
                    <Button fullWidth onClick={handleManualImport} disabled={!importText}>Відновити</Button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType, UserSettings } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date;
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
  onResetFilters?: () => void;
  settings: UserSettings;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, accounts, categories, onDelete, onEdit, initialFilters, onResetFilters, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      if (onResetFilters) onResetFilters();
    }
  }, [initialFilters, onResetFilters]);

  const resetFilters = () => {
    setFilterMonth(new Date());
    setFilterAccountId('');
    setFilterCategoryId('');
    if (onResetFilters) onResetFilters();
  };

  const prevMonth = () => setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  const nextMonth = () => setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);
      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;
      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) return false;
      if (filterCategoryId && t.categoryId !== filterCategoryId) return false;
      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  return (
    <div className="h-full flex flex-col bg-gray-50 dark:bg-gray-900 transition-colors">
        <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 px-4 py-3 shadow-sm z-20 transition-colors">
            <div className="flex items-center justify-between mb-3">
                 <button onClick={prevMonth} className="p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-500"><ChevronLeft size={20} /></button>
                 <span className="font-bold text-gray-800 dark:text-gray-100 capitalize">{monthLabel}</span>
                 <button onClick={nextMonth} className="p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-500"><ChevronRight size={20} /></button>
            </div>
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <select value={filterAccountId} onChange={(e) => setFilterAccountId(e.target.value)}
                        className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterAccountId ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800 text-blue-700 dark:text-blue-300 font-medium' : 'bg-gray-50 dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400'}`}
                    >
                        <option value="">Всі рахунки</option>
                        {accounts.map(a => (<option key={a.id} value={a.id}>{a.name}</option>))}
                    </select>
                </div>
                <div className="relative flex-1">
                    <select value={filterCategoryId} onChange={(e) => setFilterCategoryId(e.target.value)}
                         className={`w-full p-2 pl-2 pr-6 text-xs rounded-lg border appearance-none focus:ring-2 focus:ring-primary focus:outline-none ${filterCategoryId ? 'bg-emerald-50 dark:bg-emerald-900/30 border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-300 font-medium' : 'bg-gray-50 dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400'}`}
                    >
                        <option value="">Всі категорії</option>
                        {categories.map(c => (<option key={c.id} value={c.id}>{c.name}</option>))}
                    </select>
                </div>
                {(filterAccountId || filterCategoryId) && (
                    <button onClick={resetFilters} className="p-2 text-gray-400 dark:text-gray-500 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"><X size={16} /></button>
                )}
            </div>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar pb-32 px-4 pt-2">
            {sortedTransactions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400 dark:text-gray-600 text-center">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p>Транзакцій не знайдено.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Fix: Explicitly cast Object.entries(grouped) to [string, Transaction[]][] to fix "Property 'map' does not exist on type 'unknown'" */}
                    {(Object.entries(grouped) as [string, Transaction[]][]).map(([date, items]) => (
                        <div key={date} className="animate-fade-in">
                        <div className="flex items-center gap-2 mb-2 sticky top-0 bg-gray-50/95 dark:bg-gray-900/95 backdrop-blur py-2 z-10 transition-colors">
                            <Calendar size={14} className="text-gray-500 dark:text-gray-600" />
                            <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-600 uppercase tracking-wider">{formatDate(date)}</h3>
                        </div>
                        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden divide-y divide-gray-50 dark:divide-gray-700 transition-colors">
                            {items.map(t => {
                            const category = categories.find(c => c.id === t.categoryId);
                            const account = accounts.find(a => a.id === t.accountId);
                            const toAccount = t.toAccountId ? accounts.find(a => a.id === t.toAccountId) : null;
                            const isExpense = t.type === TransactionType.EXPENSE;
                            const isTransfer = t.type === TransactionType.TRANSFER;
                            let amountClass = 'text-gray-900 dark:text-gray-100';
                            let sign = '';
                            const absAmount = Math.abs(t.amount);

                            if (isTransfer) amountClass = 'text-blue-600 dark:text-blue-400';
                            else if (isExpense) {
                                if (t.amount < 0) { amountClass = 'text-emerald-600 dark:text-emerald-400'; sign = '+'; }
                                else { amountClass = 'text-gray-900 dark:text-gray-100'; sign = '-'; }
                            } else {
                                if (t.amount < 0) { amountClass = 'text-gray-900 dark:text-gray-100'; sign = '-'; }
                                else { amountClass = 'text-emerald-600 dark:text-emerald-400'; sign = '+'; }
                            }

                            return (
                                <div key={t.id} className="p-3 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    {isTransfer ? (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 bg-blue-500 shadow-sm"><CategoryIcon iconName="transfer" size={20} /></div>
                                    ) : (
                                        <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm" style={{ backgroundColor: category?.color || '#ccc' }}><CategoryIcon iconName={category?.icon || 'help-circle'} size={20} /></div>
                                    )}
                                    <div className="min-w-0 flex-1">
                                        <div className="font-semibold text-gray-900 dark:text-gray-100 truncate pr-2 text-sm">{isTransfer ? 'Переказ коштів' : (category?.name || 'Без категорії')}</div>
                                        <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-1 mt-0.5">
                                            {isTransfer ? <span className="truncate flex items-center gap-1">{account?.name} → {toAccount?.name}</span> : <span className="truncate font-medium">{account?.name}</span>}
                                            {t.note && <><span className="shrink-0 text-gray-300 dark:text-gray-700">|</span><span className="italic truncate text-gray-400 dark:text-gray-500">{t.note}</span></>}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 pl-2 shrink-0">
                                    <div className="text-right">
                                        {isTransfer && t.toAmount ? (
                                            <div className="flex flex-col items-end">
                                                <span className="text-red-500 dark:text-red-400 font-bold text-sm">-{formatValue(absAmount)} {t.currency}</span>
                                                <span className="text-emerald-500 dark:text-emerald-400 font-bold text-sm">+{formatValue(t.toAmount)} {toAccount?.currency}</span>
                                            </div>
                                        ) : (
                                            <div className={`font-bold text-base ${amountClass}`}>
                                                {sign}{formatValue(absAmount)} <span className="text-xs font-normal text-gray-400 dark:text-gray-500 ml-1">{t.currency}</span>
                                            </div>
                                        )}
                                    </div>
                                    {isEditMode && (
                                        <div className="flex items-center gap-2">
                                            <button onClick={(e) => { e.stopPropagation(); onEdit(t); }} className="p-2 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={16} /></button>
                                            <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDelete(t.id); }} className="p-2 bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={16} /></button>
                                        </div>
                                    )}
                                </div>
                                </div>
                            );})}
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

      <div className="fixed bottom-28 left-4 z-30">
        <button onClick={() => setIsEditMode(!isEditMode)} className={`w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isEditMode ? 'bg-orange-500 text-white' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 border border-gray-200 dark:border-gray-700'}`}>
            {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Category, Currency, Transaction, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X, ArrowRightLeft, AlertCircle, RefreshCw } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Omit<Transaction, 'id'> | Transaction) => void;
  accounts: Account[];
  categories: Category[];
  initialData?: Transaction;
  rates?: Record<string, number>;
}

export const AddTransactionModal: React.FC<AddTransactionModalProps> = ({
  isOpen, onClose, onSave, accounts, categories, initialData, rates
}) => {
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [amount, setAmount] = useState('');
  const [toAmount, setToAmount] = useState(''); 
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountId, setAccountId] = useState('');
  const [toAccountId, setToAccountId] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [rate, setRate] = useState('1');
  const [note, setNote] = useState('');

  const [validationError, setValidationError] = useState<string | null>(null);

  const visibleAccounts = useMemo(() => {
    return accounts.filter(a => !a.isHidden || (initialData && (a.id === initialData.accountId || (initialData.type === TransactionType.TRANSFER && a.id === initialData.toAccountId))));
  }, [accounts, initialData]);

  useEffect(() => {
    if (isOpen) {
        if (initialData) {
            setType(initialData.type);
            setAmount(initialData.amount.toString());
            setDate(initialData.date.split('T')[0]);
            setAccountId(initialData.accountId);
            setCurrency(initialData.currency);
            setRate(initialData.exchangeRate.toString());
            setNote(initialData.note || '');

            if (initialData.type === TransactionType.TRANSFER) {
                setToAccountId(initialData.toAccountId || '');
                setToAmount(initialData.toAmount ? initialData.toAmount.toString() : '');
                setCategoryId('');
            } else {
                setCategoryId(initialData.categoryId);
                setToAccountId('');
                setToAmount('');
            }
        } else {
            setType(TransactionType.EXPENSE);
            setAmount('');
            setToAmount('');
            setDate(new Date().toISOString().split('T')[0]);

            const activeAccounts = accounts.filter(a => !a.isHidden);
            const defaultAcc = activeAccounts[0] || accounts[0];
            setAccountId(defaultAcc?.id || '');
            setCurrency(defaultAcc?.currency || Currency.UAH);

            if (rates && defaultAcc?.currency !== Currency.UAH) {
                setRate(rates[defaultAcc.currency]?.toString() || '1');
            } else {
                setRate('1');
            }

            setToAccountId('');
            const defaultCat = categories.find(c => c.type === TransactionType.EXPENSE);
            setCategoryId(defaultCat?.id || '');
            setNote('');
        }
    }
  }, [isOpen, initialData, accounts, rates, categories]);

  const sourceAccount = accounts.find(a => a.id === accountId);
  const targetAccount = accounts.find(a => a.id === toAccountId);
  const isMultiCurrencyTransfer = type === TransactionType.TRANSFER && sourceAccount && targetAccount && sourceAccount.currency !== targetAccount.currency;

  useEffect(() => {
    if (!isMultiCurrencyTransfer) {
        setValidationError(null);
        return;
    }
    const srcAmt = parseFloat(amount);
    const dstAmt = parseFloat(toAmount);
    const r = parseFloat(rate);
    if (!srcAmt || !dstAmt || !r) { setValidationError(null); return; }

    const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
    let calculatedDest = isSell ? srcAmt * r : srcAmt / r;
    if (Math.abs(calculatedDest - dstAmt) > 1.0) setValidationError('Суми не відповідають вказаному курсу');
    else setValidationError(null);
  }, [amount, toAmount, rate, isMultiCurrencyTransfer, sourceAccount, targetAccount]);

  const handleAmountChange = (val: string) => {
      setAmount(val);
      if (isMultiCurrencyTransfer && rate && val) {
          const s = parseFloat(val);
          const r = parseFloat(rate);
          if (!isNaN(s) && !isNaN(r) && r !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              const newTo = isSell ? s * r : s / r;
              setToAmount(parseFloat(newTo.toFixed(2)).toString());
          }
      }
  };

  const handleToAmountChange = (val: string) => {
      setToAmount(val);
      if (isMultiCurrencyTransfer && amount && val) {
          const s = parseFloat(amount);
          const d = parseFloat(val);
          if (!isNaN(s) && !isNaN(d) && d !== 0 && s !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              const newRate = isSell ? d / s : s / d;
              setRate(parseFloat(newRate.toFixed(4)).toString());
          }
      }
  };

  const handleRateChange = (val: string) => {
      setRate(val);
      if (isMultiCurrencyTransfer && amount && val) {
          const s = parseFloat(amount);
          const r = parseFloat(val);
          if (!isNaN(s) && !isNaN(r) && r !== 0) {
              const isSell = sourceAccount?.currency !== Currency.UAH && targetAccount?.currency === Currency.UAH;
              const newTo = isSell ? s * r : s / r;
              setToAmount(parseFloat(newTo.toFixed(2)).toString());
          }
      }
  };

  const handleTypeChange = (newType: TransactionType) => {
      setType(newType);
      if (newType !== TransactionType.TRANSFER) {
          const firstCat = categories.find(c => c.type === newType);
          setCategoryId(firstCat?.id || '');
      } else {
          setCategoryId('');
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !accountId) return;
    if (type !== TransactionType.TRANSFER && !categoryId) return;
    if (type === TransactionType.TRANSFER) {
        if (!toAccountId || accountId === toAccountId) { alert("Оберіть інший рахунок"); return; }
        if (isMultiCurrencyTransfer && (!toAmount || (validationError && !confirm("Зберегти як є?")))) return;
    }

    const transactionData = {
      date: new Date(date).toISOString(),
      amount: parseFloat(amount),
      currency: currency,
      exchangeRate: sourceAccount?.currency !== Currency.UAH ? parseFloat(rate) : 1,
      accountId,
      toAccountId: type === TransactionType.TRANSFER ? toAccountId : undefined,
      toAmount: (type === TransactionType.TRANSFER && toAmount) ? parseFloat(toAmount) : undefined,
      categoryId: type === TransactionType.TRANSFER ? 'transfer' : categoryId,
      note,
      type
    };

    onSave(initialData ? { ...transactionData, id: initialData.id } : transactionData);
    onClose();
  };

  if (!isOpen) return null;
  const filteredCategories = categories.filter(c => c.type === type);

  const handleAccountChange = (id: string) => {
    setAccountId(id);
    const acc = accounts.find(a => a.id === id);
    if (acc) {
        setCurrency(acc.currency);
        setRate(acc.currency === Currency.UAH ? '1' : (rates?.[acc.currency]?.toString() || String(acc.currentRate)));
        if (type === TransactionType.TRANSFER && id === toAccountId) setToAccountId('');
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in p-0 sm:p-4">
      <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[95vh] transition-colors">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100">{initialData ? 'Редагувати' : 'Нова транзакція'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex p-1 bg-gray-100 dark:bg-gray-900 rounded-lg mb-6">
            <button type="button" onClick={() => handleTypeChange(TransactionType.EXPENSE)} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white dark:bg-gray-800 shadow text-red-500' : 'text-gray-500 dark:text-gray-400'}`}>Витрата</button>
            <button type="button" onClick={() => handleTypeChange(TransactionType.INCOME)} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white dark:bg-gray-800 shadow text-emerald-500' : 'text-gray-500 dark:text-gray-400'}`}>Дохід</button>
            <button type="button" onClick={() => handleTypeChange(TransactionType.TRANSFER)} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${type === TransactionType.TRANSFER ? 'bg-white dark:bg-gray-800 shadow text-blue-500' : 'text-gray-500 dark:text-gray-400'}`}>Трансфер</button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
            {type === TransactionType.TRANSFER ? (
                <div className="flex items-center gap-2">
                    <div className="flex-1">
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">З рахунку</label>
                        <select value={accountId} onChange={(e) => handleAccountChange(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary text-sm">
                            {visibleAccounts.map(a => <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>)}
                        </select>
                    </div>
                    <div className="pt-5 text-gray-400"><ArrowRightLeft size={18} /></div>
                    <div className="flex-1">
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">На рахунок</label>
                        <select value={toAccountId} onChange={(e) => setToAccountId(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary text-sm">
                            <option value="">Оберіть...</option>
                            {visibleAccounts.filter(a => a.id !== accountId).map(a => <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>)}
                        </select>
                    </div>
                </div>
            ) : (
                <div>
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Рахунок</label>
                    <select value={accountId} onChange={(e) => handleAccountChange(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary">
                        {visibleAccounts.map(a => <option key={a.id} value={a.id}>{a.name} ({a.currency})</option>)}
                    </select>
                </div>
            )}

            {isMultiCurrencyTransfer ? (
                <div className={`p-4 rounded-xl space-y-3 border ${validationError ? 'bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-800' : 'bg-blue-50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-800'}`}>
                    <div>
                        <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Списання ({sourceAccount?.currency})</label>
                        <input type="number" step="0.01" required value={amount} onChange={(e) => handleAmountChange(e.target.value)} className="w-full p-2 rounded-lg bg-white dark:bg-gray-800 dark:text-white border-none shadow-sm" />
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="h-px bg-gray-300 dark:bg-gray-700 flex-1"></div>
                        <input type="number" step="0.0001" value={rate} onChange={(e) => handleRateChange(e.target.value)} className="w-20 p-1 text-center text-xs rounded border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 dark:text-white font-bold" />
                        <div className="h-px bg-gray-300 dark:bg-gray-700 flex-1"></div>
                    </div>
                    <div>
                        <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Зарахування ({targetAccount?.currency})</label>
                        <input type="number" step="0.01" required value={toAmount} onChange={(e) => handleToAmountChange(e.target.value)} className="w-full p-2 rounded-lg bg-white dark:bg-gray-800 dark:text-white border-none shadow-sm" />
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Сума</label>
                        <input type="number" step="0.01" required value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary text-lg font-bold" placeholder="0.00" />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Валюта</label>
                        <div className="w-full p-3 bg-gray-100 dark:bg-gray-700 rounded-xl text-gray-600 dark:text-gray-300 font-bold">{currency}</div>
                    </div>
                </div>
            )}

            {type !== TransactionType.TRANSFER && (
                <div>
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Категорія</label>
                    <div className="grid grid-cols-3 gap-2 max-h-40 overflow-y-auto no-scrollbar">
                        {filteredCategories.map(c => (
                            <button key={c.id} type="button" onClick={() => setCategoryId(c.id)} className={`p-2 rounded-lg text-xs border transition-all flex flex-col items-center gap-1 ${categoryId === c.id ? 'border-primary bg-emerald-50 dark:bg-emerald-900/20 text-primary font-bold' : 'border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700'}`}>
                                <div style={{ color: c.color }}><CategoryIcon iconName={c.icon} size={24} /></div>
                                <span className="truncate w-full text-center">{c.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Дата</label>
                <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" />
            </div>

            <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Примітка</label>
                <input type="text" value={note} onChange={(e) => setNote(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" placeholder="Додаткова інформація" />
            </div>

            <Button type="submit" fullWidth className="py-4 mt-4 text-lg">Зберегти</Button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Account, AccountType, Currency } from '../types';
import { Button } from './ui/Button';
import { X } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (account: Omit<Account, 'id'> | Account) => void;
  initialData?: Account;
}

const COLORS = ['#10b981', '#3b82f6', '#ef4444', '#f97316', '#8b5cf6', '#ec4899', '#000000', '#6b7280'];
const ACCOUNT_ICONS = ['wallet', 'credit-card', 'banknote', 'landmark', 'piggy-bank', 'coins', 'vault', 'briefcase'];

export const AccountModal: React.FC<AccountModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [name, setName] = useState('');
  const [currency, setCurrency] = useState<Currency>(Currency.UAH);
  const [initialBalance, setInitialBalance] = useState('0');
  const [type, setType] = useState<AccountType>(AccountType.CURRENT);
  const [color, setColor] = useState(COLORS[0]);
  const [icon, setIcon] = useState('wallet');
  const [currentRate, setCurrentRate] = useState('1');

  useEffect(() => {
    if (initialData) {
      setName(initialData.name);
      setCurrency(initialData.currency);
      setInitialBalance(initialData.initialBalance.toString());
      setType(initialData.type || AccountType.CURRENT);
      setColor(initialData.color);
      setIcon(initialData.icon || 'wallet');
      setCurrentRate(initialData.currentRate?.toString() || '1');
    } else {
      resetForm();
    }
  }, [initialData, isOpen]);

  const resetForm = () => {
    setName('');
    setCurrency(Currency.UAH);
    setInitialBalance('0');
    setType(AccountType.CURRENT);
    setColor(COLORS[0]);
    setIcon('wallet');
    setCurrentRate('1');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(initialData ? { ...initialData, name, currency, initialBalance: parseFloat(initialBalance), type, color, icon, currentRate: parseFloat(currentRate) } : { name, currency, initialBalance: parseFloat(initialBalance), type, color, icon, currentRate: parseFloat(currentRate) });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in p-0 sm:p-4">
      <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh] transition-colors">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100">{initialData ? 'Редагувати' : 'Новий рахунок'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-600"><X size={20} /></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Назва</label>
            <input type="text" required value={name} onChange={(e) => setName(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" placeholder="Назва рахунку" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Валюта</label>
              <select value={currency} onChange={(e) => { setCurrency(e.target.value as Currency); if (e.target.value === Currency.UAH) setCurrentRate('1'); }} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary">
                {Object.values(Currency).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Тип</label>
              <select value={type} onChange={(e) => setType(e.target.value as AccountType)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary">
                <option value={AccountType.CURRENT}>Поточний</option>
                <option value={AccountType.SAVINGS}>Заощадження</option>
                <option value={AccountType.DEBT}>Заборгованість</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Поч. баланс</label>
                <input type="number" step="0.01" value={initialBalance} onChange={(e) => setInitialBalance(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" />
             </div>
             <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Курс до UAH</label>
                <input type="number" step="0.01" value={currentRate} disabled={currency === Currency.UAH} onChange={(e) => setCurrentRate(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary disabled:opacity-50" />
             </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Іконка</label>
            <div className="flex flex-wrap gap-2">
              {ACCOUNT_ICONS.map((iconKey) => (
                <button key={iconKey} type="button" onClick={() => setIcon(iconKey)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${icon === iconKey ? 'bg-emerald-50 dark:bg-emerald-900/20 text-primary ring-2 ring-primary' : 'bg-gray-50 dark:bg-gray-900 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}><CategoryIcon iconName={iconKey} size={20} /></button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Колір</label>
            <div className="flex flex-wrap gap-2">
              {COLORS.map(c => (
                <button key={c} type="button" onClick={() => setColor(c)} className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${color === c ? 'ring-2 ring-offset-2 ring-gray-400 scale-110' : ''}`} style={{ backgroundColor: c }} />
              ))}
            </div>
          </div>

          <Button type="submit" fullWidth className="py-3 mt-4">Зберегти</Button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Category, TransactionType } from '../types';
import { Button } from './ui/Button';
import { X } from 'lucide-react';
import { CategoryIcon, ICON_MAP } from './CategoryIcon';

interface CategoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (category: Omit<Category, 'id'> | Category) => void;
  initialData?: Category;
  targetDate?: Date;
}

const COLORS = ['#ef4444', '#f97316', '#f59e0b', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#8b5cf6', '#ec4899', '#f43f5e', '#6b7280', '#000000'];

export const CategoryModal: React.FC<CategoryModalProps> = ({ isOpen, onClose, onSave, initialData, targetDate = new Date() }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [monthlyBudget, setMonthlyBudget] = useState('0');
  const [color, setColor] = useState(COLORS[0]);
  const [icon, setIcon] = useState('shopping-cart');

  const monthLabel = targetDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' });

  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7);
    const effectiveKey = keys.find(k => k <= targetKey);
    return effectiveKey ? category.budgetHistory[effectiveKey] : 0;
  };

  useEffect(() => {
    if (initialData) {
      setName(initialData.name);
      setType(initialData.type);
      setMonthlyBudget(getBudgetForDate(initialData, targetDate).toString());
      setColor(initialData.color);
      setIcon(ICON_MAP[initialData.icon] ? initialData.icon : 'shopping-cart');
    } else {
      resetForm();
    }
  }, [initialData, isOpen, targetDate]);

  const resetForm = () => {
    setName('');
    setType(TransactionType.EXPENSE);
    setMonthlyBudget('0');
    setColor(COLORS[0]);
    setIcon('shopping-cart');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const categoryData = { name, type, icon, color, monthlyBudget: parseFloat(monthlyBudget) || 0 };
    onSave(initialData ? { ...categoryData, id: initialData.id } : categoryData);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in p-0 sm:p-4">
      <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-t-2xl sm:rounded-2xl shadow-2xl p-6 overflow-y-auto max-h-[90vh] transition-colors">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100">{initialData ? 'Редагувати' : 'Нова категорія'}</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-600"><X size={20} /></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex p-1 bg-gray-100 dark:bg-gray-900 rounded-lg mb-4">
                <button type="button" onClick={() => setType(TransactionType.EXPENSE)} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${type === TransactionType.EXPENSE ? 'bg-white dark:bg-gray-800 shadow text-red-500' : 'text-gray-500 dark:text-gray-400'}`}>Витрати</button>
                <button type="button" onClick={() => setType(TransactionType.INCOME)} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${type === TransactionType.INCOME ? 'bg-white dark:bg-gray-800 shadow text-emerald-500' : 'text-gray-500 dark:text-gray-400'}`}>Доходи</button>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Назва</label>
            <input type="text" required value={name} onChange={(e) => setName(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" placeholder="Назва статті" />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Бюджет на {monthLabel}</label>
            <input type="number" step="0.01" value={monthlyBudget} onChange={(e) => setMonthlyBudget(e.target.value)} className="w-full p-3 bg-gray-50 dark:bg-gray-900 dark:text-white rounded-xl border-none focus:ring-2 focus:ring-primary" />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Колір</label>
            <div className="flex flex-wrap gap-2">
              {COLORS.map(c => (
                <button key={c} type="button" onClick={() => setColor(c)} className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${color === c ? 'ring-2 ring-offset-2 ring-gray-400 scale-110' : ''}`} style={{ backgroundColor: c }} />
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1">Іконка</label>
            <div className="grid grid-cols-6 gap-2 max-h-40 overflow-y-auto no-scrollbar">
              {Object.keys(ICON_MAP).filter(k => k !== 'transfer').map((key) => (
                <button key={key} type="button" onClick={() => setIcon(key)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${icon === key ? 'bg-emerald-50 dark:bg-emerald-900/20 text-primary ring-2 ring-primary' : 'bg-gray-50 dark:bg-gray-900 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}><CategoryIcon iconName={key} size={20} /></button>
              ))}
            </div>
          </div>

          <Button type="submit" fullWidth className="py-3 mt-4">Зберегти</Button>
        </form>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Transaction, Account, Category, TransactionType, UserSettings } from '../types';
import { Calendar, Search, Trash2, Pencil, Lock, LockOpen, Filter, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

export interface TransactionFilters {
  accountId?: string;
  categoryId?: string;
  date?: Date;
}

interface TransactionListProps {
  transactions: Transaction[];
  accounts: Account[];
  categories: Category[];
  onDelete: (id: string) => void;
  onEdit: (transaction: Transaction) => void;
  initialFilters?: TransactionFilters | null;
  onResetFilters?: () => void;
  settings: UserSettings;
}

export const TransactionList: React.FC<TransactionListProps> = ({ 
  transactions, accounts, categories, onDelete, onEdit, initialFilters, onResetFilters, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [filterMonth, setFilterMonth] = useState<Date>(new Date());
  const [filterAccountId, setFilterAccountId] = useState<string>('');
  const [filterCategoryId, setFilterCategoryId] = useState<string>('');

  useEffect(() => {
    if (initialFilters) {
      if (initialFilters.date) setFilterMonth(initialFilters.date);
      if (initialFilters.accountId !== undefined) setFilterAccountId(initialFilters.accountId);
      if (initialFilters.categoryId !== undefined) setFilterCategoryId(initialFilters.categoryId);
      if (initialFilters.accountId || initialFilters.categoryId) setIsFilterOpen(true);
      if (onResetFilters) onResetFilters();
    }
  }, [initialFilters, onResetFilters]);

  const resetFilters = () => {
    setFilterAccountId('');
    setFilterCategoryId('');
    // We don't close the panel immediately so user sees it reset
    if (onResetFilters) onResetFilters();
  };

  const hasActiveFilters = filterAccountId !== '' || filterCategoryId !== '';

  const prevMonth = () => setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() - 1, 1));
  const nextMonth = () => setFilterMonth(new Date(filterMonth.getFullYear(), filterMonth.getMonth() + 1, 1));

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const tDate = new Date(t.date);
      const sameMonth = tDate.getMonth() === filterMonth.getMonth() && tDate.getFullYear() === filterMonth.getFullYear();
      if (!sameMonth) return false;
      if (filterAccountId && t.accountId !== filterAccountId && t.toAccountId !== filterAccountId) return false;
      if (filterCategoryId && t.categoryId !== filterCategoryId) return false;
      return true;
    });
  }, [transactions, filterMonth, filterAccountId, filterCategoryId]);

  const sortedTransactions = useMemo(() => {
    return [...filteredTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredTransactions]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: Transaction[] } = {};
    sortedTransactions.forEach(t => {
      const dateKey = t.date.split('T')[0];
      if (!groups[dateKey]) groups[dateKey] = [];
      groups[dateKey].push(t);
    });
    return groups;
  }, [sortedTransactions]);

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) return 'Сьогодні';
    return date.toLocaleDateString('uk-UA', { weekday: 'long', day: 'numeric', month: 'long' });
  };

  const monthLabel = filterMonth.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');

  return (
    <div className="pb-32 pt-2 px-4 h-full overflow-y-auto no-scrollbar bg-gray-50 dark:bg-gray-900 transition-colors">
        {/* Month Selector (Budget Style) */}
        <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 mb-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
            <button onClick={prevMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronLeft size={24} /></button>
            <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100 capitalize">{monthLabel}</h2>
            <button onClick={nextMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronRight size={24} /></button>
        </div>

        {/* Controls Row */}
        <div className="flex items-center justify-between mb-4 px-1">
             <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-100">Транзакції</h2>
                <button 
                    onClick={() => setIsFilterOpen(!isFilterOpen)} 
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${
                        hasActiveFilters || isFilterOpen
                        ? 'bg-primary text-white shadow-md shadow-emerald-200 dark:shadow-emerald-900/20' 
                        : 'bg-white dark:bg-gray-800 text-gray-500 border border-gray-200 dark:border-gray-700'
                    }`}
                >
                    <Filter size={14} />
                    <span>Фільтр</span>
                    {hasActiveFilters && <div className="w-1.5 h-1.5 bg-white rounded-full ml-1" />}
                </button>
             </div>

             <button onClick={() => setIsEditMode(!isEditMode)} className={`p-2 rounded-full transition-all ${isEditMode ? 'bg-orange-100 dark:bg-orange-900/40 text-orange-600 dark:text-orange-400' : 'text-gray-400 dark:text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
             </button>
        </div>

        {/* Collapsible Filter Panel */}
        {isFilterOpen && (
            <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 mb-6 animate-fade-in transition-colors">
