                    }`}
                >
                    {isEditMode ? <LockOpen size={20} /> : <Lock size={20} />}
                </button>
            </div>

            {/* Horizontal Compact Filter Panel */}
            {isFilterOpen && (
                <div className="mt-2 animate-fade-in flex items-center gap-2">
