                 <div className="flex-1 min-w-0">
                    {isFilterOpen ? (
                        <div className="flex items-center gap-2 animate-fade-in">
                            <div className="relative flex-1 min-w-0">
                                <select value={filterAccountId} onChange={(e) => setFilterAccountId(e.target.value)}
                                    className={`w-full py-2.5 pl-3 pr-2 text-xs rounded-xl border appearance-none focus:ring-2 focus:ring-primary focus:outline-none transition-colors truncate ${filterAccountId ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800 text-blue-700 dark:text-blue-300 font-bold' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-600 dark:text-gray-400 font-medium'}`}
                                >
