                                    {accounts.map(a => (<option key={a.id} value={a.id}>{a.name}</option>))}
                                </select>
                            </div>
                            <div className="relative flex-1 min-w-0">
                                <select value={filterCategoryId} onChange={(e) => setFilterCategoryId(e.target.value)}
                                        className={`w-full py-2.5 pl-3 pr-2 text-xs rounded-xl border appearance-none focus:ring-2 focus:ring-primary focus:outline-none transition-colors truncate ${filterCategoryId ? 'bg-emerald-50 dark:bg-emerald-900/30 border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-300 font-bold' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-600 dark:text-gray-400 font-medium'}`}
                                >
                                    <option value="">Всі категорії</option>
