                           <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900 p-1 rounded-lg border border-gray-100 dark:border-gray-700">
                               <button onClick={(e) => { e.stopPropagation(); moveCategory(index, 'up', type); }} disabled={index === 0} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowUp size={14} strokeWidth={2.5} /></button>
                               <button onClick={(e) => { e.stopPropagation(); moveCategory(index, 'down', type); }} disabled={index === group.length - 1} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowDown size={14} strokeWidth={2.5} /></button>
                           </div>
                           <button onClick={(e) => { e.stopPropagation(); onEditCategory(category, currentDate); }} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={14} /></button>
                           <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDeleteCategory(category.id); }} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={14} /></button>
                       </div>
                   )}
               </div>
            </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
        {/* Fixed Header Section (Month Selector) */}
        <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
            <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
                <button onClick={prevMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronLeft size={24} /></button>
                <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100 capitalize">{periodLabel}</h2>
                <button onClick={nextMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronRight size={24} /></button>
            </div>
        </div>

        {/* Floating Controls */}
        <div className="absolute top-20 left-4 right-4 z-20 flex items-start justify-end pointer-events-none">
             <div className="flex items-center gap-2 pointer-events-auto shrink-0">
                 <button 
                    onClick={() => setIsEditMode(!isEditMode)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border ${
                        isEditMode
                        ? 'bg-orange-100/90 text-orange-600 border-orange-200' 
                        : 'bg-white/80 dark:bg-gray-800/80 text-gray-500 border-white/20 dark:border-gray-700/50'
                    }`}
                 >
                    {isEditMode ? <LockOpen size={18} /> : <Lock size={18} />}
                 </button>
             </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
           {/* Projected Balance Card */}
           <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors animate-fade-in">
               <div className={`text-4xl font-black tracking-tight ${projectedBalance >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                  {projectedBalance > 0 ? '+' : ''}{formatValue(projectedBalance)}
                  <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
               </div>
           </div>

           {renderCategoryGroup(TransactionType.EXPENSE, 'Витрати', TrendingDown, 'bg-red-500')}
           {renderCategoryGroup(TransactionType.INCOME, 'Доходи', TrendingUp, 'bg-emerald-500')}
           {isEditMode && (<button onClick={() => onAddCategory(currentDate)} className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-2xl flex items-center justify-center text-gray-500 dark:text-gray-400 transition-colors bg-white/50 dark:bg-gray-800/50 text-lg font-medium"><Plus size={24} className="mr-2" /> Додати статтю</button>)}
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, Wallet, Plus, Settings, Calculator } from 'lucide-react';
import { AppData, Transaction, Account, Category, UserSettings } from './types';
import { INITIAL_DATA } from './constants';
import { loadFromStorage, saveToStorage } from './services/storageService';
import { OverviewTab } from './components/OverviewTab';
import { TransactionList, TransactionFilters } from './components/TransactionList';
import { AccountsTab } from './components/AccountsTab';
import { BudgetTab } from './components/BudgetTab';
import { AddTransactionModal } from './components/AddTransactionModal';
import { AccountModal } from './components/AccountModal';
import { CategoryModal } from './components/CategoryModal';
import { DataManagementModal } from './components/DataManagementModal';

const generateId = () => Math.random().toString(36).substr(2, 9);

export default function App() {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'accounts' | 'budget'>('overview');
  const [data, setData] = useState<AppData>(INITIAL_DATA);

  const [transactionFilters, setTransactionFilters] = useState<TransactionFilters | null>(null);

  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);

  const [editingAccount, setEditingAccount] = useState<Account | undefined>(undefined);
  const [editingCategory, setEditingCategory] = useState<Category | undefined>(undefined);
  const [editingCategoryDate, setEditingCategoryDate] = useState<Date>(new Date());
  const [editingTransaction, setEditingTransaction] = useState<Transaction | undefined>(undefined);

  useEffect(() => {
    const loaded = loadFromStorage();

    if (!loaded.rates) loaded.rates = INITIAL_DATA.rates;
    if (!loaded.settings) loaded.settings = INITIAL_DATA.settings;

    if (loaded.accounts) {
       loaded.accounts = loaded.accounts.map(a => {
           let updated = { ...a };
           // @ts-ignore
           if (!updated.type) updated.type = 'CURRENT';
           if (!updated.currentRate) updated.currentRate = 1;
           if (!updated.icon) {
               const nameLower = updated.name.toLowerCase();
               if (nameLower.includes('карт') || nameLower.includes('card')) updated.icon = 'credit-card';
               else if (nameLower.includes('банк') || nameLower.includes('bank')) updated.icon = 'landmark';
               else if (nameLower.includes('usd') || nameLower.includes('eur')) updated.icon = 'banknote';
               else updated.icon = 'wallet';
           }
           return updated as Account;
       });
    }

    if(loaded.categories) {
        loaded.categories = loaded.categories.map(c => {
            const updated = { ...c };
            if (!updated.budgetHistory) {
                updated.budgetHistory = { '2023-01': c.monthlyBudget || 0 };
            }
            if (updated.monthlyBudget === undefined) updated.monthlyBudget = 0;
            return updated;
        });
    }

    setData(loaded);
  }, []);

  useEffect(() => {
    saveToStorage(data);
  }, [data]);

  // Sync theme with document class
  useEffect(() => {
    if (data.settings.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [data.settings.theme]);

  const saveTransaction = (t: Transaction | Omit<Transaction, 'id'>) => {
    if ('id' in t) {
        setData(prev => ({
            ...prev,
            transactions: prev.transactions.map(tr => tr.id === t.id ? t as Transaction : tr)
        }));
    } else {
        const newTransaction: Transaction = { ...t, id: generateId() };
        setData(prev => ({
          ...prev,
          transactions: [...prev.transactions, newTransaction]
        }));
    }
  };

  const openEditTransaction = (t: Transaction) => {
      setEditingTransaction(t);
      setIsTransactionModalOpen(true);
  };

  const deleteTransaction = (id: string) => {
    setData(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
  };

  const saveAccount = (accountData: Omit<Account, 'id'> | Account) => {
    if ('id' in accountData) {
        setData(prev => ({
            ...prev,
            accounts: prev.accounts.map(a => a.id === accountData.id ? accountData as Account : a)
        }));
    } else {
        const newAccount: Account = { ...accountData, id: generateId() };
        setData(prev => ({
            ...prev,
            accounts: [...prev.accounts, newAccount]
        }));
    }
  };

  const reorderAccounts = (newAccounts: Account[]) => {
      setData(prev => ({ ...prev, accounts: newAccounts }));
  };

  const toggleAccountVisibility = (account: Account) => {
      const updatedAccount = { ...account, isHidden: !account.isHidden };
      saveAccount(updatedAccount);
  };

  const deleteAccount = (id: string) => {
    setData(prev => ({
        ...prev,
        accounts: prev.accounts.filter(a => a.id !== id),
        transactions: prev.transactions.filter(t => t.accountId !== id)
    }));
  };

  const openAddAccount = () => {
    setEditingAccount(undefined);
    setIsAccountModalOpen(true);
  };

  const openEditAccount = (account: Account) => {
    setEditingAccount(account);
    setIsAccountModalOpen(true);
  };

  const saveCategory = (catData: Omit<Category, 'id'> | Category) => {
    const monthKey = editingCategoryDate.toISOString().slice(0, 7);
    if ('id' in catData) {
        setData(prev => ({
            ...prev,
            categories: prev.categories.map(c => {
                if (c.id === catData.id) {
                    const newBudget = catData.monthlyBudget;
                    const oldHistory = c.budgetHistory || {};
                    const newHistory = { ...oldHistory };
                    newHistory[monthKey] = newBudget;
                    Object.keys(newHistory).forEach(key => {
                        if (key > monthKey) delete newHistory[key];
                    });
                    return { ...catData, budgetHistory: newHistory } as Category;
                }
                return c;
            })
        }));
    } else {
        const newCat: Category = {
            ...catData,
            id: generateId(),
            budgetHistory: { [monthKey]: catData.monthlyBudget }
        } as Category;
        setData(prev => ({
            ...prev,
            categories: [...prev.categories, newCat]
        }));
    }
  };

  const reorderCategories = (newCategories: Category[]) => {
      setData(prev => ({ ...prev, categories: newCategories }));
  };

  const deleteCategory = (id: string) => {
    setData(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c.id !== id)
    }));
  };

  const openAddCategory = (date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(undefined);
      setIsCategoryModalOpen(true);
  };

  const openEditCategory = (cat: Category, date: Date) => {
      setEditingCategoryDate(date);
      setEditingCategory(cat);
      setIsCategoryModalOpen(true);
  };

  const handleDataImport = (newData: AppData) => {
      setData(newData);
      alert('Дані успішно імпортовано!');
  };

  const handleUpdateRates = (newRates: Record<string, number>) => {
      setData(prev => ({ ...prev, rates: newRates }));
  };

  const handleUpdateSettings = (newSettings: UserSettings) => {
      setData(prev => ({ ...prev, settings: newSettings }));
  };

  const handleOverviewCategoryClick = (categoryId: string, date: Date) => {
    setTransactionFilters({ categoryId, date, accountId: '' });
    setActiveTab('transactions');
  };

  const handleAccountSelect = (accountId: string) => {
    setTransactionFilters({ accountId, date: new Date(), categoryId: '' });
    setActiveTab('transactions');
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 dark:bg-gray-900 w-full overflow-hidden relative transition-colors duration-300">

      <main className="flex-1 overflow-hidden relative w-full pt-safe">
        {activeTab === 'overview' && (
            <OverviewTab 
                transactions={data.transactions} 
                categories={data.categories}
                onCategoryClick={handleOverviewCategoryClick}
                settings={data.settings}
            />
        )}
        {activeTab === 'transactions' && (
            <TransactionList 
                transactions={data.transactions} 
                accounts={data.accounts} 
                categories={data.categories} 
                onDelete={deleteTransaction}
                onEdit={openEditTransaction}
                initialFilters={transactionFilters}
                onResetFilters={() => setTransactionFilters(null)}
                settings={data.settings}
            />
        )}
        {activeTab === 'accounts' && (
            <AccountsTab 
                accounts={data.accounts} 
                transactions={data.transactions}
                rates={data.rates}
                onAddAccount={openAddAccount}
                onEditAccount={openEditAccount}
                onDeleteAccount={deleteAccount}
                onSelectAccount={handleAccountSelect}
                onReorderAccounts={reorderAccounts}
                onToggleVisibility={toggleAccountVisibility}
                onOpenSettings={() => setIsDataModalOpen(true)}
                settings={data.settings}
            />
        )}
        {activeTab === 'budget' && (
            <BudgetTab 
                categories={data.categories}
                onAddCategory={openAddCategory}
                onEditCategory={openEditCategory}
                onDeleteCategory={deleteCategory}
                onReorderCategories={reorderCategories}
                settings={data.settings}
            />
        )}
      </main>

      <div className="absolute bottom-28 right-4 z-30">
          <button 
            onClick={() => {
                setEditingTransaction(undefined);
                setIsTransactionModalOpen(true);
            }}
            className="w-14 h-14 bg-primary rounded-full shadow-lg shadow-emerald-300 dark:shadow-emerald-900/40 text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-transform"
          >
              <Plus size={32} />
          </button>
      </div>

      <nav className="bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 pb-safe pt-2 px-2 flex justify-between items-center z-20 pb-4 transition-colors">
        <button 
            onClick={() => setActiveTab('overview')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors flex-1 ${activeTab === 'overview' ? 'text-primary' : 'text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300'}`}
        >
            <LayoutDashboard size={22} strokeWidth={activeTab === 'overview' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Огляд</span>
        </button>
        <button 
            onClick={() => setActiveTab('transactions')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors flex-1 ${activeTab === 'transactions' ? 'text-primary' : 'text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300'}`}
        >
            <List size={22} strokeWidth={activeTab === 'transactions' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Транз.</span>
        </button>
        <button 
            onClick={() => setActiveTab('budget')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors flex-1 ${activeTab === 'budget' ? 'text-primary' : 'text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300'}`}
        >
            <Calculator size={22} strokeWidth={activeTab === 'budget' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Бюджет</span>
        </button>
        <button 
            onClick={() => setActiveTab('accounts')}
            className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-colors flex-1 ${activeTab === 'accounts' ? 'text-primary' : 'text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300'}`}
        >
            <Wallet size={22} strokeWidth={activeTab === 'accounts' ? 2.5 : 2} />
            <span className="text-[10px] font-medium">Рахунки</span>
        </button>
      </nav>

      <AddTransactionModal 
        isOpen={isTransactionModalOpen} 
        onClose={() => setIsTransactionModalOpen(false)} 
        onSave={saveTransaction}
        accounts={data.accounts}
        categories={data.categories}
        initialData={editingTransaction}
        rates={data.rates}
      />

      <AccountModal 
        isOpen={isAccountModalOpen}
        onClose={() => setIsAccountModalOpen(false)}
        onSave={saveAccount}
        initialData={editingAccount}
      />

      <CategoryModal 
        isOpen={isCategoryModalOpen}
        onClose={() => setIsCategoryModalOpen(false)}
        onSave={saveCategory}
        initialData={editingCategory}
        targetDate={editingCategoryDate}
      />

      <DataManagementModal
        isOpen={isDataModalOpen}
        onClose={() => setIsDataModalOpen(false)}
        currentData={data}
        onImport={handleDataImport}
        onUpdateRates={handleUpdateRates}
        onUpdateSettings={handleUpdateSettings}
      />
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType, UserSettings } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote, ArrowUp, ArrowDown, Eye, EyeOff, Wallet, PiggyBank, CreditCard, Settings } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  rates: Record<string, number>;
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
  onReorderAccounts: (accounts: Account[]) => void;
  onToggleVisibility: (account: Account) => void;
  onOpenSettings: () => void;
  settings: UserSettings;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, transactions, rates, onAddAccount, onEditAccount, onDeleteAccount, onSelectAccount, onReorderAccounts, onToggleVisibility, onOpenSettings, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const getBalance = (account: Account) => {
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);
    const totalIncome = sourceTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const totalExpense = sourceTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferOut = sourceTransactions.filter(t => t.type === TransactionType.TRANSFER).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferIn = destTransactions.reduce((sum, t) => {
        if (t.toAmount !== undefined) return sum + t.toAmount;
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = rates[account.currency] || 1; 
        return sum + (amountInUAH / destRate);
    }, 0);
    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const totalCapital = useMemo(() => {
    return accounts.reduce((sum, account) => {
        // If editing or hidden, we still count towards total unless that logic needs to change.
        // Usually total capital includes hidden accounts too, but let's stick to what's logical for user
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  }, [accounts, transactions, rates]);

  const groupAccounts = (type: AccountType) => accounts.filter(a => (a.type || AccountType.CURRENT) === type);

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        if (!isEditMode && account.isHidden) return sum;
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  };

  const moveAccount = (index: number, direction: 'up' | 'down', groupType: AccountType) => {
      const current = groupAccounts(AccountType.CURRENT);
      const savings = groupAccounts(AccountType.SAVINGS);
      const debt = groupAccounts(AccountType.DEBT);
      let targetGroup: Account[] = groupType === AccountType.CURRENT ? current : groupType === AccountType.SAVINGS ? savings : debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (title: string, type: AccountType, Icon: React.ElementType, headerColorClass: string) => {
    let group = groupAccounts(type);
    if (!isEditMode) group = group.filter(a => !a.isHidden);
    if (group.length === 0 && !isEditMode) return null;
    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden mb-6 animate-fade-in transition-colors">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
           <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}><Icon size={18} className={headerColorClass.replace('bg-', 'text-')} /></div>
                <div><h3 className="font-bold text-gray-800 dark:text-gray-200 text-base">{title}</h3></div>
           </div>
           <div className="text-right whitespace-nowrap">
                <span className="text-lg font-bold text-gray-900 dark:text-gray-100 leading-none">{formatValue(totalInUAH)} <span className="text-xs font-medium text-gray-400 ml-1">UAH</span></span>
           </div>
        </div>

        <div className="divide-y divide-gray-50 dark:divide-gray-700">
          {group.map((account, index) => {
            const rawBalance = getBalance(account);
            const balance = Math.abs(rawBalance) < 0.005 ? 0 : rawBalance;
            const isHidden = !!account.isHidden;
            const rate = rates[account.currency] || 1;
            const balanceInUAH = balance * rate;

            return (
              <div key={account.id} onClick={() => { if (!isEditMode) onSelectAccount(account.id); }}
                className={`p-3 flex items-center justify-between group hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors relative ${!isEditMode ? 'cursor-pointer active:bg-gray-100 dark:active:bg-gray-700' : ''} ${isHidden ? 'opacity-60 bg-gray-50 dark:bg-gray-900' : ''}`}
              >
                 <div className="flex items-center gap-3 overflow-hidden flex-1">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm ${isHidden ? 'bg-gray-400 dark:bg-gray-600' : ''}`} style={{ backgroundColor: isHidden ? undefined : account.color }}><CategoryIcon iconName={account.icon || 'wallet'} size={20} /></div>
                    <div className="min-w-0">
                        <div className={`font-bold text-sm truncate pr-2 ${isHidden ? 'text-gray-500' : 'text-gray-800 dark:text-gray-200'}`}>{account.name} {isHidden && <span className='text-[10px] font-normal text-gray-400 dark:text-gray-500 ml-2 border border-gray-200 dark:border-gray-700 px-1 rounded'>Приховано</span>}</div>
                         <div className="text-xs text-gray-400 dark:text-gray-500 font-medium">{account.currency}</div>
                    </div>
                 </div>

                 <div className="flex items-center gap-3 shrink-0">
                      {isEditMode ? (
                         <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200 dark:border-gray-700">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900 p-1 rounded-lg border border-gray-100 dark:border-gray-700">
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }} disabled={index === 0} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowUp size={14} strokeWidth={2.5} /></button>
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }} disabled={index === group.length - 1} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowDown size={14} strokeWidth={2.5} /></button>
                             </div>
                             <button onClick={(e) => { e.stopPropagation(); onToggleVisibility(account); }} className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${account.isHidden ? 'bg-gray-100 dark:bg-gray-700 text-gray-500' : 'bg-white dark:bg-gray-800 text-gray-400 hover:text-black dark:hover:text-white border border-gray-100 dark:border-gray-700'}`}>{account.isHidden ? <EyeOff size={14} /> : <Eye size={14} />}</button>
                             <button onClick={(e) => { e.stopPropagation(); onEditAccount(account); }} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={14} /></button>
                             <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDeleteAccount(account.id); }} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={14} /></button>
                         </div>
                      ) : (
                          <div className="flex flex-col items-end">
                              <div className={`font-bold text-sm whitespace-nowrap ${balance < 0 ? 'text-red-500 dark:text-red-400' : 'text-gray-900 dark:text-gray-100'}`}>{formatValue(balance)} <span className="text-xs font-normal text-gray-400 dark:text-gray-500 ml-1">{account.currency}</span></div>
                              {account.currency !== Currency.UAH && (<div className="text-[10px] text-gray-400 dark:text-gray-500 font-medium">{formatValue(balanceInUAH)} UAH</div>)}
                          </div>
                      )}
                 </div>
              </div>
            );})}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
        {/* Fixed Header Section (Empty Card + Settings) */}
        <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
            <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors h-[58px]">
                 <div className="flex-1"></div> {/* Spacer to push settings to right */}
                 <button onClick={onOpenSettings} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors">
                    <Settings size={24} />
                </button>
            </div>
        </div>

        {/* Floating Controls (Lock Button) */}
        <div className="absolute top-20 left-4 right-4 z-20 flex items-start justify-end pointer-events-none">
             <div className="flex items-center gap-2 pointer-events-auto shrink-0">
                 <button 
                    onClick={() => setIsEditMode(!isEditMode)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border ${
                        isEditMode
                        ? 'bg-orange-100/90 text-orange-600 border-orange-200' 
                        : 'bg-white/80 dark:bg-gray-800/80 text-gray-500 border-white/20 dark:border-gray-700/50'
                    }`}
                 >
                    {isEditMode ? <LockOpen size={18} /> : <Lock size={18} />}
                 </button>
             </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
            {/* Total Capital Card */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors animate-fade-in">
                <div className={`text-4xl font-black tracking-tight ${totalCapital >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                    {totalCapital > 0 ? '+' : ''}{formatValue(totalCapital)}
                    <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
                </div>
            </div>

            {renderAccountGroup('Поточні', AccountType.CURRENT, Wallet, 'bg-blue-500')}
            {renderAccountGroup('Заощадження', AccountType.SAVINGS, PiggyBank, 'bg-emerald-500')}
            {renderAccountGroup('Заборгованість', AccountType.DEBT, CreditCard, 'bg-red-500')}

            {isEditMode && (<button onClick={onAddAccount} className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-2xl flex items-center justify-center text-gray-500 dark:text-gray-400 hover:border-primary hover:text-primary transition-colors bg-white/50 dark:bg-gray-800/50 text-lg font-medium"><Plus size={24} className="mr-2" /> Додати рахунок</button>)}
        </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType, UserSettings } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote, ArrowUp, ArrowDown, Eye, EyeOff, Wallet, PiggyBank, CreditCard, Settings } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  rates: Record<string, number>;
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
  onReorderAccounts: (accounts: Account[]) => void;
  onToggleVisibility: (account: Account) => void;
  onOpenSettings: () => void;
  settings: UserSettings;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, transactions, rates, onAddAccount, onEditAccount, onDeleteAccount, onSelectAccount, onReorderAccounts, onToggleVisibility, onOpenSettings, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const getBalance = (account: Account) => {
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);
    const totalIncome = sourceTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const totalExpense = sourceTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferOut = sourceTransactions.filter(t => t.type === TransactionType.TRANSFER).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferIn = destTransactions.reduce((sum, t) => {
        if (t.toAmount !== undefined) return sum + t.toAmount;
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = rates[account.currency] || 1; 
        return sum + (amountInUAH / destRate);
    }, 0);
    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const totalCapital = useMemo(() => {
    return accounts.reduce((sum, account) => {
        // If editing or hidden, we still count towards total unless that logic needs to change.
        // Usually total capital includes hidden accounts too, but let's stick to what's logical for user
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  }, [accounts, transactions, rates]);

  const groupAccounts = (type: AccountType) => accounts.filter(a => (a.type || AccountType.CURRENT) === type);

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        if (!isEditMode && account.isHidden) return sum;
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  };

  const moveAccount = (index: number, direction: 'up' | 'down', groupType: AccountType) => {
      const current = groupAccounts(AccountType.CURRENT);
      const savings = groupAccounts(AccountType.SAVINGS);
      const debt = groupAccounts(AccountType.DEBT);
      let targetGroup: Account[] = groupType === AccountType.CURRENT ? current : groupType === AccountType.SAVINGS ? savings : debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (title: string, type: AccountType, Icon: React.ElementType, headerColorClass: string) => {
    let group = groupAccounts(type);
    if (!isEditMode) group = group.filter(a => !a.isHidden);
    if (group.length === 0 && !isEditMode) return null;
    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden mb-6 animate-fade-in transition-colors">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
           <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}><Icon size={18} className={headerColorClass.replace('bg-', 'text-')} /></div>
                <div><h3 className="font-bold text-gray-800 dark:text-gray-200 text-base">{title}</h3></div>
           </div>
           <div className="text-right whitespace-nowrap">
                <span className="text-lg font-bold text-gray-900 dark:text-gray-100 leading-none">{formatValue(totalInUAH)} <span className="text-xs font-medium text-gray-400 ml-1">UAH</span></span>
           </div>
        </div>

        <div className="divide-y divide-gray-50 dark:divide-gray-700">
          {group.map((account, index) => {
            const rawBalance = getBalance(account);
            const balance = Math.abs(rawBalance) < 0.005 ? 0 : rawBalance;
            const isHidden = !!account.isHidden;
            const rate = rates[account.currency] || 1;
            const balanceInUAH = balance * rate;

            return (
              <div key={account.id} onClick={() => { if (!isEditMode) onSelectAccount(account.id); }}
                className={`p-3 flex items-center justify-between group hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors relative ${!isEditMode ? 'cursor-pointer active:bg-gray-100 dark:active:bg-gray-700' : ''} ${isHidden ? 'opacity-60 bg-gray-50 dark:bg-gray-900' : ''}`}
              >
                 <div className="flex items-center gap-3 overflow-hidden flex-1">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm ${isHidden ? 'bg-gray-400 dark:bg-gray-600' : ''}`} style={{ backgroundColor: isHidden ? undefined : account.color }}><CategoryIcon iconName={account.icon || 'wallet'} size={20} /></div>
                    <div className="min-w-0">
                        <div className={`font-bold text-sm truncate pr-2 ${isHidden ? 'text-gray-500' : 'text-gray-800 dark:text-gray-200'}`}>{account.name} {isHidden && <span className='text-[10px] font-normal text-gray-400 dark:text-gray-500 ml-2 border border-gray-200 dark:border-gray-700 px-1 rounded'>Приховано</span>}</div>
                         <div className="text-xs text-gray-400 dark:text-gray-500 font-medium">{account.currency}</div>
                    </div>
                 </div>

                 <div className="flex items-center gap-3 shrink-0">
                      {isEditMode ? (
                         <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200 dark:border-gray-700">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900 p-1 rounded-lg border border-gray-100 dark:border-gray-700">
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }} disabled={index === 0} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowUp size={14} strokeWidth={2.5} /></button>
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }} disabled={index === group.length - 1} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowDown size={14} strokeWidth={2.5} /></button>
                             </div>
                             <button onClick={(e) => { e.stopPropagation(); onToggleVisibility(account); }} className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${account.isHidden ? 'bg-gray-100 dark:bg-gray-700 text-gray-500' : 'bg-white dark:bg-gray-800 text-gray-400 hover:text-black dark:hover:text-white border border-gray-100 dark:border-gray-700'}`}>{account.isHidden ? <EyeOff size={14} /> : <Eye size={14} />}</button>
                             <button onClick={(e) => { e.stopPropagation(); onEditAccount(account); }} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={14} /></button>
                             <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDeleteAccount(account.id); }} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={14} /></button>
                         </div>
                      ) : (
                          <div className="flex flex-col items-end">
                              <div className={`font-bold text-sm whitespace-nowrap ${balance < 0 ? 'text-red-500 dark:text-red-400' : 'text-gray-900 dark:text-gray-100'}`}>{formatValue(balance)} <span className="text-xs font-normal text-gray-400 dark:text-gray-500 ml-1">{account.currency}</span></div>
                              {account.currency !== Currency.UAH && (<div className="text-[10px] text-gray-400 dark:text-gray-500 font-medium">{formatValue(balanceInUAH)} UAH</div>)}
                          </div>
                      )}
                 </div>
              </div>
            );})}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
        {/* Fixed Header Section (Empty Card + Settings) */}
        <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
            <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
                 <div className="flex-1"></div> {/* Spacer to push settings to right */}
                 <button onClick={onOpenSettings} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors">
                    <Settings size={24} />
                </button>
            </div>
        </div>

        {/* Floating Controls (Lock Button) */}
        <div className="absolute top-20 left-4 right-4 z-20 flex items-start justify-end pointer-events-none">
             <div className="flex items-center gap-2 pointer-events-auto shrink-0">
                 <button 
                    onClick={() => setIsEditMode(!isEditMode)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border ${
                        isEditMode
                        ? 'bg-orange-100/90 text-orange-600 border-orange-200' 
                        : 'bg-white/80 dark:bg-gray-800/80 text-gray-500 border-white/20 dark:border-gray-700/50'
                    }`}
                 >
                    {isEditMode ? <LockOpen size={18} /> : <Lock size={18} />}
                 </button>
             </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
            {/* Total Capital Card */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors animate-fade-in">
                <div className={`text-4xl font-black tracking-tight ${totalCapital >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                    {totalCapital > 0 ? '+' : ''}{formatValue(totalCapital)}
                    <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
                </div>
            </div>

            {renderAccountGroup('Поточні', AccountType.CURRENT, Wallet, 'bg-blue-500')}
            {renderAccountGroup('Заощадження', AccountType.SAVINGS, PiggyBank, 'bg-emerald-500')}
            {renderAccountGroup('Заборгованість', AccountType.DEBT, CreditCard, 'bg-red-500')}

            {isEditMode && (<button onClick={onAddAccount} className="w-full py-4 mt-2 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-2xl flex items-center justify-center text-gray-500 dark:text-gray-400 hover:border-primary hover:text-primary transition-colors bg-white/50 dark:bg-gray-800/50 text-lg font-medium"><Plus size={24} className="mr-2" /> Додати рахунок</button>)}
        </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Transaction, Category, TransactionType, UserSettings } from '../types';
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface OverviewTabProps {
  transactions: Transaction[];
  categories: Category[];
  onCategoryClick: (categoryId: string, date: Date) => void;
  settings: UserSettings;
}

export const OverviewTab: React.FC<OverviewTabProps> = ({ transactions, categories, onCategoryClick, settings }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => {
    return currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', '');
  }, [currentDate]);

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7);
    const effectiveKey = keys.find(k => k <= targetKey);
    return effectiveKey ? category.budgetHistory[effectiveKey] : 0;
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
    });
  }, [transactions, currentDate]);

  const stats = useMemo(() => {
    let income = 0;
    let expense = 0;
    const categoryTotals: { [key: string]: number } = {};

    filteredTransactions.forEach(t => {
      const amountInBase = t.amount * t.exchangeRate;
      if (t.type === TransactionType.INCOME) income += amountInBase;
      else if (t.type === TransactionType.EXPENSE) expense += amountInBase;
      if (!categoryTotals[t.categoryId]) categoryTotals[t.categoryId] = 0;
      categoryTotals[t.categoryId] += amountInBase;
    });

    const expenseCategories = categories.filter(c => c.type === TransactionType.EXPENSE);
    const totalBudgetExpense = expenseCategories.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);
    const expenseData = expenseCategories.map(cat => ({
        id: cat.id, name: cat.name, value: categoryTotals[cat.id] || 0, budget: getBudgetForDate(cat, currentDate), color: cat.color, icon: cat.icon
    }));

    const incomeCategories = categories.filter(c => c.type === TransactionType.INCOME);
    const totalBudgetIncome = incomeCategories.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);
    const incomeData = incomeCategories.map(cat => ({
        id: cat.id, name: cat.name, value: categoryTotals[cat.id] || 0, budget: getBudgetForDate(cat, currentDate), color: cat.color, icon: cat.icon
    }));

    return { income, expense, expenseData, totalBudgetExpense, incomeData, totalBudgetIncome };
  }, [filteredTransactions, categories, currentDate]);

  const balance = stats.income - stats.expense;

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const renderCategoryList = (
      title: string, 
      data: typeof stats.expenseData, 
      totalActual: number, 
      totalBudget: number,
      HeaderIcon: React.ElementType,
      headerColorClass: string
  ) => {
      return (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden mb-6 animate-fade-in transition-colors">
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
               <div className="flex items-center gap-2">
                    <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}>
                        <HeaderIcon size={18} className={headerColorClass.replace('bg-', 'text-')} />
                    </div>
                    <div>
                        <h3 className="font-bold text-gray-800 dark:text-gray-200 text-base">{title}</h3>
                    </div>
               </div>
               <div className="text-right whitespace-nowrap">
                    <span className="text-lg font-bold text-gray-900 dark:text-gray-100 leading-none">
                        {formatValue(totalActual)} 
                    </span>
                    {totalBudget > 0 && (
                        <>
                            <span className="text-gray-400 dark:text-gray-600 mx-1 text-lg font-light">/</span>
                            <span className="text-gray-900 dark:text-gray-300 text-lg font-bold">
                                {formatValue(totalBudget)}
                            </span>
                        </>
                    )}
               </div>
            </div>

            <div className="divide-y divide-gray-50 dark:divide-gray-700">
                {data.map((item) => {
                    const percent = item.budget > 0 ? (item.value / item.budget) * 100 : 0;
                    return (
                        <div 
                          key={item.id} 
                          className="p-3 hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer transition-colors active:bg-gray-100 dark:active:bg-gray-700"
                          onClick={() => onCategoryClick(item.id, currentDate)}
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shadow-sm shrink-0" style={{ backgroundColor: item.color }}>
                                   <CategoryIcon iconName={item.icon} size={20} />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center mb-1">
                                        <div className="font-bold text-gray-800 dark:text-gray-200 text-sm truncate pr-2">{item.name}</div>
                                        <div className="text-right whitespace-nowrap">
                                            <span className="font-bold text-gray-900 dark:text-gray-100 text-sm">{formatValue(item.value)}</span>
                                            {item.budget > 0 && (
                                                <>
                                                    <span className="text-gray-400 dark:text-gray-600 mx-1 text-sm font-light">/</span>
                                                    <span className="text-gray-900 dark:text-gray-300 font-bold text-sm">{formatValue(item.budget)}</span>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                    <div className="h-1.5 w-full bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-500" style={{ width: item.budget > 0 ? `${Math.min(percent, 100)}%` : '0%', backgroundColor: item.color }} />
                                    </div>
                                </div>
                            </div>
                        </div>
                    );
                })}
                 {data.length === 0 && (
                    <div className="p-4 text-center text-gray-400 dark:text-gray-600 text-xs italic">Категорії відсутні</div>
                )}
            </div>
        </div>
      );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
      {/* Fixed Header Section */}
      <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
        <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
            <button onClick={prevMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronLeft size={24} /></button>
            <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100 capitalize">{periodLabel}</h2>
            <button onClick={nextMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronRight size={24} /></button>
        </div>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
        <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors">
            <div className={`text-4xl font-black tracking-tight ${balance >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                {balance > 0 ? '+' : ''}{formatValue(balance)}
                <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
            </div>
        </div>

        {renderCategoryList('Витрати', stats.expenseData, stats.expense, stats.totalBudgetExpense, TrendingDown, 'bg-red-500')}
        {renderCategoryList('Доходи', stats.incomeData, stats.income, stats.totalBudgetIncome, TrendingUp, 'bg-emerald-500')}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Category, TransactionType, UserSettings } from '../types';
import { Lock, LockOpen, Plus, Trash2, Pencil, TrendingUp, TrendingDown, ArrowUp, ArrowDown, ChevronLeft, ChevronRight } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface BudgetTabProps {
  categories: Category[];
  onAddCategory: (date: Date) => void;
  onEditCategory: (category: Category, date: Date) => void;
  onDeleteCategory: (id: string) => void;
  onReorderCategories: (categories: Category[]) => void;
  settings: UserSettings;
}

export const BudgetTab: React.FC<BudgetTabProps> = ({ 
  categories, onAddCategory, onEditCategory, onDeleteCategory, onReorderCategories, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date());

  const periodLabel = useMemo(() => currentDate.toLocaleDateString('uk-UA', { month: 'long', year: 'numeric' }).replace(' р.', ''), [currentDate]);
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const getBudgetForDate = (category: Category, date: Date): number => {
    if (!category.budgetHistory) return category.monthlyBudget || 0;
    const keys = Object.keys(category.budgetHistory).sort().reverse();
    const targetKey = date.toISOString().slice(0, 7);
    const effectiveKey = keys.find(k => k <= targetKey);
    return effectiveKey ? category.budgetHistory[effectiveKey] : 0;
  };

  const { projectedBalance } = useMemo(() => {
    const income = categories
        .filter(c => c.type === TransactionType.INCOME)
        .reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);
    const expense = categories
        .filter(c => c.type === TransactionType.EXPENSE)
        .reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);
    return { projectedBalance: income - expense };
  }, [categories, currentDate]);

  const moveCategory = (index: number, direction: 'up' | 'down', groupType: TransactionType) => {
    const income = categories.filter(c => c.type === TransactionType.INCOME);
    const expense = categories.filter(c => c.type === TransactionType.EXPENSE);
    const targetGroup = groupType === TransactionType.INCOME ? income : expense;
    if (direction === 'up') {
        if (index === 0) return;
        [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
    } else {
        if (index === targetGroup.length - 1) return;
         [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
    }
    onReorderCategories([...income, ...expense]);
  };

  const renderCategoryGroup = (type: TransactionType, title: string, Icon: React.ElementType, headerColorClass: string) => {
    const group = categories.filter(c => c.type === type);
    const totalBudget = group.reduce((sum, c) => sum + getBudgetForDate(c, currentDate), 0);

    return (
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden mb-6 animate-fade-in transition-colors">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
           <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}><Icon size={18} className={headerColorClass.replace('bg-', 'text-')} /></div>
                <div><h3 className="font-bold text-gray-800 dark:text-gray-200 text-base">{title}</h3></div>
           </div>
           <div className="text-right whitespace-nowrap">
                <span className="text-lg font-bold text-gray-900 dark:text-gray-100 leading-none">{formatValue(totalBudget)}</span>
           </div>
        </div>

        <div className="divide-y divide-gray-50 dark:divide-gray-700">
          {group.map((category, index) => {
            const budgetAmount = getBudgetForDate(category, currentDate);
            return (
            <div key={category.id} className="p-3 flex items-center justify-between group hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors relative" onClick={() => isEditMode ? onEditCategory(category, currentDate) : null}>
               <div className="flex items-center gap-3 overflow-hidden flex-1">
                  <div className="w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm" style={{ backgroundColor: category.color }}><CategoryIcon iconName={category.icon} size={20} /></div>
                  <div className="font-bold text-gray-800 dark:text-gray-200 text-sm truncate pr-2">{category.name}</div>
               </div>
               <div className="flex items-center gap-3 shrink-0">
                   {!isEditMode && <div className="text-sm font-bold text-gray-900 dark:text-gray-100 whitespace-nowrap">{formatValue(budgetAmount)}</div>}
                   {isEditMode && (
                       <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200 dark:border-gray-700">
                           <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900 p-1 rounded-lg border border-gray-100 dark:border-gray-700">
                               <button onClick={(e) => { e.stopPropagation(); moveCategory(index, 'up', type); }} disabled={index === 0} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowUp size={14} strokeWidth={2.5} /></button>
                               <button onClick={(e) => { e.stopPropagation(); moveCategory(index, 'down', type); }} disabled={index === group.length - 1} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowDown size={14} strokeWidth={2.5} /></button>
                           </div>
                           <button onClick={(e) => { e.stopPropagation(); onEditCategory(category, currentDate); }} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={14} /></button>
                           <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDeleteCategory(category.id); }} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={14} /></button>
                       </div>
                   )}
               </div>
            </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
        {/* Fixed Header Section (Month Selector) */}
        <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
            <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
                <button onClick={prevMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronLeft size={24} /></button>
                <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100 capitalize">{periodLabel}</h2>
                <button onClick={nextMonth} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors"><ChevronRight size={24} /></button>
            </div>
        </div>

        {/* Floating Controls */}
        <div className="absolute top-20 left-4 right-4 z-20 flex items-start justify-end pointer-events-none">
             <div className="flex items-center gap-2 pointer-events-auto shrink-0">
                 {isEditMode && (
                     <button 
                        onClick={() => onAddCategory(currentDate)}
                        className="w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border bg-primary/90 text-white border-primary/20 animate-fade-in"
                     >
                        <Plus size={18} />
                     </button>
                 )}
                 <button 
                    onClick={() => setIsEditMode(!isEditMode)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border ${
                        isEditMode
                        ? 'bg-orange-100/90 text-orange-600 border-orange-200' 
                        : 'bg-white/80 dark:bg-gray-800/80 text-gray-500 border-white/20 dark:border-gray-700/50'
                    }`}
                 >
                    {isEditMode ? <LockOpen size={18} /> : <Lock size={18} />}
                 </button>
             </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
           {/* Projected Balance Card */}
           <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors animate-fade-in">
               <div className={`text-4xl font-black tracking-tight ${projectedBalance >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                  {projectedBalance > 0 ? '+' : ''}{formatValue(projectedBalance)}
                  <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
               </div>
           </div>

           {renderCategoryGroup(TransactionType.EXPENSE, 'Витрати', TrendingDown, 'bg-red-500')}
           {renderCategoryGroup(TransactionType.INCOME, 'Доходи', TrendingUp, 'bg-emerald-500')}
        </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Account, AccountType, Currency, Transaction, TransactionType, UserSettings } from '../types';
import { Lock, LockOpen, Trash2, Pencil, Plus, Banknote, ArrowUp, ArrowDown, Eye, EyeOff, Wallet, PiggyBank, CreditCard, Settings } from 'lucide-react';
import { CategoryIcon } from './CategoryIcon';

interface AccountsTabProps {
  accounts: Account[];
  transactions: Transaction[];
  rates: Record<string, number>;
  onAddAccount: () => void;
  onEditAccount: (account: Account) => void;
  onDeleteAccount: (id: string) => void;
  onSelectAccount: (accountId: string) => void;
  onReorderAccounts: (accounts: Account[]) => void;
  onToggleVisibility: (account: Account) => void;
  onOpenSettings: () => void;
  settings: UserSettings;
}

export const AccountsTab: React.FC<AccountsTabProps> = ({ 
  accounts, transactions, rates, onAddAccount, onEditAccount, onDeleteAccount, onSelectAccount, onReorderAccounts, onToggleVisibility, onOpenSettings, settings
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const formatValue = (val: number) => {
    const isInteger = settings.numberFormat === 'integer';
    return val.toLocaleString('uk-UA', {
        minimumFractionDigits: isInteger ? 0 : 2,
        maximumFractionDigits: isInteger ? 0 : 2
    });
  };

  const getBalance = (account: Account) => {
    const sourceTransactions = transactions.filter(t => t.accountId === account.id);
    const destTransactions = transactions.filter(t => t.type === TransactionType.TRANSFER && t.toAccountId === account.id);
    const totalIncome = sourceTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const totalExpense = sourceTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferOut = sourceTransactions.filter(t => t.type === TransactionType.TRANSFER).reduce((sum, t) => sum + t.amount, 0);
    const totalTransferIn = destTransactions.reduce((sum, t) => {
        if (t.toAmount !== undefined) return sum + t.toAmount;
        const amountInUAH = t.amount * t.exchangeRate;
        const destRate = rates[account.currency] || 1; 
        return sum + (amountInUAH / destRate);
    }, 0);
    return account.initialBalance + totalIncome - totalExpense - totalTransferOut + totalTransferIn;
  };

  const totalCapital = useMemo(() => {
    return accounts.reduce((sum, account) => {
        // If editing or hidden, we still count towards total unless that logic needs to change.
        // Usually total capital includes hidden accounts too, but let's stick to what's logical for user
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  }, [accounts, transactions, rates]);

  const groupAccounts = (type: AccountType) => accounts.filter(a => (a.type || AccountType.CURRENT) === type);

  const getGroupTotalInUAH = (type: AccountType) => {
    const group = groupAccounts(type);
    return group.reduce((sum, account) => {
        if (!isEditMode && account.isHidden) return sum;
        const balance = getBalance(account);
        const rate = rates[account.currency] || 1;
        return sum + (balance * rate);
    }, 0);
  };

  const moveAccount = (index: number, direction: 'up' | 'down', groupType: AccountType) => {
      const current = groupAccounts(AccountType.CURRENT);
      const savings = groupAccounts(AccountType.SAVINGS);
      const debt = groupAccounts(AccountType.DEBT);
      let targetGroup: Account[] = groupType === AccountType.CURRENT ? current : groupType === AccountType.SAVINGS ? savings : debt;

      if (direction === 'up') {
          if (index === 0) return;
          [targetGroup[index - 1], targetGroup[index]] = [targetGroup[index], targetGroup[index - 1]];
      } else {
          if (index === targetGroup.length - 1) return;
          [targetGroup[index], targetGroup[index + 1]] = [targetGroup[index + 1], targetGroup[index]];
      }
      onReorderAccounts([...current, ...savings, ...debt]);
  };

  const renderAccountGroup = (title: string, type: AccountType, Icon: React.ElementType, headerColorClass: string) => {
    let group = groupAccounts(type);
    if (!isEditMode) group = group.filter(a => !a.isHidden);
    if (group.length === 0 && !isEditMode) return null;
    const totalInUAH = getGroupTotalInUAH(type);

    return (
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden mb-6 animate-fade-in transition-colors">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
           <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-lg ${headerColorClass} bg-opacity-10`}><Icon size={18} className={headerColorClass.replace('bg-', 'text-')} /></div>
                <div><h3 className="font-bold text-gray-800 dark:text-gray-200 text-base">{title}</h3></div>
           </div>
           <div className="text-right whitespace-nowrap">
                <span className="text-lg font-bold text-gray-900 dark:text-gray-100 leading-none">{formatValue(totalInUAH)} <span className="text-xs font-medium text-gray-400 ml-1">UAH</span></span>
           </div>
        </div>

        <div className="divide-y divide-gray-50 dark:divide-gray-700">
          {group.map((account, index) => {
            const rawBalance = getBalance(account);
            const balance = Math.abs(rawBalance) < 0.005 ? 0 : rawBalance;
            const isHidden = !!account.isHidden;
            const rate = rates[account.currency] || 1;
            const balanceInUAH = balance * rate;

            return (
              <div key={account.id} onClick={() => { if (!isEditMode) onSelectAccount(account.id); }}
                className={`p-3 flex items-center justify-between group hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors relative ${!isEditMode ? 'cursor-pointer active:bg-gray-100 dark:active:bg-gray-700' : ''} ${isHidden ? 'opacity-60 bg-gray-50 dark:bg-gray-900' : ''}`}
              >
                 <div className="flex items-center gap-3 overflow-hidden flex-1">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 shadow-sm ${isHidden ? 'bg-gray-400 dark:bg-gray-600' : ''}`} style={{ backgroundColor: isHidden ? undefined : account.color }}><CategoryIcon iconName={account.icon || 'wallet'} size={20} /></div>
                    <div className="min-w-0">
                        <div className={`font-bold text-sm truncate pr-2 ${isHidden ? 'text-gray-500' : 'text-gray-800 dark:text-gray-200'}`}>{account.name} {isHidden && <span className='text-[10px] font-normal text-gray-400 dark:text-gray-500 ml-2 border border-gray-200 dark:border-gray-700 px-1 rounded'>Приховано</span>}</div>
                         <div className="text-xs text-gray-400 dark:text-gray-500 font-medium">{account.currency}</div>
                    </div>
                 </div>

                 <div className="flex items-center gap-3 shrink-0">
                      {isEditMode ? (
                         <div className="flex items-center gap-2 ml-2 pl-3 border-l border-gray-200 dark:border-gray-700">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900 p-1 rounded-lg border border-gray-100 dark:border-gray-700">
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'up', type); }} disabled={index === 0} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowUp size={14} strokeWidth={2.5} /></button>
                                 <button onClick={(e) => { e.stopPropagation(); moveAccount(index, 'down', type); }} disabled={index === group.length - 1} className="w-7 h-7 flex items-center justify-center text-gray-500 disabled:opacity-30 transition-all"><ArrowDown size={14} strokeWidth={2.5} /></button>
                             </div>
                             <button onClick={(e) => { e.stopPropagation(); onToggleVisibility(account); }} className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${account.isHidden ? 'bg-gray-100 dark:bg-gray-700 text-gray-500' : 'bg-white dark:bg-gray-800 text-gray-400 hover:text-black dark:hover:text-white border border-gray-100 dark:border-gray-700'}`}>{account.isHidden ? <EyeOff size={14} /> : <Eye size={14} />}</button>
                             <button onClick={(e) => { e.stopPropagation(); onEditAccount(account); }} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-full"><Pencil size={14} /></button>
                             <button onClick={(e) => { e.stopPropagation(); if(window.confirm('Видалити?')) onDeleteAccount(account.id); }} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/40 text-red-600 dark:text-red-400 rounded-full"><Trash2 size={14} /></button>
                         </div>
                      ) : (
                          <div className="flex flex-col items-end">
                              <div className={`font-bold text-sm whitespace-nowrap ${balance < 0 ? 'text-red-500 dark:text-red-400' : 'text-gray-900 dark:text-gray-100'}`}>{formatValue(balance)} <span className="text-xs font-normal text-gray-400 dark:text-gray-500 ml-1">{account.currency}</span></div>
                              {account.currency !== Currency.UAH && (<div className="text-[10px] text-gray-400 dark:text-gray-500 font-medium">{formatValue(balanceInUAH)} UAH</div>)}
                          </div>
                      )}
                 </div>
              </div>
            );})}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-900 transition-colors relative">
        {/* Fixed Header Section (Empty Card + Settings) */}
        <div className="flex-none px-4 pt-2 pb-2 bg-gray-50 dark:bg-gray-900 z-30 relative">
            <div className="flex items-center justify-between bg-white dark:bg-gray-800 p-2 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
                 <div className="flex-1"></div> {/* Spacer to push settings to right */}
                 <button onClick={onOpenSettings} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-600 dark:text-gray-400 transition-colors">
                    <Settings size={24} />
                </button>
            </div>
        </div>

        {/* Floating Controls (Lock Button) */}
        <div className="absolute top-20 left-4 right-4 z-20 flex items-start justify-end pointer-events-none">
             <div className="flex items-center gap-2 pointer-events-auto shrink-0">
                 {isEditMode && (
                     <button 
                        onClick={onAddAccount}
                        className="w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border bg-primary/90 text-white border-primary/20 animate-fade-in"
                     >
                        <Plus size={18} />
                     </button>
                 )}
                 <button 
                    onClick={() => setIsEditMode(!isEditMode)}
                    className={`w-10 h-10 flex items-center justify-center rounded-xl shadow-lg backdrop-blur-md transition-all border ${
                        isEditMode
                        ? 'bg-orange-100/90 text-orange-600 border-orange-200' 
                        : 'bg-white/80 dark:bg-gray-800/80 text-gray-500 border-white/20 dark:border-gray-700/50'
                    }`}
                 >
                    {isEditMode ? <LockOpen size={18} /> : <Lock size={18} />}
                 </button>
             </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-32 pt-0">
            {/* Total Capital Card */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700 mb-4 text-center transition-colors animate-fade-in">
                <div className={`text-4xl font-black tracking-tight ${totalCapital >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-500 dark:text-red-400'}`}>
                    {totalCapital > 0 ? '+' : ''}{formatValue(totalCapital)}
                    <span className="text-lg text-gray-400 dark:text-gray-500 font-medium ml-2">UAH</span>
                </div>
            </div>

            {renderAccountGroup('Поточні', AccountType.CURRENT, Wallet, 'bg-blue-500')}
            {renderAccountGroup('Заощадження', AccountType.SAVINGS, PiggyBank, 'bg-emerald-500')}
            {renderAccountGroup('Заборгованість', AccountType.DEBT, CreditCard, 'bg-red-500')}
        </div>
    </div>
  );
};
